// The Spanish of What's new, what each version changed (lib/whats-new.ts, app/whats-new.tsx) (i18n/es/index.ts).
export const whatsNew: Record<string, string> = {
  "**The day stands out in every chat**: over the first message of each day, groups and Chat with myself too, the day shows in bold between two lines: **Today**, **Yesterday**, the weekday within the last week, and before that the weekday and date. See [Chat through a relay](#relay).":
    "**El día se ve bien en cada chat**: encima del primer mensaje de cada día, también en los grupos y en Chat conmigo, el día aparece en negrita entre dos líneas: **Hoy**, **Ayer**, el día de la semana dentro de la última semana y, antes, el día de la semana con la fecha. Consulta [Chatear a través de un relay](#relay).",
  "**The microphone writes, if you like**: tap the microphone beside the message field and choose **Speak to write**, and from then on holding it writes what you say into the field, until you choose **Voice message** again. The choice stays for every chat. See [Chat through a relay](#relay).": "**El micrófono escribe, si quieres**: toca el micrófono junto al campo del mensaje y elige **Habla para escribir**, y desde entonces, al mantenerlo pulsado, escribe en el campo lo que dices, hasta que elijas de nuevo **Mensaje de voz**. La elección vale para cada chat. Consulta [Chatear a través de un relay](#relay).",
  "**Ways on home**: once a relay is set, the line under the top bar of home is **Ways**, with a dot for each way your messages go out by and how many of them wait; a tap opens **Ways**. See [How Erevos picks the path](#paths).": "**Caminos en el inicio**: una vez puesto un relay, la línea bajo la barra superior del inicio es **Caminos**, con un punto por cada camino por el que salen tus mensajes y cuántos de ellos esperan; un toque abre **Caminos**. Consulta [Cómo elige Erevos el camino](#paths).",
  "**LoRa makes up for lost pieces, and long texts go shorter**: a text sent by LoRa in several pieces now goes with spare pieces, one for each four, so it comes whole even when a piece or two are lost on the air; older Erevos reads it as before. And long texts are packed, with nothing lost, before they are encrypted, when that makes them go in fewer bytes, to contacts whose Erevos unpacks them. See [Over a LoRa radio](#lora).": "**LoRa repone las partes perdidas, y los textos largos van más cortos**: un texto enviado por LoRa en varias partes va ahora con partes de repuesto, una por cada cuatro, así que llega entero aunque se pierdan una o dos partes en el aire; un Erevos más antiguo lo lee como antes. Y los textos largos se comprimen, sin perder nada, antes de cifrarse, cuando así ocupan menos bytes, para contactos cuyo Erevos los descomprime. Consulta [Con una radio LoRa](#lora).",
  "**Ways at a glance**: **Settings** → **Relay and networks** → **Ways** shows each way your messages go out by, the relay, Nostr, the phones nearby, LoRa, SMS and Tor, with how each is now and a line under it: full when it works, faint when it reaches no one now, dashed when it is off. Above them, how many of your messages wait to go, an orange dot for each. Only the space that is open shows, never hidden chats. See [How Erevos picks the path](#paths).": "**Los caminos de un vistazo**: **Ajustes** → **Relay y redes** → **Caminos** muestra cada camino por el que salen tus mensajes, el relay, Nostr, los teléfonos cercanos, LoRa, SMS y Tor, con cómo está cada uno ahora y una línea debajo: llena cuando funciona, tenue cuando ahora no llega a nadie, de guiones cuando está apagado. Encima, cuántos de tus mensajes esperan salir, un punto naranja por cada uno. Solo se muestra el espacio abierto, nunca los chats ocultos. Ver [Cómo elige Erevos el camino](#paths).",
  "**Answer a hidden contact's call with no PIN**: where hidden chats receive while closed, **Answer** on the ringing screen takes their contact's call at once, on a call screen with no name and no face, and the hidden chats stay closed; the small sign and the PIN still open them. See [Hidden chats](#hidden).": "**Contestar la llamada de un contacto oculto sin PIN**: donde los chats ocultos reciben estando cerrados, **Responder** en la pantalla de la llamada la contesta al momento, en una pantalla sin nombre ni cara, y los chats ocultos siguen cerrados; el pequeño signo y el PIN los siguen abriendo. Mira [Chats ocultos](#hidden).",
  "**See yourself in a video call**: once their picture comes, yours stays in a small window in the top corner, on both phones; before, it vanished, and each side saw only the other. See [Chat through a relay](#relay).": "**Mírate en una videollamada**: en cuanto llega la imagen del otro, la tuya queda en una ventana pequeña en la esquina superior, en ambos teléfonos; antes desaparecía, y cada lado veía solo al otro. Consulta [Chatear a través de un relay](#relay).",
  "**Phones nearby are off until you turn them on**: Erevos no longer looks for phones nearby by itself, with Bluetooth, Wi-Fi Aware or on the same Wi-Fi, as on the same Wi-Fi it held a call back for up to a minute before it rang. Turn on **Look for phones nearby** under **Nearby, with no internet**, on **New chat**, to chat and call with no internet. See [Chat with a nearby phone](#nearby).": "**Los teléfonos cerca están apagados hasta que los actives**: Erevos ya no busca por sí solo teléfonos cerca, por Bluetooth, Wi-Fi Aware o en la misma Wi-Fi, porque en la misma Wi-Fi retrasaba una llamada hasta un minuto antes de sonar. Activa **Buscar teléfonos cerca** en **Cerca, sin internet**, en **Chat nuevo**, para chatear y llamar sin internet. Consulta [Chatear con un teléfono cercano](#nearby).",
  "**Open a file with another app**: a file in a chat, a PDF say, has **Open** too, not only **Save**: the phone's app for it reads it from Erevos's memory, with no copy left on the phone. Erevos asks first, and never opens web pages, drawings or app packages that way. See [Chat through a relay](#relay).": "**Abrir un archivo con otra app**: un archivo en un chat, un PDF por ejemplo, tiene también **Abrir**, no solo **Guardar**: la app del teléfono lo lee de la memoria de Erevos, sin que quede una copia en el teléfono. Erevos pregunta primero y nunca abre así páginas web, dibujos ni paquetes de apps. Mira [Chatear a través de un relay](#relay).",
  "**Shared chats say how far they are, on both phones**: chats a contact shared from a relay your Erevos does not take from by itself show **Coming, 40%** once you tap them, and their phone says it is taking them; if they did not come, both phones say so and yours buzzes twice. See [Chat through a relay](#relay).": "**Los chats compartidos dicen cuánto llevan, en los dos teléfonos**: los chats que un contacto compartió desde un relay del que tu Erevos no toma por sí solo muestran **Recibiendo, 40%** al tocarlos, y su teléfono dice que los estás tomando; si no llegaron, lo dicen los dos teléfonos y el tuyo vibra dos veces. Mira [Chatear a través de un relay](#relay).",
  "**Calls connect again**: a call that rang no longer stays at **Connecting** on both phones; each phone now waits for its own addresses before it calls or answers. See [Chat through a relay](#relay).": "**Las llamadas vuelven a conectar**: una llamada que sonó ya no se queda en **Conectando** en los dos teléfonos; cada teléfono espera ahora sus propias direcciones antes de llamar o responder. Mira [Chatear a través de un relay](#relay).",
  "**A phone beside you brings your messages**: with no internet, an Erevos phone beside yours that has it, and carries for others, takes what waits for you on your relay and hands it over nearby, once you say yes to that phone. It learns your queue there, never what your messages say, and your phone moves to a new queue once it has internet again. Yours does the same for others while **Carry messages for others** is on, as it now is from the start. Never through Tor, and from another relay only once you say yes, warned it sees your address. See [Chat with a nearby phone](#nearby).": "**Un teléfono a tu lado trae tus mensajes**: sin internet, un teléfono con Erevos al lado del tuyo que lo tiene, y lleva para otros, toma lo que te espera en tu relay y te lo da de cerca, cuando le dices que sí a ese teléfono. Sabe tu cola ahí, nunca lo que dicen tus mensajes, y tu teléfono pasa a una cola nueva en cuanto vuelve a tener internet. El tuyo hace lo mismo para otros mientras **Llevar mensajes de otros** está activado, como ahora lo está desde el principio. Nunca por Tor, y de otro relay solo cuando dices que sí, avisado de que ve tu dirección. Ver [Chat with a nearby phone](#nearby).",
  "**A Matrix chat read elsewhere is read here too**: an encrypted Matrix chat you read, or answered, in Element or on another device of yours no longer keeps its count of new messages here. See [Matrix](#matrix).": "**Un chat de Matrix leído en otro sitio queda leído aquí también**: un chat cifrado de Matrix que leíste o respondiste en Element o en otro de tus dispositivos ya no conserva aquí su número de mensajes nuevos. Ver [Matrix](#matrix).",
  "**Matrix rooms with very long messages open**: a message with a very long run of names, dots or dashes, as some public Matrix rooms have, no longer closes Erevos+ as its chat shows it.":
    "**Las salas de Matrix con mensajes muy largos se abren**: un mensaje con una serie muy larga de nombres, puntos o guiones, como tienen algunas salas públicas de Matrix, ya no cierra Erevos+ cuando su chat lo muestra.",
  "**Messenger chats you read stay read**: a Messenger chat you marked read, or wrote in, no longer comes back as unread when Messenger sends it again, after Erevos+ reconnects or starts.":
    "**Los chats de Messenger que leíste siguen leídos**: un chat de Messenger que marcaste como leído, o en el que escribiste, ya no vuelve a aparecer como no leído cuando Messenger lo envía de nuevo, después de que Erevos+ se reconecte o se inicie.",
  "**Chats stay where you read**: in Telegram, Matrix, XMPP and Nostr chats, the chat no longer moves by itself to other messages as older ones load above it; it stays at the last message, or where you were reading.":
    "**Los chats se quedan donde lees**: en los chats de Telegram, Matrix, XMPP y Nostr, el chat ya no se mueve solo a otros mensajes mientras se cargan los más antiguos encima; se queda en el último mensaje o donde estabas leyendo.",
  "**Erevos+ says its own name, with an icon of its own**: the app and its guide now say Erevos+ everywhere, and its icon is Erevos's mark on a purple tile. Where it speaks of the plain Erevos, it still says Erevos.":
    "**Erevos+ dice su propio nombre, con un icono propio**: la app y su guía dicen ahora Erevos+ en todas partes, y su icono es la marca de Erevos sobre un fondo morado. Donde habla del Erevos sencillo, sigue diciendo Erevos.",
  "**Signal: one chat for each person, with their name**: in Erevos+, a Signal chat shows the person's name, what you send from the phone Erevos+ is linked to shows in the chat of the one you sent it to, and someone who first wrote to your phone number keeps one chat with you on their phone too.":
    "**Signal: un chat por persona, con su nombre**: en Erevos+, un chat de Signal muestra el nombre de la persona, lo que envías desde el teléfono al que está vinculado Erevos+ aparece en el chat de quien lo recibió, y quien te escribió primero a tu número conserva también un solo chat contigo en su teléfono.",
  "**A message's menu always opens**: holding a message, in a chat or a group, opens its menu every time; before, after you had been in another app, it could stop opening until Erevos was closed and opened again.": "**El menú de un mensaje siempre se abre**: al mantener pulsado un mensaje, en un chat o en un grupo, su menú se abre cada vez; antes, después de pasar por otra app, podía dejar de abrirse hasta cerrar y volver a abrir Erevos.",
  "**New chat, made anew**: your QR code is on New chat as soon as it opens, with **Scan theirs** and **Share** under it; the field at the top finds a contact by name, or adds someone whose link you paste; and **No Erevos yet?** makes an invite, showing again one no one took yet instead of making another. On a new phone with no relay, New chat starts with **Start with an invite**. The small QR code is new each time and good once: the first to scan it is a contact at once, and anyone after, or with the link you share, writes a message request first. See [Chat through a relay](#relay).": "**Chat nuevo, hecho de nuevo**: tu código QR está en Chat nuevo en cuanto se abre, con **Escanear el suyo** y **Compartir** debajo; el campo de arriba encuentra un contacto por su nombre, o añade a alguien cuyo enlace pegas; y **¿Aún no tiene Erevos?** hace una invitación, mostrando de nuevo una que nadie ha tomado aún en lugar de hacer otra. En un teléfono nuevo sin relay, Chat nuevo empieza con **Empieza con una invitación**. El código QR pequeño es nuevo cada vez y vale una vez: el primero que lo escanea es un contacto al instante, y quien venga después, o con el enlace que compartes, escribe primero una solicitud de mensaje. Ver [Chat through a relay](#relay).",
  "What's new": 'Novedades',
  'What each version changed': 'Qué cambió en cada versión',
  'What each version of Erevos changed, the newest first.': 'Qué cambió en cada versión de Erevos, primero la más reciente.',
  'Not out yet': 'Aún no ha salido',
  'This version': 'Esta versión',
  'For you': 'Para ti',
  'Under the hood': 'Bajo el capó',
  "**Chats you have read stay read, on every network**: in Erevos+, Messenger, Signal, Session, Telegram, Matrix, XMPP and Nostr chats you have read no longer notify you again of messages already read, after a restart, a reconnect or when a chat opens. Signal's reads go both ways with the phone it is linked to, and a Nostr chat you answer from another app is read here too.": "**Los chats que leíste siguen leídos, en todas las redes**: en Erevos+, los chats de Messenger, Signal, Session, Telegram, Matrix, XMPP y Nostr que leíste ya no te avisan otra vez de mensajes ya leídos, tras reiniciar, reconectar o al abrir un chat. Lo leído en Signal va en los dos sentidos con el teléfono al que está vinculado, y un chat de Nostr que respondes desde otra app queda leído aquí también.",
  "**The guide tells of Messenger, Signal and Session**: in Erevos+, the user guide has a section for each, on signing in, chats, groups, calls, notifications, Tor and signing out. See [Messenger](#messenger), [Signal](#signal) and [Session](#session).": "**La guía explica Messenger, Signal y Session**: en Erevos+, la guía de uso tiene una sección para cada uno, sobre iniciar sesión, chats, grupos, llamadas, notificaciones, Tor y cerrar sesión. Consulta [Messenger](#messenger), [Signal](#signal) y [Session](#session).",
  // Not out yet.
  "**New chat asks whether they have Erevos**: over your QR code on **New chat**, choose **Has Erevos already** or **New to Erevos**. The first is your QR code as before, and says that it works only when both phones have a relay; the second shows an invite, which brings in someone new, or someone whose phone has no relay. New chat remembers your choice. See [Chat through a relay](#relay).":
    "**Chat nuevo pregunta si tiene Erevos**: encima de tu código QR en **Chat nuevo**, elige **Ya tiene Erevos** o **Nuevo en Erevos**. Lo primero es tu código QR como antes, y dice que solo funciona si los dos teléfonos tienen un relay; lo segundo muestra una invitación, que trae a alguien nuevo, o a alguien cuyo teléfono no tiene relay. Chat nuevo recuerda tu elección. Ver [Chatear a través de un relay](#relay).",
  "**The keypad lists the contacts it finds, and shows its letters**: on the Phone's **Keypad**, the contacts what you type finds are listed in the room over the number, all of them, not one at a time; and each key shows its letters in the app's language, ΑΒΓ in Greek, ABC in the others. See [Phone](#phone).":
    "**El teclado muestra en lista los contactos que encuentra, y sus letras**: en el **Teclado** del Teléfono, los contactos que encuentra lo que tecleas aparecen en una lista en el espacio sobre el número, todos a la vez y no de uno en uno; y cada tecla muestra sus letras en el idioma de la app, ΑΒΓ en griego, ABC en los demás. Mira [Teléfono](#phone).",
  "**A phone beside you no longer slows Erevos**: with another Erevos phone near you on the same Wi-Fi, Erevos no longer links to it over Wi-Fi Aware too, which took your phone's Wi-Fi away for moments and slowed your messages and the relay, as if the other phone were far away; and a link to a phone nearby that stopped carrying anything is let go at once, not used on. See [Chat with a nearby phone](#nearby).":
    "**Un teléfono a tu lado ya no ralentiza Erevos**: con otro teléfono con Erevos cerca de ti en la misma Wi-Fi, Erevos ya no se conecta también a él por Wi-Fi Aware, lo que quitaba por momentos la Wi-Fi a tu teléfono y ralentizaba tus mensajes y el relay, como si el otro teléfono estuviera lejos; y un enlace con un teléfono cercano que dejó de llevar nada se suelta enseguida, en vez de seguir usándolo. Ver [Chatear con un teléfono cercano](#nearby).",
  "**Calls start sooner and sound steadier**: a call through the call relay no longer waits up to 5 seconds on each phone for every way to the relay, only for the first that works; while it goes on, Erevos looks for phones nearby less often, which took the phone's Wi-Fi away for moments and made gaps in the sound; and in a video call, their picture is no longer put aside when their sound came apart from it. See [Chat through a relay](#relay).":
    "**Las llamadas empiezan antes y suenan más estables**: una llamada por el relay de llamadas ya no espera hasta 5 segundos en cada teléfono a cada camino hacia el relay, solo al primero que funciona; mientras dura, Erevos busca teléfonos cercanos con menos frecuencia, lo que quitaba un momento el Wi-Fi al teléfono y cortaba el sonido; y en una videollamada, su imagen ya no se deja de lado cuando su sonido llegó aparte. Ver [Chat through a relay](#relay).",
  "**Contacts as you dial**: on the Phone's **Keypad**, a contact whose number holds the digits you type, or whose name starts with them on the keys' letters (2 for ABC and ΑΒΓ), shows over the keys: tap it to call. See [Phone](#phone).":
    "**Contactos al marcar**: en el **Teclado** del Teléfono, un contacto cuyo número contiene los dígitos que tecleas, o cuyo nombre empieza con ellos en las letras de las teclas (2 para ABC y ΑΒΓ), aparece sobre las teclas: tócalo para llamar. Ver [Teléfono](#phone).",
  "**Chats open at once**: a chat no longer waits, showing your contact as encrypted, for Erevos to finish what it was doing with the relay in the background; it is ready to use as it opens, and holding a message opens its menu, at most a moment later while Erevos says it is still reading what came. See [Chat through a relay](#relay).":
    "**Los chats se abren al instante**: un chat ya no espera, mostrando a tu contacto como cifrado, a que Erevos termine lo que hacía con el relay en segundo plano; está listo al abrirse, y mantener pulsado un mensaje abre su menú, como mucho un momento después, mientras Erevos dice que aún está leyendo lo que llegó. Ver [Chatear a través de un relay](#relay).",
  "**Pair with a code with no relay yet**: on a phone with no relay yet, **New chat** now has **Pair with a code** too, under your QR code, and opens straight on **Start with an invite** without first showing the screen of a phone with a relay. See [Chat through a relay](#relay).":
    "**Emparejar con un código sin relay todavía**: en un teléfono sin relay todavía, **Chat nuevo** también tiene ahora **Emparejar con un código**, bajo tu código QR, y se abre directamente en **Empieza con una invitación** sin mostrar antes la pantalla de un teléfono con relay. Ver [Chat through a relay](#relay).",
  "**The Public tab says why it shows no Nostr post**: whether the list of people you follow was not found, or they were found but no relay sent their posts, or their posts came but could not be shown, and how each relay answered. Before, it said only that no public posts were found. See [Chats with other Nostr apps](#nostr-chats).":
    "**La pestaña Público dice por qué no muestra ninguna publicación de Nostr**: si no se encontró la lista de las personas que sigues, si se encontraron pero ningún relay envió sus publicaciones, o si llegaron publicaciones pero no se pudieron mostrar, y cómo respondió cada relay. Antes solo decía que no se encontraron publicaciones públicas. Ver [Chats con otras apps de Nostr](#nostr-chats).",
  "**A new computer links to the end**: a computer with no relay before linking now takes the phone's answer at once, so linking with the small code finishes by itself, and with the full code **They match** shows. Before, the phone waited for **They match** while the computer showed nothing more until Erevos started again. See [Linked devices](#devices).":
    "**Un ordenador nuevo se vincula hasta el final**: un ordenador sin relay antes de vincularlo toma ahora al instante la respuesta del teléfono, así que la vinculación con el código pequeño termina sola, y con el código completo aparece **Coinciden**. Antes, el teléfono esperaba **Coinciden** mientras el ordenador no mostraba nada más hasta que Erevos se volvía a abrir. Ver [Dispositivos vinculados](#devices).",
  "**Sharing into Erevos reaches every service**: **Send to** now lists the chats of your Matrix, XMPP and Nostr accounts too, beside Erevos chats, groups and SMS conversations. A photo or file shared from another app no longer goes missing when Erevos locks as it opens: after the password, **Send to** shows it again, where before it said that nothing came to send. See [Chat through a relay](#relay).":
    "**Compartir en Erevos llega a todos los servicios**: **Enviar a** ahora lista también los chats de tus cuentas de Matrix, XMPP y Nostr, junto a los chats de Erevos, los grupos y las conversaciones SMS. Una foto o un archivo compartido desde otra app ya no se pierde cuando Erevos se bloquea al abrirse: tras la contraseña, **Enviar a** lo muestra de nuevo, donde antes decía que no llegó nada para enviar. Ver [Chatear a través de un relay](#relay).",
  "**Search, media, days and export in Matrix, XMPP, Nostr and SMS**: these chats now have **Search in this chat**, **Media, links and files**, **Go to a day** and **Export chat**, as Erevos chats do, over what your phone keeps of them; an SMS conversation has them under **⋮**. Nothing you search for leaves your phone. See [Getting started](#start).":
    "**Búsqueda, multimedia, días y exportación en Matrix, XMPP, Nostr y SMS**: estos chats ahora tienen **Buscar en este chat**, **Multimedia, enlaces y archivos**, **Ir a un día** y **Exportar chat**, como los chats de Erevos, sobre lo que tu teléfono guarda de ellos; una conversación SMS los tiene en **⋮**. Nada de lo que buscas sale de tu teléfono. Ver [Primeros pasos](#start).",
  "**Styles, cards and video in Matrix, XMPP and Nostr**: these chats now show bold, italic and the other marks for how words look, with tappable links, and send a contact card, a video without where it was filmed, or a photo from the camera at the quality you choose. In groups, @ offers the members; Nostr chats send your location, and a message you forward is marked as forwarded on your phone. See [Matrix](#matrix).":
    "**Estilos, tarjetas y vídeo en Matrix, XMPP y Nostr**: estos chats ahora muestran negrita, cursiva y las demás marcas de cómo se ven las palabras, con enlaces que se pueden tocar, y envían una tarjeta de contacto, un vídeo sin el lugar donde se grabó o una foto de la cámara con la calidad que elijas. En los grupos, @ ofrece los miembros; los chats de Nostr envían tu ubicación, y un mensaje que reenvías se marca como reenviado en tu teléfono. Ver [Matrix](#matrix).",
  "**Starred messages in every chat**: star a message in Matrix, XMPP, Nostr and SMS too, and find it again under **Starred messages**; save a photo, video, voice message or file that came there to the Collection, and keep a sticker or photo that came as one of your stickers. See [Chat through a relay](#relay).":
    "**Mensajes destacados en todos los chats**: destaca un mensaje también en Matrix, XMPP, Nostr y SMS, y vuelve a encontrarlo en **Mensajes destacados**; guarda en la Colección una foto, un vídeo, un mensaje de voz o un archivo que llegó allí, y quédate un sticker o una foto que llegó como uno de tus stickers. Ver [Chatear a través de un relay](#relay).",
  "**Pin and archive any chat**: hold any chat down on the home screen (an Erevos contact or group, Matrix, XMPP or Nostr) to **Pin to the top**, **Archive** or, on Android, mute it, as SMS conversations already could. Archived chats wait under **Archived** until a new message comes from them. Matrix favourites show pinned, and low-priority rooms come last. A Matrix row shows ✓✓✓ once everyone has read yours. Matrix rooms, XMPP contacts and group MMS can take a name of your own. See [Getting started](#start).":
    "**Fija y archiva cualquier chat**: mantén pulsado cualquier chat en la pantalla de inicio (un contacto o grupo de Erevos, Matrix, XMPP o Nostr) para **Fijar arriba**, **Archivar** o, en Android, silenciarlo, como ya podían las conversaciones SMS. Los chats archivados esperan en **Archivadas** hasta que llega un mensaje nuevo de ellos. Los favoritos de Matrix aparecen fijados, y las salas de prioridad baja van al final. Una fila de Matrix muestra ✓✓✓ cuando todos han leído el tuyo. Las salas de Matrix, los contactos de XMPP y los MMS de grupo pueden llevar un nombre tuyo. Ver [Primeros pasos](#start).",
  "**Drafts, Send later and Remind me on Matrix, XMPP and Nostr**: what you type in a chat and do not send stays as its draft, also after Erevos closes, and shows on the chat's row. Hold **Send** down to send a message later from this phone. A Matrix or XMPP message that did not go has **Send again** in its menu, and **Remind me** on a message of any of these chats, SMS too, puts it in Chat with myself with a reminder. See [Matrix](#matrix).":
    "**Borradores, Enviar más tarde y Recordarme en Matrix, XMPP y Nostr**: lo que escribes en un chat y no envías queda como su borrador, también después de que Erevos se cierra, y se ve en la fila del chat. Mantén pulsado **Enviar** para enviar un mensaje más tarde desde este teléfono. Un mensaje de Matrix o XMPP que no salió tiene **Volver a enviar** en su menú, y **Recordarme** en un mensaje de estos chats, y de SMS, lo pone en Chat conmigo con un recordatorio. Ver [Matrix](#matrix).",
  "**A PIN and screenshots for Matrix, XMPP, Nostr and SMS chats**: lock a chat on Matrix, XMPP or Nostr, or an SMS conversation, with a PIN of its own and block its screenshots, as an Erevos chat; an SMS conversation can also have its own look, be muted, or have a sound of its own. See [Hidden chats](#hidden).":
    "**Un PIN y capturas para chats de Matrix, XMPP, Nostr y SMS**: bloquea un chat de Matrix, XMPP o Nostr, o una conversación SMS, con un PIN propio y bloquea sus capturas de pantalla, como un chat de Erevos; una conversación SMS también puede tener su propia apariencia, estar silenciada o tener un sonido propio. Ver [Chats ocultos](#hidden).",
  "**Chat rules on Matrix, XMPP, Nostr and SMS**: disappearing messages, a timer for the chat or **Disappear** for one message, each chat saying what the other side keeps; **Block** on Matrix and Nostr, with a list of whom you blocked on each service's screen; **Delete** asks **This phone** or **Everyone**; on XMPP, **Appear offline** to one contact; and **Check in person** by QR code on XMPP and Nostr. See [Matrix](#matrix).":
    "**Reglas del chat en Matrix, XMPP, Nostr y SMS**: mensajes temporales, con un tiempo para el chat o **Temporal** para un mensaje, y cada chat dice lo que guarda el otro lado; **Bloquear** en Matrix y Nostr, con una lista de a quién bloqueaste en la pantalla de cada servicio; **Eliminar** pregunta **Este teléfono** o **Para todos**; en XMPP, **Aparecer sin conexión** para un contacto; y **Comprobar en persona** con código QR en XMPP y Nostr. Ver [Matrix](#matrix).",
  "**Choose where a call's sound goes**: with a Bluetooth or wired headset connected, **Speaker** in a call becomes **Audio output**, to choose the phone, the speaker or the headset, a Bluetooth one by its own name. A headset connected as a call starts, or during it, takes the sound, as in a phone call. On Android. See [Chat through a relay](#relay).":
    "**Elige adónde va el sonido de una llamada**: con unos auriculares Bluetooth o con cable conectados, **Altavoz** en una llamada pasa a ser **Salida de audio**, para elegir el teléfono, el altavoz o los auriculares, unos Bluetooth con su propio nombre. Unos auriculares conectados al empezar una llamada, o durante ella, se quedan con el sonido, como en una llamada de teléfono. En Android. Consulta [Chatear a través de un relay](#relay).",
  "**Nothing goes through Tor unless you turn it on**: on Android, **Automatically from your relay** under **Home relay** is now off in a new space, so a space no longer takes its relay's paired relay as a home relay through Tor by itself; turn it on there if you want it. Turning it off now also lets go of the home relay it took, so Tor does not run for it. See [Home relay](#home-relay).":
    "**Nada pasa por Tor salvo que lo actives**: en Android, **Automáticamente desde tu relay** en **Relay de casa** ahora está apagado en un espacio nuevo, así que un espacio ya no toma por sí solo el relay emparejado con su relay como relay de casa por Tor; actívalo allí si lo quieres. Al apagarlo ahora también suelta el relay de casa que tomó, para que Tor no funcione por él. Ver [Relay de casa](#home-relay).",
  "**Your relays first, Nostr only after them**: a text to a contact who reads on Nostr now goes through your relay, then their home relays, then your home relay, and through the public Nostr relays only when none of them took it. Before, it went to the Nostr relays first and through your relay only when they were slow or did not take it. See [Through Nostr](#nostr).":
    "**Primero tus relays, Nostr solo después**: un texto a un contacto que lee en Nostr ahora va por tu relay, luego por los relays de casa de tu contacto, luego por tu relay de casa, y por los relays públicos de Nostr solo cuando ninguno lo aceptó. Antes iba primero a los relays de Nostr y por tu relay solo cuando estos eran lentos o no lo aceptaban. Ver [A través de Nostr](#nostr).",
  "**One chat only through Tor**: on Android, **Through Tor** in an Erevos chat's **Details** sends that chat's messages and files only through Tor, on circuits of its own, whatever the space's Tor setting. It is off unless you turn it on, and calls do not go through Tor. See [Through Tor](#tor).":
    "**Un solo chat por Tor**: en Android, **Por Tor** en los **Detalles** de un chat de Erevos envía los mensajes y archivos de ese chat solo por Tor, por circuitos propios, diga lo que diga el ajuste de Tor del espacio. Está desactivado salvo que lo actives, y las llamadas no van por Tor. Ver [A través de Tor](#tor).",
  "**One chat only through Tor reaches Nostr too**: a chat with **Through Tor** on in its **Details** now sends and reads its Nostr texts only through Tor, and its photos and files on Nostr file servers too, even when the space's Tor is **Nothing**; Tor is started for it, and what goes waits for it. Until your contact first writes to the chat's own queue, their first messages come to the space's own queue, which is read the space's way. Before, with the space's Tor off, such a chat's texts could reach the public Nostr relays straight, and they saw the phone's internet address. See [Through Tor](#tor).":
    "**Un solo chat por Tor llega también a Nostr**: un chat con **Por Tor** activado en sus **Detalles** envía y lee ahora sus textos de Nostr solo por Tor, y sus fotos y archivos en servidores de archivos de Nostr también, aunque el Tor del espacio sea **Nada**; Tor se arranca para él, y lo que sale lo espera. Hasta que tu contacto escribe por primera vez en la cola propia del chat, sus primeros mensajes llegan a la cola del espacio, que se lee como dice el espacio. Antes, con el Tor del espacio desactivado, los textos de un chat así podían llegar directamente a los relays públicos de Nostr, y estos veían la dirección de internet del teléfono. Mira [A través de Tor](#tor).",
  "**Through Tor on your linked devices too**: a chat's **Through Tor** switch, set in its **Details**, now reaches your linked devices (your computer, the web app and Jolla) and back: switched on or off on any of them, it is switched everywhere. On a linked device that chat's messages, files and send-later messages then go only through Tor too, on the chat's own circuits, never straight; so do the copies that go to your contact's other devices. The web app has no Tor: there a chat with the switch on sends nothing while it is on, and the switch is shown so it can be turned off. A device on an older version never turns it off anywhere; it learns a change made elsewhere at that contact's next change. Before, it was only on the phone where you set it. See [Through Tor](#tor).":
    "**Por Tor también en tus dispositivos vinculados**: el interruptor **Por Tor** de un chat, puesto en sus **Detalles**, llega ahora a tus dispositivos vinculados (tu ordenador, la aplicación web y Jolla) y vuelve: activado o desactivado en uno, queda así en todos. En un dispositivo vinculado, los mensajes, archivos y mensajes para enviar más tarde de ese chat van entonces también solo por Tor, por los circuitos propios del chat, nunca directos; igual las copias que van a los otros dispositivos de tu contacto. La aplicación web no tiene Tor: allí un chat con el interruptor activado no envía nada mientras esté activado, y el interruptor se muestra para poder desactivarlo. Un dispositivo con una versión anterior nunca lo desactiva en ningún sitio; se entera de un cambio hecho en otro lado en el siguiente cambio de ese contacto. Antes, solo valía en el teléfono donde lo ponías. Ver [A través de Tor](#tor).",
  "**Nostr has its own Tor switch**: the **Nostr** screen now has **Nostr through Tor**, **On** or **Off**, off unless you turn it on. **On**, Erevos reaches the Nostr relays and the Nostr file servers only through Tor, and starts Tor for it even when the space's Tor is **Nothing**; a text that goes there waits while Tor starts. It only adds Tor: with the space's Tor on, or for a chat set to **Through Tor**, Nostr goes through Tor whatever it says. Before, Nostr only followed the space's Tor setting, and the screen only said whether it was on. See [Through Nostr](#nostr).":
    "**Nostr tiene su propio interruptor de Tor**: la pantalla **Nostr** tiene ahora **Nostr por Tor**, **Activado** o **Desactivado**, desactivado salvo que lo actives. **Activado**, Erevos llega a los relays de Nostr y a los servidores de archivos de Nostr solo por Tor y arranca Tor para ello, aunque el Tor del espacio sea **Nada**; un texto que va allí espera mientras Tor arranca. Solo añade Tor: con el Tor del espacio activado, o en un chat con **Por Tor**, Nostr va por Tor diga lo que diga. Antes, Nostr solo seguía el ajuste de Tor del espacio y la pantalla solo decía si estaba activado. Mira [A través de Nostr](#nostr).",
  "**Erevos warns before your internet address can be seen**: once before the first message, voice message or file in an Erevos chat that can go without Tor, with **Through Tor for this chat** to fix it or **Go on**; before the first message in an Erevos group that can go without Tor; before a call, as calls never go through Tor, unless the contact is nearby on the same network; before fetching a file from a server your contact chose; and in every **Open this link?** question, where the site sees the address. Each has a **Guide** button. Before, Erevos did not say it. See [Who sees your internet address](#ip).":
    "**Erevos avisa antes de que pueda verse tu dirección de internet**: una vez antes del primer mensaje, mensaje de voz o archivo en un chat de Erevos que puede ir sin Tor, con **Por Tor para este chat** para arreglarlo o **Seguir**; antes del primer mensaje en un grupo de Erevos que puede ir sin Tor; antes de una llamada, pues las llamadas nunca van por Tor, salvo que el contacto esté cerca en la misma red; antes de descargar un archivo de un servidor que eligió tu contacto; y en cada pregunta **¿Abrir este enlace?**, donde el sitio ve la dirección. Cada aviso tiene un botón **Guía**. Antes, Erevos no lo decía. Mira [Quién ve tu dirección de internet](#ip).",
  "**A Tor switch of their own**: backups to a server, the Collection's server copy, radio and TV lists, link previews and updates each have a **Through Tor** switch in their own screen, off unless you turn it on. On, that goes only through Tor, whatever the space's Tor setting, and waits while Tor starts; nothing goes straight. Off, it goes as before. It only adds Tor. For updates, the switch makes the daily new-version notice and **Check for updates** ask the web app's server instead of GitHub; a new version is told, but it does not download through Tor: to install it, turn the switch off for a moment. Playing a radio station or a TV channel always goes straight. Before, backups, the Collection and radio and TV followed only the space's Tor setting, and link previews and updates never went through Tor. See [Who sees your internet address](#ip).":
    "**Un interruptor de Tor propio**: las copias de seguridad a un servidor, la copia de la Colección en un servidor, las listas de radio y TV, las vistas previas de enlaces y las actualizaciones tienen cada una un interruptor **Por Tor** en su propia pantalla, desactivado salvo que lo actives. Activado, eso va solo por Tor, diga lo que diga el ajuste de Tor del espacio, y espera mientras Tor arranca; nada va directo. Desactivado, va como antes. Solo añade Tor. En las actualizaciones, el interruptor hace que el aviso diario de versión nueva y **Buscar actualizaciones** pregunten al servidor de la app web en vez de a GitHub; se avisa de una versión nueva, pero no se descarga por Tor: para instalarla, desactívalo un momento. Reproducir una emisora de radio o un canal de TV va siempre directo. Antes, las copias, la Colección y la radio y la TV solo seguían el ajuste de Tor del espacio, y las vistas previas y las actualizaciones nunca iban por Tor. Mira [Quién ve tu dirección de internet](#ip).",
  "**Bare web addresses open too**: t.me/name, example.org/page and the like are now tappable in every chat, as in Telegram and Signal, and show whole before they open; e-mail addresses and file names are not. See [Chat through a relay](#relay).":
    "**También se abren las direcciones web sin más**: t.me/name, example.org/page y similares ya se pueden tocar en todos los chats, como en Telegram y Signal, y se muestran enteras antes de abrirse; las direcciones de correo y los nombres de archivo no. Ver [Chatear a través de un relay](#relay).",
  "**Read marks no longer go missing**: when you read a message and put the phone away at once, the other person still learns that you read it, at Erevos's next look, also after Erevos was closed. Before, it could stay at ✓✓ for them for good.": "**Las marcas de lectura ya no se pierden**: si lees un mensaje y dejas el teléfono enseguida, la otra persona sabe igualmente que lo leíste, en la siguiente consulta de Erevos, también después de cerrar Erevos. Antes podía quedarse en ✓✓ para ella para siempre.",
  "**Backups are checked**: after each automatic backup Erevos reads it back from the folder, opens it with its password, makes sure every part it names is there, of its size, and reads two of them through. On a server it looks at the listing only. **Check now** under Backups also downloads the server’s newest backup and ten of its parts; a part missing or damaged shows in red. **Full check of the folder** compares every part there with its SHA-256, on the phone. See [Backups](#backup).":
    "**Las copias se comprueban**: tras cada copia automática, Erevos la vuelve a leer de la carpeta, la abre con su contraseña, se asegura de que cada parte que nombra está ahí, con su tamaño, y lee dos de ellas enteras. En un servidor solo mira la lista. **Comprobar ahora**, en Copias de seguridad, además descarga la copia más reciente del servidor y diez de sus partes; una parte que falta o está dañada se ve en rojo. **Comprobación completa de la carpeta** compara cada parte de ahí con su SHA-256, en el teléfono. Ver [Copias de seguridad](#backup).",
  "**A new first start**: the first screen now says what you do not give, no phone number, email, user name or account, and asks for a name for your contacts, if you want one. After the modules comes a short screen for each, with how to begin with it and what Android should allow for it, **Allow all, one by one** among it; then the password lock and backups, then what is ready and what is missing. **I already have Erevos on another phone** goes straight to restoring a backup. See [Modules](#modules).":
    "**Un primer inicio nuevo**: la primera pantalla dice ahora lo que no entregas, ni número de teléfono, ni correo, ni nombre de usuario, ni cuenta, y pide un nombre para tus contactos, si quieres uno. Tras los módulos viene una pantalla corta para cada uno, con cómo empezar con él y lo que Android debe permitir para él, con **Permitir todo, una por una** entre ello; luego el bloqueo con contraseña y las copias, y después lo que está listo y lo que falta. **Ya tengo Erevos en otro teléfono** va directo a restaurar una copia. Mira [Módulos](#modules).",
  "**Leftovers**: photos and files that nothing names any more, as those of an import that stopped in its middle, can now be found and deleted, under Backups → **Leftovers**. Type the PIN of each of your hidden chats and the password of any other space, tap **Find leftovers**, and Erevos shows how much none of them names; **Delete them** deletes it once you say so. See [Backups](#backup).":
    "**Restos**: las fotos y archivos que ya nada nombra, como los de una importación que se cortó a medias, ahora se pueden encontrar y borrar en Copias de seguridad → **Restos**. Escribe el PIN de cada uno de tus chats ocultos y la contraseña de cualquier otro espacio, toca **Buscar restos**, y Erevos muestra cuánto no nombra ninguno; **Borrarlos** lo borra cuando lo confirmas. Ver [Copias de seguridad](#backup).",
  "**An import that stops leaves nothing behind**: when Erevos stops while it brings in the photos and files of a Telegram, WhatsApp or Viber export, as when Android closes it or the battery runs out, what it had written of them is deleted the next time it starts. Before, it stayed on the phone, and in every backup, for good. See [Imported chats](#import).":
    "**Una importación que se corta no deja nada atrás**: cuando Erevos se detiene mientras trae las fotos y archivos de una exportación de Telegram, WhatsApp o Viber, como cuando Android lo cierra o se acaba la batería, lo que ya había escrito se borra la próxima vez que se inicia. Antes se quedaba en el teléfono, y en cada copia de seguridad, para siempre. Ver [Chats importados](#import).",
  // 7.0.0-rc.7
  "**What takes room**: Backups now have **What takes room**, which shows on Android how much room Erevos takes on the phone, by kind: the Collection with the chats' photos and files, voice messages, chat history, Tor, and what writes that did not end left over. Each automatic backup holds it all, so it tells why one is large. See [Backups](#backup).":
    "**Qué ocupa espacio**: las copias de seguridad tienen ahora **Qué ocupa espacio**, que muestra en Android cuánto espacio ocupa Erevos en el teléfono, por tipo: la Colección con las fotos y archivos de los chats, los mensajes de voz, el historial, Tor y los restos de escrituras que no terminaron. Cada copia automática lo contiene todo, así se ve por qué una es grande. Ver [Copias de seguridad](#backup).",
  "**Backups to a server get there again**: a backup to your own server, such as a Nextcloud, no longer stops when the server misses one of its pieces for a moment, as when it closes for a few minutes at night. That piece goes again a little later and the backup carries on; before, it started over the next time, and a large backup could fail day after day. See [Backups](#backup).":
    '**Las copias a un servidor vuelven a llegar**: una copia a tu propio servidor, como un Nextcloud, ya no se detiene cuando el servidor no acepta por un momento una de sus partes, como cuando cierra unos minutos por la noche. Esa parte vuelve a enviarse un poco más tarde y la copia sigue; antes, empezaba de nuevo la vez siguiente, y una copia grande podía fallar día tras día. Consulta [Copias de seguridad](#backup).',
  // 7.0.0-rc.6
  "**Photos and files from the Collection, straight from a chat**: **+** in a chat now has **Collection**, which opens the Collection of that chat's place, its photos and its other files. Tap what to send, then **Send**, and it goes in the chat. Before, **Photo** opened only the phone's own gallery. See [Collection](#collection).":
    "**Fotos y archivos de la Colección, directamente desde un chat**: **+** en un chat tiene ahora **Colección**, que abre la Colección del lugar de ese chat, con sus fotos y sus otros archivos. Toca lo que quieras enviar y luego **Enviar**, y va al chat. Antes, **Foto** abría solo la galería del teléfono. Ver [Colección](#collection).",
  "**A chat opens at its last message again**: opened from the home screen or a notification, a chat could stop above its newest messages, often above the unread ones. Now it goes to its end at once, and once more as its messages come into view.":
    "**Un chat vuelve a abrirse en su último mensaje**: abierto desde la pantalla de inicio o desde una notificación, un chat podía quedarse por encima de sus mensajes más nuevos, a menudo por encima de los no leídos. Ahora va a su final al momento, y otra vez en cuanto se ven sus mensajes.",
  "**A new sign-in to a relay is no longer undone**: after you signed in to your relay again, a chat screen open from before could later write back the token from before, which the relay no longer lets in, and the relay then refused this phone. Now the new token is kept at once, and every chat screen open takes it. See [Chat through a relay](#relay).":
    "**Un nuevo inicio de sesión en el relay ya no se deshace**: después de volver a iniciar sesión en tu relay, una pantalla de chat abierta desde antes podía volver a guardar más tarde el token anterior, que el relay ya no deja entrar, y entonces el relay rechazaba este teléfono. Ahora el nuevo token se guarda al momento, y toda pantalla de chat abierta lo toma. Mira [Chatear a través de un relay](#relay).",
  // 7.0.0-rc.5
  "**A message sent offline is no longer lost when you leave the chat**: what you sent while your chats were still opening, as they do for a while with no connection, was lost if you left the chat before it went. Now it waits, marked **Waiting**, and goes by itself once the relay or their phone nearby can take it, a voice message too. See [Chat through a relay](#relay).":
    "**Un mensaje enviado sin conexión ya no se pierde al salir del chat**: lo que enviabas mientras tus chats aún se abrían, como hacen un rato sin conexión, se perdía si salías del chat antes de que saliera. Ahora espera, marcado como **En espera**, y sale solo en cuanto el relay o su teléfono cercano pueden recibirlo, también un mensaje de voz. Mira [Chatear a través de un relay](#relay).",
  // 7.0.0-rc.4
  "**No more freezing after a space opens**: while an automatic backup was made, the screen could stop answering for minutes. Now the backup's files are written, listed and deleted in their folder away from the screen, and its parts are checked natively, many times faster.":
    '**Se acabaron los bloqueos al abrirse un espacio**: mientras se hacía una copia automática, la pantalla podía dejar de responder durante minutos. Ahora los archivos de la copia se escriben, se listan y se borran en su carpeta, lejos de la pantalla, y sus partes se comprueban de forma nativa, muchas veces más rápido.',
  // 7.0.0-rc.3
  "**Your SMS on your computer**: the phone's SMS can now show on this space's linked devices too, a computer, a browser or a tablet, end-to-end encrypted: read them there and answer, and the phone sends the answer. The latest 50 conversations go, each with its latest 50 messages; photos stay on the phone. Off until you turn it on, on the phone, under Settings → Phone and SMS → SMS → **On my linked devices too**. See [SMS](#sms).":
    "**Tus SMS en tu ordenador**: los SMS del teléfono ahora pueden aparecer también en los dispositivos vinculados de este espacio, un ordenador, un navegador o una tablet, cifrados de extremo a extremo: léelos allí y responde, y el teléfono envía la respuesta. Van las últimas 50 conversaciones, cada una con sus últimos 50 mensajes; las fotos se quedan en el teléfono. Desactivado hasta que lo actives, en el teléfono, en Ajustes → Teléfono y SMS → SMS → **También en mis dispositivos vinculados**. Consulta [SMS](#sms).",
  "**TV in the Collection**: the Collection's new **TV** tab plays TV channels from IPTV lists (.m3u), by their link or from a file, or from iptv-org's public list of free channels, by country or whole, in their groups, with a search, on Android, on a computer and in a browser. There is no programme guide, logos show only if you turn them on, and a channel's name and link, or a radio station's, can be sent to a chat. See [Collection](#collection).":
    "**TV en la Colección**: la nueva pestaña **TV** de la Colección reproduce canales de TV de listas IPTV (.m3u), por su enlace o desde un archivo, o de la lista pública de canales gratuitos de iptv-org, por país o entera, en sus grupos, con búsqueda, en Android, en el ordenador y en un navegador. No hay guía de programación, los logotipos solo se muestran si los activas, y el nombre y el enlace de un canal, o de una emisora de radio, se pueden enviar a un chat. Consulta [Colección](#collection).",
  "**Radio that keeps playing**: when a station's server, or a proxy on the way, drops the stream, or the network goes for a moment, Erevos asks the station again by itself, a few seconds later, instead of stopping.":
    "**Radio que sigue sonando**: cuando el servidor de una emisora, o un proxy intermedio, corta el flujo, o la red se va un momento, Erevos vuelve a conectar solo unos segundos después, en lugar de pararse.",
  "**Radio playlists with many stations**: in the Collection's Radio, **Add a station** takes a playlist link (.m3u, .pls) that names many stations and adds each of them, and **Import a playlist file** adds the stations of a .m3u or .pls file from your device. Only stations with an https link are added, and Erevos says how many were left out.":
    "**Listas de radio con muchas emisoras**: en la Radio de la Colección, **Añadir una emisora** acepta un enlace de lista (.m3u, .pls) con muchas emisoras y las añade todas, e **Importar un archivo de lista** añade las emisoras de un archivo .m3u o .pls de tu dispositivo. Solo se añaden emisoras con enlace https, y Erevos dice cuántas quedaron fuera.",
  "**Block screenshots in a chat**: in a chat's details, **Block screenshots** keeps screenshots and screen recordings of it out on both phones, on Android, and either of you can turn it off again. Erevos on an iPhone, on a computer, in a browser or on Sailfish cannot block them, and says so. See [Chat through a relay](#relay).":
    "**Bloquear capturas de pantalla en un chat**: en los detalles de un chat, **Bloquear capturas de pantalla** impide capturas y grabaciones de pantalla del chat en los dos teléfonos, en Android, y cualquiera de los dos puede volver a desactivarlo. Erevos en un iPhone, en un ordenador, en un navegador o en Sailfish no puede bloquearlas, y lo dice. Mira [Chatear a través de un relay](#relay).",
  "**Every chat in its own look**: groups, Chat with myself and chats on Matrix, XMPP and Nostr now have **Chat look** too, as a contact's chat had, for that chat only. See [Chat through a relay](#relay).":
    "**Cada chat con su propio aspecto**: los grupos, Chat conmigo y los chats de Matrix, XMPP y Nostr tienen ahora también **Apariencia del chat**, como lo tenía el chat de un contacto, solo para ese chat. Mira [Chatear a través de un relay](#relay).",
  "**Letters and text size**: Settings → Appearance has **Letters** (the style's own, the phone's, serif or monospace) and the messages' **Text size**, for the whole app or, from **Chat look**, for one chat. See [Appearance](#appearance).":
    "**Tipo de letra y tamaño del texto**: Ajustes → Apariencia tiene **Tipo de letra** (la del estilo, la del teléfono, con serifa o monoespaciada) y el **Tamaño del texto** de los mensajes, para toda la app o, desde **Apariencia del chat**, para un chat. Mira [Apariencia](#appearance).",
  "**Muting hidden Matrix, XMPP and Nostr chats**: a hidden place's own Matrix, XMPP and Nostr chats can now be muted, as hidden chats are, and then say nothing at all. See [Hidden chats](#hidden).":
    "**Silenciar chats ocultos de Matrix, XMPP y Nostr**: los chats de las cuentas propias de Matrix, XMPP y Nostr de un lugar oculto ahora se pueden silenciar, como los chats ocultos, y entonces no dicen nada. Mira [Chats ocultos](#hidden).",
  "**Say when I open Erevos**: with **Last seen** on, opening Erevos now tells your contacts at once, without waiting for a message: only those you talked with in the last 30 days who show their own time too, each after a random wait of up to a minute, at most every 15 minutes. The relay can then tell when you open Erevos: turn it off under Settings → Privacy and security → Last seen, or in a chat's details. See [Chat through a relay](#relay).":
    "**Avisar cuando abro Erevos**: con **Última vez** activado, al abrir Erevos tus contactos lo saben ahora al momento, sin esperar a un mensaje: solo aquellos con los que hablaste en los últimos 30 días que también muestran su propia hora, cada uno tras una espera aleatoria de hasta un minuto, como mucho cada 15 minutos. El relay puede entonces saber cuándo abres Erevos: apágalo en Ajustes → Privacidad y seguridad → Última vez, o en los detalles de un chat. Mira [Chatear a través de un relay](#relay).",
  "**Moving to a new phone**: a new chapter of the guide takes you step by step from the old phone to the new one with one backup: what to get ready, what comes over, what to set again, and wiping the old one at the end. See [Moving to a new phone](#new-phone).":
    "**Pasar a un teléfono nuevo**: un capítulo nuevo de la guía te lleva paso a paso del teléfono viejo al nuevo con una sola copia de seguridad: qué preparar, qué pasa, qué volver a poner y cómo borrar el viejo al final. Consulta [Pasar a un teléfono nuevo](#new-phone).",
  '**A lost phone**: if the phone a backup came from was lost or stolen and may still be on, **The old phone was lost** under Settings → Data and devices → Backups moves every space and its hidden chats to new relay queues, so that phone reads nothing more of yours there, and tells your contacts quietly. The contact links and QR codes you gave before work for 14 more days. See [Backups](#backup).':
    '**Un teléfono perdido**: si el teléfono del que vino una copia se perdió o te lo robaron y puede seguir encendido, **El teléfono anterior se perdió**, en Ajustes → Datos y dispositivos → Copias de seguridad, pasa cada espacio y sus chats ocultos a colas nuevas del relay, para que ese teléfono no lea nada más tuyo allí, y avisa a tus contactos sin ruido. Los enlaces de contacto y los códigos QR que diste antes sirven 14 días más. Consulta [Copias de seguridad](#backup).',
  '**Restored chats go on by themselves**: after a backup is restored, a chat that went on after the backup was made starts a new conversation with the contact by itself, so you no longer give each other your links again, but with a contact on an older Erevos. See [Backups](#backup).':
    '**Los chats restaurados siguen solos**: tras restaurar una copia, un chat que siguió después de hacerla empieza solo una conversación nueva con el contacto, así que ya no tenéis que daros de nuevo vuestros enlaces, salvo con un contacto de un Erevos más antiguo. Consulta [Copias de seguridad](#backup).',
  '**Backups every 6 hours, and lighter**: automatic backups can now come every 6 hours too, made while Erevos is open and as it goes to the background. Each one writes and sends only the photos, files and voice messages that are new, and names again those of the backups before it: keep the whole backup folder together. See [Backups](#backup).':
    '**Copias cada 6 horas, y más ligeras**: las copias automáticas ahora también pueden hacerse cada 6 horas, mientras Erevos está abierto y al pasar a segundo plano. Cada una escribe y envía solo las fotos, archivos y mensajes de voz que son nuevos, y nombra de nuevo los de las copias anteriores: mantén junta toda la carpeta de copias. Consulta [Copias de seguridad](#backup).',
  '**Linked devices after a restore**: the phone a backup was restored on can ask the computers and browsers the old phone had linked to link again: tap **Ask to link again** under Settings → Data and devices → Linked devices, then **Link again** on the device. It keeps its chats, with no code to scan. See [Backups](#backup).':
    '**Dispositivos vinculados tras una restauración**: el teléfono en el que se restauró una copia puede pedir a los ordenadores y navegadores que el teléfono anterior tenía vinculados que se vinculen de nuevo: toca **Pedir que vuelva a vincularse** en Ajustes → Datos y dispositivos → Dispositivos vinculados, y luego **Volver a vincular** en el dispositivo. Conserva sus chats, sin código que escanear. Consulta [Copias de seguridad](#backup).',
  "**The phone's calls in backups**: on Android, **Put the calls in backups** under Backups adds the call history and Android's blocked numbers to your backups, and restoring adds back those the phone lacks. Off until you turn it on. See [Backups](#backup).":
    '**Las llamadas del teléfono en las copias**: en Android, **Incluir las llamadas en las copias**, en Copias de seguridad, añade a tus copias el historial de llamadas y los números bloqueados de Android, y restaurar devuelve los que le faltan al teléfono. Desactivado hasta que lo actives. Consulta [Copias de seguridad](#backup).',
  "**Groups after a restore**: a member restored from a backup asks the group's admin to put it in again, which works while the group moved on only a little.":
    '**Grupos tras una restauración**: un miembro restaurado desde una copia pide al administrador del grupo que lo vuelva a meter, lo que funciona mientras el grupo solo ha avanzado un poco.',
  "**The time of a message that waited**: a message that waited on the relay, as for a computer or for hidden chats that were closed, now shows when it was sent, not when it came. From an Erevos before this version it still shows when it came.":
    "**La hora de un mensaje que esperó**: un mensaje que esperó en el relay, como para un ordenador o para chats ocultos que estaban cerrados, ahora muestra cuándo se envió, no cuándo llegó. De un Erevos anterior a esta versión sigue mostrando cuándo llegó.",
  // 7.0.0-rc.2
  "**Find radio stations by name**: Add a station in the Collection's Radio tab searches Radio Browser, a free directory, sent only the words you type when you press Search. See [Collection](#collection).":
    "**Encuentra emisoras por su nombre**: Añadir una emisora en la pestaña Radio de la Colección busca en Radio Browser, un directorio libre, al que solo se envían las palabras que escribes cuando pulsas Buscar. Consulta [Colección](#collection).",
  "**Internet radio in the Collection**: a Radio tab with stations you add by their https link, kept encrypted with the Collection, played like the music, with the notice on the phone. The station sees your device's IP address. See [Collection](#collection).":
    "**Radio por internet en la Colección**: una pestaña Radio con emisoras que añades por su enlace https, cifradas con la Colección, que suenan como la música, con el aviso en el teléfono. La emisora ve la dirección IP de tu dispositivo. Consulta [Colección](#collection).",
  "**Music and videos of any size in the desktop app's Collection**: they play and seek at once, read a piece at a time from their encrypted pieces, never held whole in memory. See [Collection](#collection).":
    "**Música y vídeos de cualquier tamaño en la Colección de la aplicación de escritorio**: suenan y se avanzan al instante, leídos trozo a trozo de sus partes cifradas, nunca enteros en memoria. Consulta [Colección](#collection).",
  "**Playlists in the Collection's Music**: songs in the order you choose, kept encrypted with the Collection, played in order or shuffled. Make one at the top of Music, and add songs from their menu or by holding them down. See [Collection](#collection).":
    "**Listas de reproducción en la Música de la Colección**: canciones en el orden que eliges, cifradas con la Colección, en orden o en orden aleatorio. Crea una arriba en Música, y añade canciones desde su menú o manteniéndolas pulsadas. Consulta [Colección](#collection).",
  "**Subtitles for the Collection's videos**: an .srt or .vtt file in the same folder with the video's name (film.srt, or film.en.srt) shows as its subtitles, and a tap at the top turns them off or on. See [Collection](#collection).":
    "**Subtítulos para los vídeos de la Colección**: un archivo .srt o .vtt en la misma carpeta con el nombre del vídeo (film.srt, o film.en.srt) se muestra como sus subtítulos, y un toque arriba los quita o los pone. Consulta [Colección](#collection).",
  "**A player's screen for the Collection**: tap the bar of the music playing, or **Now playing**, for its cover, title, artist and album, a bar to move in it, previous and next, **Shuffle**, **Repeat** (all or one), the speed from 0.5× to 2×, and the list, to tap another. A video, or music of 10 minutes or more, starts where you left it. The notification shows the title and cover only with **Show the title in the notification** on. See [Collection](#collection).":
    "**Una pantalla de reproducción para la Colección**: toca la barra de la música que suena, o **Sonando ahora**, para ver la portada, el título, el artista y el álbum, una barra para moverte en ella, anterior y siguiente, **Aleatorio**, **Repetir** (todo o uno), la velocidad de 0.5× a 2× y la lista, para tocar otra. Un vídeo, o música de 10 minutos o más, empieza donde lo dejaste. La notificación muestra el título y la portada solo con **Mostrar el título en la notificación** activado. Consulta [Colección](#collection).",
  "**Photos, Videos, Music and Files**: the Collection has a tab for each, each with the folders that hold any of its files above it. See [Collection](#collection).":
    "**Fotos, Vídeos, Música y Archivos**: la Colección tiene una pestaña para cada uno, con encima las carpetas que tienen algo suyo. Consulta [Colección](#collection).",
  "**Music of the Collection goes on with the screen off**: on Android, music could stop a while after the screen went off. Now the player is kept in the foreground for as long as the list plays. See [Collection](#collection).":
    "**La música de la Colección sigue con la pantalla apagada**: en Android, la música podía pararse un rato después de apagarse la pantalla. Ahora el reproductor se mantiene en primer plano mientras suena la lista. Consulta [Colección](#collection).",
  "**More music and video formats in the Collection**: on Android MP3, AAC, M4A, FLAC, Ogg, Opus, WAV, AMR, MP4, MKV, WebM and 3GP play, also a file that came with no type, known by its name's ending, and seeking works in an MP3 with no table of its seconds. See [Collection](#collection).":
    "**Más formatos de música y vídeo en la Colección**: en Android se reproducen MP3, AAC, M4A, FLAC, Ogg, Opus, WAV, AMR, MP4, MKV, WebM y 3GP, también un archivo que llegó sin tipo, reconocido por la terminación de su nombre, y saltar a un punto funciona también en un MP3 sin tabla de sus segundos. Consulta [Colección](#collection).",
  "**New modules on after an update**: where the modules were chosen before the Collection came, as on a phone or computer updated from 6, the Collection stayed off. Now it is on there, as is any module that comes later, until you turn it off in Settings → General → Modules. See [Modules](#modules).":
    "**Módulos nuevos activados tras una actualización**: donde los módulos se eligieron antes de que llegara la Colección, como en un teléfono o un ordenador actualizado desde la 6, la Colección seguía desactivada. Ahora está activada ahí, como cualquier módulo que llegue después, hasta que la desactives en Ajustes → General → Módulos. Mira [Módulos](#modules).",
  "**A home relay by itself**: on Android, when your relay names a relay paired with it, a space with no home relay takes that one, only through Tor, with its token from a coupon: nothing to type. **Automatically from your relay**, under Settings → Relay and networks → Home relay, turns it off. See [Home relay](#home-relay).":
    "**Un relay de casa por sí solo**: en Android, cuando tu relay nombra un relay emparejado con él, un espacio sin relay de casa toma ese, solo por Tor, con su token de un cupón: nada que escribir. **Automáticamente desde tu relay**, en Ajustes → Relay y redes → Relay de casa, lo desactiva. Mira [Relay de casa](#home-relay).",
  "**A chip for every part that is on**: above the chats, **SMS**, **Erevos**, **Matrix**, **XMPP** and **Nostr** each have their chip whenever they are on in Modules, also with no chat yet. Before, in a space with only SMS so far, choosing **All messages** after Erevos's icon opened its chats hid the chips, with no way back.":
    "**Un chip para cada parte activada**: encima de los chats, **SMS**, **Erevos**, **Matrix**, **XMPP** y **Nostr** tienen cada uno su chip siempre que estén activados en Módulos, también sin ningún chat aún. Antes, en un espacio con solo SMS por ahora, elegir **Todos** después de que el icono de Erevos abriera sus chats ocultaba los chips, sin forma de volver.",
  "**Invite at one tap**: on the home screen, **Invite** beside the relay's line shows an invite's QR code at once, with nothing to type: who it is for and your name for them can be typed below it, or never. See [Chat through a relay](#relay).":
    "**Invitar con un toque**: en la pantalla de inicio, **Invitar** junto a la línea del relay muestra al instante el código QR de una invitación, sin escribir nada: para quién es y tu nombre para esa persona se pueden escribir debajo, o nunca. Ver [Chatear a través de un relay](#relay).",
  "**Sign in with LPHL without typing a code**: on Android, once you sign in on the page the browser opened, tap **Open Erevos** there, and Erevos finishes signing in by itself. The code to type is still on the page, in case nothing opens. It needs the relay updated. See [Chat through a relay](#relay).":
    "**Iniciar sesión con LPHL sin escribir un código**: en Android, tras iniciar sesión en la página que abrió el navegador, toca allí **Abrir Erevos** y Erevos termina de iniciar sesión solo. El código para escribir sigue en la página, por si no se abre nada. Necesita el relay actualizado. Consulta [Chatear a través de un relay](#relay).",
  "**Invites and contact links by touch**: on an Android phone with NFC, while **Invite someone** or **My QR code** shows the small QR code, hold the back of their phone to the back of yours: their phone opens it by itself, in Erevos where it is installed. See [Chat through a relay](#relay).":
    "**Invitaciones y enlaces de contacto con un toque**: en un teléfono Android con NFC, mientras **Invitar a alguien** o **Mi código QR** muestra el código QR pequeño, junta la parte de atrás de su teléfono con la del tuyo: su teléfono lo abre solo, en Erevos si lo tiene instalado. Consulta [Chatear a través de un relay](#relay).",
  "**Smaller invite QR codes**: the QR code of **Invite someone** now holds about eight times less, so simpler and older cameras read it too, and its link is short enough for an SMS. It opens Erevos's page for invites, which offers Erevos and then opens the invite in it. Where your relay lets this phone make no invite, the long one is still made. See [Chat through a relay](#relay).":
    "**Códigos QR de invitación más pequeños**: el código QR de **Invitar a alguien** contiene ahora unas ocho veces menos, así que también lo leen cámaras más sencillas y antiguas, y su enlace es lo bastante corto para un SMS. Abre la página de invitaciones de Erevos, que ofrece Erevos y luego abre la invitación en él. Donde tu relay no deja a este teléfono hacer invitaciones, se sigue haciendo la larga. Consulta [Chatear a través de un relay](#relay).",
  "**A small contact QR code**: **Show my QR code** now shows your contact link in short, so any camera reads it, and **Share my contact link** sends a link any app lets you tap. Whoever scans it while it shows is your contact at once; later, they write a message request first. **Large QR code, for no internet** shows the whole one, for near with no internet. See [Chat through a relay](#relay).":
    "**Un código QR de contacto pequeño**: **Mostrar mi código QR** ahora muestra tu enlace de contacto en corto, así que cualquier cámara lo lee, y **Compartir mi enlace de contacto** envía un enlace que cualquier app te deja tocar. Quien lo escanea mientras se muestra es tu contacto al instante; más tarde, escribe primero una solicitud de mensaje. **Código QR grande, sin internet** muestra el entero, para cerca y sin internet. Ver [Chatear a través de un relay](#relay).",
  "**Links open Erevos**: on Android, an invite or contact link tapped in any app opens Erevos, which asks before it takes it, once the web server and a new Erevos are both out. See [Chat through a relay](#relay).":
    "**Los enlaces abren Erevos**: en Android, un enlace de invitación o de contacto tocado en cualquier app abre Erevos, que pregunta antes de aceptarlo, cuando salgan el servidor web y un Erevos nuevo. Ver [Chatear a través de un relay](#relay).",
  "**Home relay**: the screen no longer says that whoever runs a home relay sees this phone's address when it is set to **Only through Tor**.":
    "**Relay de casa**: la pantalla ya no dice que quien gestiona un relay de casa ve la dirección de este teléfono cuando está en **Solo por Tor**.",
  "**An invite that opened Erevos for the first time** opens once the first start's setup is done, however long it took; before, after five minutes on the setup screens it was lost.":
    "**Una invitación que abrió Erevos por primera vez** se abre cuando termina la configuración del primer inicio, por mucho que tarde; antes, tras cinco minutos en las pantallas de configuración, se perdía.",
  // 7.0.0-rc.1
  "**Linked devices on the same Wi-Fi**: the phone and a computer on the same Wi-Fi or hotspot give each other what changes straight there, with no internet too. See [Linked devices](#devices).":
    "**Dispositivos vinculados en la misma Wi-Fi**: el teléfono y un ordenador en la misma Wi-Fi o punto de acceso se dan lo que cambia directamente allí, también sin internet. Ver [Dispositivos vinculados](#devices).",
  "**Your Matrix, XMPP and Nostr accounts on every linked device**: each device linked gets them by itself, with no choice to make, and they follow as they change on the phone: one you sign out of there, or replace with another, goes from the devices too. See [Linked devices](#devices).":
    "**Tus cuentas de Matrix, XMPP y Nostr en cada dispositivo vinculado**: cada dispositivo vinculado las recibe solo, sin nada que elegir, y siguen los cambios del teléfono: la que cierres allí, o cambies por otra, se va también de los dispositivos. Ver [Dispositivos vinculados](#devices).",
  "**Same settings on your linked devices**: the language, the look and Last seen changed on the phone or a computer change on the others too. A photo behind the screens, passwords, PINs and what is about one device alone stay on each. A device can keep its own: **Same settings on every device** in Linked devices. See [Linked devices](#devices).":
    "**Los mismos ajustes en tus dispositivos vinculados**: el idioma, el aspecto y Última vez cambiados en el teléfono o en un ordenador cambian también en los otros. Una foto detrás de las pantallas, las contraseñas, los PIN y lo que atañe a un solo dispositivo se quedan en cada uno. Un dispositivo puede guardar los suyos: **Los mismos ajustes en todos los dispositivos** en Dispositivos vinculados. Ver [Dispositivos vinculados](#devices).",
  "**Last seen**: when a contact is not online, their chat says when they last had Erevos open, to the minute. It goes end-to-end encrypted, never to the relay. It is on, and both ways: turn it off in Settings → Privacy and security → Last seen, and no one sees yours, nor you theirs. Hidden chats have their own time and their own switch, in a chat's details there. See [Chat through a relay](#relay).":
    "**Última vez**: cuando un contacto no está en línea, su chat dice cuándo tuvo Erevos abierto por última vez, al minuto. Va cifrada de extremo a extremo, nunca al relay. Está activada, y en los dos sentidos: desactívala en Ajustes → Privacidad y seguridad → Última vez, y nadie ve la tuya, ni tú la suya. Los chats ocultos tienen su propia hora y su propio interruptor, en los detalles de un chat de allí. Consulta [Chatear a través de un relay](#relay).",
  "**One Public feed**: the new **Public** chip on the home screen shows the public posts of the Nostr people you follow and the public Matrix rooms you are in as one feed, as in Amethyst, with photos inside the posts and a card for a link. Answer, share again, like, share and write new posts with photos; for Matrix, answer, react and share. **Photos** chooses whether photos come at once, only through Tor or on a tap. The **Nostr** chip shows only the Nostr chats again. See [Chats with other Nostr apps](#nostr-chats).":
    "**Un feed público**: el nuevo botón **Público** de la pantalla de inicio muestra en un solo feed, como en Amethyst, las publicaciones públicas de las personas de Nostr que sigues y las salas públicas de Matrix en las que estás, con las fotos dentro de las publicaciones y una tarjeta para un enlace. Responde, comparte de nuevo, da Me gusta, comparte y escribe publicaciones nuevas con fotos; en Matrix, responde, reacciona y comparte. **Fotos** elige si las fotos llegan al instante, solo por Tor o al tocar. El botón **Nostr** vuelve a mostrar solo los chats de Nostr. Ver [Chats con otras apps de Nostr](#nostr-chats).",
  "**Collection**: an encrypted place in every space and hidden place for photos, files and folders, with its icon next to the lock. Turn it on in Modules. See [Collection](#collection).":
    "**Colección**: un lugar cifrado en cada espacio y lugar oculto para fotos, archivos y carpetas, con su icono junto al candado. Actívala en Módulos. Mira [Colección](#collection).",
  "**Music, videos and PDFs in the Collection**: music and videos play from their encrypted pieces, music on with the screen off and with play, pause, next and previous on the lock screen, and PDFs read page by page inside Erevos. **Open with another app** leaves no plain copy, and a photo or video picked from the gallery can be deleted there after importing. See [Collection](#collection).":
    "**Música, vídeos y PDF en la Colección**: la música y los vídeos se reproducen desde sus trozos cifrados, la música también con la pantalla apagada, con reproducir, pausa, siguiente y anterior en la pantalla de bloqueo, y los PDF se leen página a página dentro de Erevos. **Abrir con otra aplicación** no deja ninguna copia sin cifrar, y una foto o un vídeo de la galería se puede borrar de allí tras importarlo. Mira [Colección](#collection).",
  "**The Collection on a computer**: in the desktop app for Linux, macOS and Windows the Collection keeps your photos and files encrypted too. Photos, PDFs, music and videos open in memory only, never as a plain copy on the disk, and close when the space locks. **Save to the computer** asks first. See [Collection](#collection).":
    "**La Colección en el ordenador**: en la aplicación de escritorio para Linux, macOS y Windows la Colección también guarda tus fotos y archivos cifrados. Fotos, PDF, música y vídeos se abren solo en memoria, nunca como copia sin cifrar en el disco, y se cierran cuando el espacio se bloquea. **Guardar en el ordenador** pregunta antes. Consulta [Colección](#collection).",
  "**Files up to 4 GB in the Collection**: on Android a file picked from the phone's files is encrypted as it is read, with no plain copy first, so it comes in faster and needs no room twice. In the desktop app music and videos up to 1 GB play. See [Collection](#collection).":
    "**Archivos de hasta 4 GB en la Colección**: en Android, un archivo elegido de los archivos del teléfono se cifra a medida que se lee, sin una copia sin cifrar antes, así entra más rápido y no necesita el doble de espacio. En la aplicación de escritorio se reproducen música y vídeos de hasta 1 GB. Consulta [Colección](#collection).",
  "**The Collection on a WebDAV server**: each space and hidden place can copy its Collection, still encrypted, to a folder on a server you choose, Nextcloud, ownCloud or any that speaks WebDAV, so big files are not only on the phone. Only what is new goes, and a phone that lacks a file fetches it from there. See [Collection](#collection).":
    "**La Colección en un servidor WebDAV**: cada espacio y cada lugar oculto puede copiar su Colección, cifrada, a una carpeta en un servidor que eliges, Nextcloud, ownCloud o cualquiera que hable WebDAV, para que los archivos grandes no estén solo en el teléfono. Solo va lo nuevo, y un teléfono al que le falta un archivo lo trae de allí. Mira [Colección](#collection).",
  "**The Collection on your linked devices**: turn on **On my linked devices too** in a Collection's settings and that Collection goes to the space's or hidden place's linked devices, changes and deletions with it. Small pictures come at once, a file itself on the same Wi-Fi or when you open it, a piece at a time, going on where it stopped after the network drops. See [Collection](#collection).":
    "**La Colección en tus dispositivos vinculados**: activa **También en mis dispositivos vinculados** en los ajustes de una Colección y esa Colección va a los dispositivos vinculados del espacio o lugar oculto, con sus cambios y borrados. Las miniaturas llegan enseguida, el archivo en sí en la misma Wi-Fi o cuando lo abres, trozo a trozo, siguiendo donde se quedó si se corta la red. Mira [Colección](#collection).",
  "**Groups stay on the device you choose**: on the phone, under Linked devices → Groups stay on, move the groups to a linked computer. Their keys go there, never copied, so the groups work there with the phone off and new ones can be made there; members see nothing new. See [Linked devices](#devices).":
    "**Los grupos están en el dispositivo que elijas**: en el teléfono, en Dispositivos vinculados → Los grupos están en, mueve los grupos a un ordenador vinculado. Sus claves van allí, nunca copiadas, así que los grupos funcionan allí con el teléfono apagado y se pueden crear grupos nuevos allí; los miembros no ven nada nuevo. Consulta [Dispositivos vinculados](#devices).",
  "**Add someone new on a linked device without the phone**: a computer adds someone whose contact link is from this version by itself, with the phone off, and writes to them at once; they see your account as a request, with the same safety number, and the phone adds them too once it is on. See [Linked devices](#devices).":
    "**Añade a alguien nuevo en un dispositivo vinculado sin el teléfono**: un ordenador añade por sí mismo a alguien cuyo enlace de contacto es de esta versión, con el teléfono apagado, y le escribe enseguida; esa persona ve tu cuenta como una solicitud, con el mismo número de seguridad, y el teléfono la añade también en cuanto se enciende. Consulta [Dispositivos vinculados](#devices).",
  "**Calls and Send later on your linked devices without the phone**: with a contact on this version, a computer calls and is called by itself and sends a message for later itself, with the phone off, and a copy goes to each of their devices too, held till its time. Every device of yours shows what is scheduled, and deleting it on any of them takes it back everywhere. See [Linked devices](#devices).":
    "**Llamadas y Enviar más tarde en tus dispositivos vinculados sin el teléfono**: con un contacto con esta versión, un ordenador llama y recibe llamadas por sí mismo y envía él mismo un mensaje para más tarde, con el teléfono apagado, y una copia va también a cada uno de sus dispositivos, guardada hasta su hora. Cada dispositivo tuyo muestra lo programado, y eliminarlo en cualquiera de ellos lo retira en todos. Consulta [Dispositivos vinculados](#devices).",
  '**Support Erevos**: every way has its QR code now, Liberapay and PayPal too, and PayPal opens in the browser.':
    '**Apoyar Erevos**: cada forma tiene ahora su código QR, también Liberapay y PayPal, y PayPal se abre en el navegador.',
  '**Chats open at their end**: a long chat, or one with imported messages, could open at a message read long ago, often a photo, as it drew earlier messages on its way to the end. Now it opens at the newest message, and the arrow to where you left off is there when new ones came.':
    '**Los chats se abren en su final**: un chat largo, o uno con mensajes importados, podía abrirse en un mensaje leído hacía mucho, a menudo una foto, al cargar mensajes anteriores de camino al final. Ahora se abre en el mensaje más reciente, y la flecha hasta donde lo dejaste está ahí cuando llegaron nuevos.',
  "**Tor off unless you turn it on**: a new space sends nothing through Tor, so messages go fastest, and turning Tor on asks first, as it makes them slower. A space you already have keeps its choice, under Settings → Relay and networks → Tor. Texts through Nostr now go without Tor too: then the Nostr relays see your phone's internet address, never who wrote to whom. See [Through Tor](#tor).":
    "**Tor desactivado hasta que lo actives**: un espacio nuevo no envía nada por Tor, así que los mensajes van más rápido, y activar Tor pregunta antes, porque los hace más lentos. Un espacio que ya tienes conserva su elección, en Ajustes → Relay y redes → Tor. Los textos por Nostr ahora también van sin Tor: entonces los relays de Nostr ven la dirección de internet de tu teléfono, nunca quién escribió a quién. Ver [Por Tor](#tor).",
  "**Moving a chat to a space with no relay**: **Move to another space** stopped there, as that space had no relay of its own. Now it offers this space's relay, which that space then keeps, and it makes that space's relay queue when it has a relay but no queue yet. See [Second password](#second).":
    "**Mover un chat a un espacio sin relay**: **Mover a otro espacio** se detenía ahí, porque ese espacio no tenía relay propio. Ahora ofrece el relay de este espacio, que ese espacio conserva después, y crea la cola de ese espacio en el relay cuando tiene relay pero aún no cola. Consulta [Segunda contraseña](#second).",
  "**Fixes from a review of all the code**: a message you were typing stays with its chat when you open another, and never shows in a PIN-locked chat's place; a locked chat under a locked group stays out of screenshots when the group closes; the Collection's catalogue goes into backups, so a restored phone opens its files; calls in a public group reach their members; a Matrix or XMPP account no longer stops for good at one bad message or an unreachable server; a message sent for later stays listed while its details are still coming; the computer app's Wi-Fi link refuses an impossible port; and the panic button lets the apps it tells start before it closes.":
    "**Correcciones de una revisión de todo el código**: un mensaje que estabas escribiendo se queda con su chat cuando abres otro, y nunca aparece en el lugar de un chat con PIN; un chat bloqueado bajo un grupo bloqueado sigue fuera de las capturas de pantalla cuando el grupo se cierra; el catálogo de la Colección entra en las copias de seguridad, así que un teléfono restaurado abre sus archivos; las llamadas en un grupo público llegan a sus miembros; una cuenta de Matrix o XMPP ya no se detiene para siempre en un mensaje dañado o en un servidor inalcanzable; un mensaje para más tarde sigue en la lista mientras aún llegan sus datos; el enlace Wi-Fi de la aplicación de ordenador rechaza un puerto imposible; y el botón de pánico deja que las aplicaciones que avisa arranquen antes de cerrarse.",
  "**Safer in twelve more ways, from the review before 7**: a message the relay hands you is deleted there only once your phone has kept it, so a connection cut at that moment loses nothing (an older relay works as before); a relay keeps a bound on what it holds in all and for each phone; in a public group no one can have another member taken out by claiming to be them; with SMS invites off, no one becomes a contact from your number alone; searches that find nothing are forgotten after a quarter of an hour; a Matrix message is shown as its sender's only when the key came from their device, else as **Not verified**, and an XMPP or Matrix device that changes its key gets nothing until you accept it, while a new device is said in the chat; a photo or file from a server its sender chose is fetched by itself only through Tor, else on a tap; an old first packet replayed to you never takes over a chat; and your linked devices' log takes each device's changes only from that device, and forgets devices that are gone.":
    "**Más seguro de doce maneras más, de la revisión antes de 7**: un mensaje que el relay te entrega se borra allí solo cuando tu teléfono lo ha guardado, así que una conexión cortada en ese momento no pierde nada (un relay antiguo funciona como antes); un relay mantiene un límite de lo que guarda en total y por cada teléfono; en un grupo público nadie puede hacer que expulsen a otro miembro haciéndose pasar por él; con las invitaciones SMS desactivadas, nadie se convierte en contacto solo por tu número; las búsquedas que no encuentran nada se olvidan tras un cuarto de hora; un mensaje de Matrix se muestra como de su remitente solo cuando la clave vino de su dispositivo, si no como **No verificado**, y un dispositivo XMPP o Matrix que cambia de clave no recibe nada hasta que lo aceptes, mientras que un dispositivo nuevo se anuncia en el chat; una foto o un archivo de un servidor elegido por el remitente se descarga solo únicamente por Tor, si no con un toque; un primer paquete antiguo que te reenvían nunca se apodera de un chat; y el registro de tus dispositivos vinculados toma los cambios de cada dispositivo solo de ese dispositivo, y olvida los que se fueron.",
  "**A home relay only through Tor**: switch a home relay to **Only through Tor** and it never sees your phone's address, whatever Tor is set to for the rest. With no token typed, it gives one for a coupon that your relay signs blind, so neither relay can tell whose it is, and two spaces can use each other's relays as home relays with nothing tying them together. The token comes within the hour, lasts 90 days, and Erevos renews it by itself. Needs Tor, on Android. See [Home relay](#home-relay).":
    '**Un relay de casa solo por Tor**: pon un relay de casa en **Solo por Tor** y nunca ve la dirección de tu teléfono, sea cual sea el ajuste de Tor para el resto. Sin token escrito, da uno a cambio de un cupón que tu relay firma a ciegas, así que ninguno de los dos relays puede saber de quién es, y dos espacios pueden usar los relays del otro como relays de casa sin que nada los relacione. El token llega en menos de una hora, dura 90 días y Erevos lo renueva por sí solo. Necesita Tor, en Android. Mira [Relay de casa](#home-relay).',
  // 6.0.0-rc.2
  "**Home's buttons stay at the bottom**: after the password, home's **Remind me** and **New chat** could float halfway up the screen, over the chats, with the list ending above them, until Erevos went away and came back. Now the screen asks Android at once whether a keyboard is open. See [Password lock](#lock).":
    "**Los botones de la pantalla de inicio se quedan abajo**: tras la contraseña, **Recordarme** y **Chat nuevo** podían flotar a media pantalla, sobre los chats, con la lista terminando por encima de ellos, hasta salir de Erevos y volver. Ahora la pantalla pregunta enseguida a Android si hay un teclado abierto. Ver [Bloqueo con contraseña](#lock).",
  "**The Nostr tab's posts come**: **Posts** could stay on **Looking…** for good through Tor. Each wait through Tor took one of the threads the whole app shares, and once all were taken, every look-up of the posts waited behind the others; a relay that answered and then could not be reached kept them waiting with no end. Now Tor's waits have threads of their own, a relay that cannot be reached is let be after 20 seconds, and the posts come within about two minutes at most, with what was found by then. See [Chats with other Nostr apps](#nostr-chats).":
    "**Llegan las publicaciones de la pestaña Nostr**: **Publicaciones** podía quedarse para siempre en **Buscando…** a través de Tor. Cada espera a través de Tor ocupaba uno de los hilos que comparte toda la app, y cuando estaban todos ocupados, cada búsqueda de las publicaciones esperaba detrás de las demás; un relay que respondió y luego no se pudo alcanzar las dejaba esperando sin fin. Ahora las esperas de Tor tienen hilos propios, un relay que no se puede alcanzar se deja tras 20 segundos, y las publicaciones llegan en unos dos minutos como mucho, con lo que se encontró hasta entonces. Consulta [Chats con otras apps de Nostr](#nostr-chats).",
  "**Linux, Windows and macOS again**: 6.0.0-rc.1 came out without them: the check that each build for computers opens did not know the setup of Erevos's very first start. Now it does.":
    "**De nuevo Linux, Windows y macOS**: 6.0.0-rc.1 salió sin ellos: la comprobación de que cada versión para ordenador se abre no conocía la configuración del primerísimo inicio de Erevos. Ahora la conoce.",
  // 6.0.0-rc.1
  "**Links open on Sailfish OS**: **Sign in with LPHL**, a donation page or a link in a chat opened nothing there. Now Sailfish OS opens them: a web page in the browser, a number in the phone or the messages, an address in the mail.":
    "**Los enlaces se abren en Sailfish OS**: **Iniciar sesión con LPHL**, una página de donación o un enlace en un chat no abrían nada allí. Ahora Sailfish OS los abre: una página web en el navegador, un número en el teléfono o en los mensajes, una dirección en el correo.",
  "**Matrix, and photos and files in XMPP and Nostr chats, on Sailfish OS**: Erevos there could not reach their servers over HTTPS, so Matrix could not sign in, photos and files neither came nor went, and links showed no preview. Now they work as on a computer.":
    "**Matrix, y fotos y archivos en los chats de XMPP y Nostr, en Sailfish OS**: allí Erevos no llegaba a sus servidores por HTTPS, así que Matrix no podía iniciar sesión, las fotos y los archivos ni llegaban ni salían y los enlaces no mostraban vista previa. Ahora funcionan como en un ordenador.",
  "**A phone call shows its screen**: with Erevos as the phone app, a call that came could ring with the phone's screen black, so it could not be answered, when Android's full-screen notifications for Erevos, Erevos's notices or its notices of incoming calls were off. Now the call screen comes up by itself, over the lock screen too, and turns the screen on. A call that Do Not Disturb holds back still comes quietly, with the screen off. See [Phone](#phone).":
    "**Una llamada de teléfono muestra su pantalla**: con Erevos como app de teléfono, una llamada entrante podía sonar con la pantalla negra, sin poder contestarla, cuando estaban desactivadas las notificaciones a pantalla completa de Android para Erevos, los avisos de Erevos o sus avisos de llamadas entrantes. Ahora la pantalla de llamada aparece sola, también sobre la pantalla de bloqueo, y enciende la pantalla. Una llamada que «No molestar» retiene sigue llegando en silencio, con la pantalla apagada. Consulta [Teléfono](#phone).",
  "**The calculator shows a long result from its start**: upright, a result with many decimals hid its first digits, which showed only with the phone turned sideways. Now a long number gets smaller to fit, its first digits always in sight.":
    "**La calculadora muestra un resultado largo desde el principio**: en vertical, un resultado con muchos decimales ocultaba sus primeras cifras, que solo se veían con el teléfono en horizontal. Ahora un número largo se hace más pequeño hasta caber, con sus primeras cifras siempre a la vista.",
  "**Pick the recipient of a new SMS from your contacts**: **New SMS** has a **Contacts** button that opens your contacts with a search, and typing a name or number suggests the contacts that match. A contact with several numbers shows a line for each, and for a group MMS each one you pick is added. With only the SMS open, only the phone's contacts show. See [SMS](#sms).":
    "**Elige al destinatario de un SMS nuevo entre tus contactos**: **SMS nuevo** tiene un botón **Contactos** que abre tus contactos con búsqueda, y al escribir un nombre o un número se sugieren los contactos que coinciden. Un contacto con varios números muestra una línea por cada uno, y en un MMS de grupo cada contacto que elijas se añade. Con solo los SMS abiertos, solo salen los contactos del teléfono. Ver [SMS](#sms).",
  "**More for a number in the Phone**: on the keypad, **⋯** beside a typed number offers **Add to contacts**, **Add to an existing contact**, **Send an SMS** and **Copy the number**. **Recents** and **Favourites** offer **Copy the number** and **Open the contact**; **Favourites** also **Send an SMS**, and **Recents** adds an unknown number to an existing contact. With Erevos locked, the Phone still only calls. See [Phone](#phone).":
    "**Más para un número en el Teléfono**: en el teclado, **⋯** junto a un número escrito ofrece **Añadir a contactos**, **Añadir a un contacto existente**, **Enviar un SMS** y **Copiar el número**. **Recientes** y **Favoritos** ofrecen **Copiar el número** y **Abrir el contacto**; **Favoritos** también **Enviar un SMS**, y **Recientes** añade un número desconocido a un contacto existente. Con Erevos bloqueado, el Teléfono sigue solo llamando. Ver [Teléfono](#phone).",
  "**A short buzz on touch**: the keys of the keypad, **Call**, **End**, Send, the keyboard's Enter, switches and menus that open give a short buzz. **Settings** → **Appearance** → **Vibrate on touch** turns it off. See [Appearance](#appearance).":
    "**Una vibración breve al tocar**: las teclas del teclado, **Llamar**, **Colgar**, Enviar, el Intro del teclado, los interruptores y los menús que se abren dan una vibración breve. En **Ajustes** → **Apariencia** → **Vibrar al tocar** la desactivas. Ver [Apariencia](#appearance).",
  "**A number on each icon, on Huawei and Honor**: their launchers now show a number on each of Erevos's icons apart, with **Number on the icon** on: on Erevos's own the messages, on SMS's the SMS not read, on Phone's the missed calls, on Contacts's a birthday today. Most other launchers, such as those of Pixel and GrapheneOS, Samsung's and Kvaesitso, give a notice's dot or number to all of an app's icons alike, and Erevos cannot change that there. See [Appearance](#appearance).":
    "**Un número en cada icono, en Huawei y Honor**: sus lanzadores ya muestran un número en cada icono de Erevos por separado, con **Número en el icono** activado: en el de Erevos los mensajes, en el de SMS los SMS sin leer, en el de Teléfono las llamadas perdidas, en el de Contactos un cumpleaños de hoy. La mayoría de los otros lanzadores, como los de los Pixel y GrapheneOS, el de Samsung y Kvaesitso, dan el punto o el número de un aviso a todos los iconos de una app por igual, y ahí Erevos no puede cambiarlo. Consulta [Apariencia](#appearance).",
  "**Choose the parts of Erevos you use**: Erevos's own chats, the Phone, the SMS, and the chats with Nostr, Matrix and XMPP apps are modules now, any of them on, Erevos's own too, at least one. One that is off does not start and shows nowhere, and the Phone's and the SMS's icons leave the phone's apps: Erevos is lighter, opens faster and uses less battery. Nothing of it is deleted: it is all there again when it is back on. Erevos's very first start sets it up as an installer does, its language, the modules and what Android should allow for them; a module turned on later asks for its permissions again. After this update every module stays on until you change them in **Settings** → **General** → **Modules**. See [Modules](#modules).":
    "**Elige las partes de Erevos que usas**: los chats propios de Erevos, el Teléfono, los SMS y los chats con apps de Nostr, Matrix y XMPP son ahora módulos, cualquiera de ellos puede estar activado, también el propio de Erevos, al menos uno. Uno desactivado no se inicia y no se muestra en ningún sitio, y los iconos del Teléfono y de los SMS salen de las apps del teléfono: Erevos es más ligero, abre más rápido y gasta menos batería. No se borra nada de él: vuelve a estar todo cuando se activa de nuevo. El primerísimo inicio de Erevos lo configura como hace un instalador, su idioma, los módulos y lo que Android debe permitir para ellos; un módulo activado más tarde vuelve a pedir sus permisos. Tras esta actualización todos los módulos siguen activados hasta que los cambies en **Ajustes** → **General** → **Módulos**. Ver [Módulos](#modules).",
  "**Public posts in the Nostr tab**: on the home screen, the Nostr tab shows first **Posts**, the public posts of the people your Nostr key follows and what they shared again, newest first, as in Amethyst or a Telegram channel, with **Chats** one tap away. Older ones come as you scroll to the end, the newest when you pull the list down; tap who wrote a post for their posts or to write to them. Read only, looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Publicaciones públicas en la pestaña Nostr**: en la pantalla de inicio, la pestaña Nostr muestra primero **Publicaciones**, las publicaciones públicas de las personas que sigue tu clave de Nostr y lo que volvieron a compartir, lo más reciente primero, como en Amethyst o en un canal de Telegram, con **Chats** a un toque. Las anteriores llegan al desplazarte hasta el final, las más recientes al tirar de la lista hacia abajo; toca a quien escribió una publicación para ver sus publicaciones o para escribirle. Solo de lectura, se buscan por Tor como indica el espacio y no se guardan, y no se abren imágenes ni enlaces. Ver [Chats con otras apps de Nostr](#nostr-chats).",
  "**Hidden chats on your linked devices**: each place of hidden chats now links on its own, from inside it, to the same place on a computer or in a browser, with **Linked devices** under its list. Its chats, messages, groups, calls, Chat with myself and its own Matrix, XMPP and Nostr accounts go there, and its contacts write to it there directly. Nothing of it shows in the space or on the space's linked devices. The link runs while the place is open, and while it is closed too with **Receive while closed** on. See [Linked devices](#devices).":
    "**Chats ocultos en tus dispositivos vinculados**: cada lugar de chats ocultos se vincula ahora por su cuenta, desde dentro, al mismo lugar en un ordenador o en un navegador, con **Dispositivos vinculados** bajo su lista. Sus chats, mensajes, grupos, llamadas, su Chat conmigo y sus propias cuentas de Matrix, XMPP y Nostr van allí, y sus contactos le escriben allí directamente. Nada de ello se ve en el espacio ni en los dispositivos vinculados del espacio. El vínculo funciona mientras el lugar está abierto, y también cerrado con **Recibir estando cerrados** activado. Consulta [Dispositivos vinculados](#devices).",
  "**Move a chat to another space**: in a chat's **Details**, **Move to another space** takes it, with its messages, name, picture, look and imported chats, into the space whose password you type, as a move into hidden chats does: the safety number stays the same, and their phone is told at once to write there. That space stays closed, and the row shows in every space. A chat never takes the place of one that space, or hidden chats, already have with the same person. See [Second password](#second).":
    "**Mover un chat a otro espacio**: en los **Detalles** de un chat, **Mover a otro espacio** lo lleva, con sus mensajes, nombre, imagen, aspecto y chats importados, al espacio cuya contraseña escribes, como al moverlo a chats ocultos: el número de seguridad sigue igual, y a su teléfono se le dice al instante que escriba allí. Ese espacio sigue cerrado, y la opción se ve en todos los espacios. Un chat nunca ocupa el lugar de otro que ese espacio, o unos chats ocultos, ya tengan con la misma persona. Mira [Segunda contraseña](#second).",
  // 4.0.0-rc.10
  "**Erevos no longer stops when only the SMS or the Contacts are open**: from them, a contact's chat, an SMS, another icon or a screen that asks for the password again could make Erevos say it could not open (Maximum call stack size exceeded). Now the password opens all of Erevos, then that screen. And when Erevos cannot open, **Try again** starts it again. See [Password lock](#lock).":
    "**Erevos ya no se detiene cuando solo están abiertos los SMS o los contactos**: desde ahí, el chat de un contacto, un SMS, otro icono o una pantalla que vuelve a pedir la contraseña podían hacer que Erevos dijera que no pudo abrirse (Maximum call stack size exceeded). Ahora la contraseña abre todo Erevos y luego esa pantalla. Y cuando Erevos no puede abrirse, **Volver a intentarlo** lo inicia de nuevo. Consulta [Bloqueo con contraseña](#lock).",
  "**Each icon opens what it names**: after Erevos was opened by the SMS icon, or from the recent apps, another icon, the widget or a notice could sometimes show the SMS instead. Now each opens what it names. With only the SMS or the Contacts open, another icon asks for the password as when Erevos is locked, then opens its own part: the Contacts icon only the contacts, Erevos's own icon all of it. And Back on Erevos's first screen now puts it behind, as Home does, whatever opened it. See [Password lock](#lock).":
    "**Cada icono abre lo que nombra**: después de abrirse Erevos con el icono de SMS o desde las apps recientes, otro icono, el widget o un aviso podían mostrar a veces los SMS en su lugar. Ahora cada uno abre lo que nombra. Con solo los SMS o los contactos abiertos, otro icono pide la contraseña como cuando Erevos está bloqueado y luego abre su propia parte: el icono de Contactos solo los contactos, el icono propio de Erevos todo Erevos. Y Atrás en la primera pantalla de Erevos ahora lo deja en segundo plano, como Inicio, lo que sea que lo haya abierto. Consulta [Bloqueo con contraseña](#lock).",
  // 4.0.0-rc.9
  "**Only the Contacts**: with Erevos locked, the Contacts icon, the widget's Contacts button and the notice of a birthday ask for the password, then open only the contacts. A chat, an SMS, Settings, and the orange padlock **Unlock everything**, ask for it again, then open all of Erevos. See [Password lock](#lock).":
    "**Solo los Contactos**: con Erevos bloqueado, el icono de Contactos, el botón Contactos del widget y el aviso de un cumpleaños piden la contraseña y luego abren solo los contactos. Un chat, un SMS, Ajustes y el candado naranja **Desbloquear todo** la piden otra vez y luego abren todo Erevos. Consulta [Bloqueo con contraseña](#lock).",
  "**Old private messages in Nostr chats**: Erevos also reads private messages sent the older way (NIP-04), which Damus, Primal and many apps still send and keep, past and new, in the same chats. The relays see who wrote such a message to whom; Erevos itself still sends only the NIP-17 way. See [Chats with other Nostr apps](#nostr-chats).":
    "**Mensajes privados antiguos en los chats de Nostr**: Erevos también lee los mensajes privados enviados a la manera antigua (NIP-04), que Damus, Primal y muchas apps aún envían y guardan: pasados y nuevos, en los mismos chats. Los relays ven quién escribió uno de estos mensajes a quién; el propio Erevos sigue enviando solo a la manera de NIP-17. Consulta [Chats con otras apps de Nostr](#nostr-chats).",
  "**Public posts in Nostr chats**: in a chat with one person, **Public posts** shows what they post for everyone, newest first, read only. It is looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Publicaciones públicas en los chats de Nostr**: en un chat con una persona, **Publicaciones públicas** muestra lo que publica para todos, las más recientes primero, solo de lectura. Se busca por Tor como indica el espacio y no se guarda, y no se abren imágenes ni enlaces. Consulta [Chats con otras apps de Nostr](#nostr-chats).",
  // 4.0.0-rc.8
  // 4.0.0-rc.7
  "**Licence**: Settings → General → Licence says under which licence Erevos is free software, AGPL-3.0-or-later, its three additional terms, that it comes with no warranty, and who made it. See [Licence](#licence).":
    "**Licencia**: Ajustes → General → Licencia dice bajo qué licencia es Erevos software libre, AGPL-3.0-or-later, sus tres condiciones adicionales, que no viene con ninguna garantía, y quién lo hizo. Consulta [Licencia](#licence).",
  "**Contact**: Settings → General → Contact adds the maker of Erevos as a contact, to write to in Erevos itself, end-to-end encrypted, with no phone number and no email. See [What Erevos is](#about).":
    "**Contacto**: Ajustes → General → Contacto añade a quien hace Erevos como contacto, para escribirle en el propio Erevos, con cifrado de extremo a extremo, sin número de teléfono ni email. Consulta [Qué es Erevos](#about).",
  "**A new sticker set, Angry Eyes**: 24 faces of big yellow eyes on a black disc, drawn by the maintainer, each with the moves he gave it.":
    "**Un nuevo conjunto de stickers, Angry Eyes**: 24 caras de grandes ojos amarillos sobre un disco negro, dibujadas por quien mantiene Erevos, cada una con los movimientos que él le dio.",
  "**The calculator opens again**: in 4.0.0-rc.6 it closed as soon as it was tapped.":
    "**La calculadora vuelve a abrirse**: en la 4.0.0-rc.6 se cerraba en cuanto la tocabas.",
  "**People you follow on Nostr are looked for on more relays**: **Show the people you follow** also asks relays that gather follow lists and more of the relays your key writes on, and waits longer for them; when it finds no one, it says why and how each relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Las personas que sigues en Nostr se buscan en más relays**: **Mostrar a las personas que sigues** pregunta también a relays que reúnen listas de seguidos y a más de los relays donde escribe tu clave, y los espera más tiempo; cuando no encuentra a nadie, dice por qué y cómo respondió cada relay. Consulta [Chats con otras apps de Nostr](#nostr-chats).",
  // 4.0.0-rc.6
  "**Panic password**: with the password lock on, **Set the panic password** under the Panic button sets a password of its own that, typed on the lock screen, wipes Erevos as **Wipe everything now** does, while the screen shows **Wrong password**. Nothing shows whether one is set. See [Panic button](#panic).":
    "**Contraseña de pánico**: con el bloqueo con contraseña activado, **Poner la contraseña de pánico** en «Botón de pánico» pone una contraseña propia que, escrita en la pantalla de bloqueo, borra Erevos como lo hace **Borrarlo todo ahora**, mientras la pantalla muestra **Contraseña incorrecta**. Nada muestra si hay una puesta. Consulta [Botón de pánico](#panic).",
  "**Calculator in place of Erevos**: on Android, under Launcher icons, a calculator that works can take the place of Erevos's icon; your code, then **=**, opens Erevos, which asks for its password as always. See [Appearance](#appearance).":
    "**Calculadora en lugar de Erevos**: en Android, en «Iconos del lanzador», una calculadora que funciona puede ocupar el lugar del icono de Erevos; tu código, luego **=**, abre Erevos, que pide su contraseña como siempre. Consulta [Apariencia](#appearance).",
  "**Chat with myself on your linked devices too**: notes, photos, files, voice messages and reminders written on one device go to the others, as do a reminder changed or seen and a note deleted. Those from before go once, both ways. See [Linked devices](#devices).":
    "**Chat conmigo también en tus dispositivos vinculados**: las notas, fotos, archivos, mensajes de voz y recordatorios que escribes en un dispositivo van a los otros, igual que un recordatorio cambiado o visto y una nota eliminada. Los de antes van una vez, en los dos sentidos. Consulta [Dispositivos vinculados](#devices).",
  "**Start when the phone turns on**: on Android, under In the background, Erevos can start by itself after the phone turns on, so the spaces set to say a message came while closed already say \"New message\", never which space or what. Off unless you choose it. See [Chat through a relay](#relay).":
    "**Iniciar al encender el teléfono**: en Android, en «En segundo plano», Erevos puede iniciarse solo tras encender el teléfono, de modo que los espacios configurados para avisar de que llegó un mensaje estando cerrados ya dicen «New message», nunca qué espacio ni qué. Desactivado salvo que lo elijas. Consulta [Chatear a través de un relay](#relay).",
  "**Moving the clock no longer ends the wait after wrong passwords**: it goes by the phone's own time since it started, which no one can set; after a restart it starts again from its beginning. See [Password lock](#lock).":
    "**Mover el reloj ya no termina la espera tras contraseñas incorrectas**: se cuenta con el tiempo propio del teléfono desde que arrancó, que nadie puede ajustar; tras un reinicio vuelve a empezar desde el principio. Consulta [Bloqueo con contraseña](#lock).",
  "**People you follow on Nostr, found where your other app keeps them**: with a key brought from another Nostr app, **Show the people you follow** also looks on the relays your key writes on, and says so when no relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Las personas que sigues en Nostr, encontradas donde las guarda tu otra app**: con una clave traída de otra app de Nostr, **Mostrar a las personas que sigues** busca también en los relays donde escribe tu clave, y lo dice cuando ningún relay respondió. Consulta [Chats con otras apps de Nostr](#nostr-chats).",
  "**Your Nostr name keeps the rest of your profile**: saving **Your name** changes only the name in your profile; a picture or words that another app of your key put there stay. Before, they could be wiped. See [Chats with other Nostr apps](#nostr-chats).":
    "**Tu nombre de Nostr conserva el resto de tu perfil**: guardar **Tu nombre** cambia solo el nombre en tu perfil; una foto o unas palabras que otra app de tu clave puso allí se quedan. Antes podían borrarse. Consulta [Chats con otras apps de Nostr](#nostr-chats).",
  "**Screens come down when no keyboard is open, in every case**: the home screen's list and buttons, or a chat, could still stay up as if a keyboard were open after it had gone. Now Erevos asks Android itself whether a keyboard is shown, and with none they come down within a second.":
    "**Las pantallas bajan cuando no hay teclado abierto, en todos los casos**: la lista y los botones de la pantalla de inicio, o un chat, aún podían quedarse arriba como si hubiera un teclado abierto, después de que se fuera. Ahora Erevos pregunta al propio Android si se muestra un teclado, y sin teclado bajan en menos de un segundo.",
  // 4.0.0-rc.5
  "**New chat opens hidden chats sooner**: hold **New chat** down for a moment, not a whole second, and the field for a PIN of hidden chats opens; on Android the phone buzzes once as it opens. See [Hidden chats](#hidden).":
    "**Chat nuevo abre antes los chats ocultos**: mantén pulsado **Chat nuevo** un momento, no un segundo entero, y se abre el campo para un PIN de chats ocultos; en Android el teléfono vibra una vez al abrirse. Consulta [Chats ocultos](#hidden).",
  "**People you follow on Nostr**: under New chat in Nostr chats, **Show the people you follow** lists the people your Nostr key follows, with their names; tap one to write to them. See [Chats with other Nostr apps](#nostr-chats).":
    "**Personas a las que sigues en Nostr**: en los Chats de Nostr, bajo Chat nuevo, **Mostrar a las personas que sigues** lista las personas que sigue tu clave de Nostr, con sus nombres; toca una para escribirle. Consulta [Chats con otras apps de Nostr](#nostr-chats).",
  "**Who makes Erevos, and its licence**: About Erevos now names its maker, and every file of Erevos's source code says whose it is and under which licence; the AGPL-3.0 licence has three added terms (keep the maker's name, mark a changed version, give it another name). See [What Erevos is](#about).":
    "**Quién hace Erevos, y su licencia**: Acerca de Erevos dice ahora quién lo hace, y cada archivo del código fuente dice de quién es y bajo qué licencia; la licencia AGPL-3.0 tiene tres condiciones añadidas (mantener el nombre del autor, marcar una versión cambiada como cambiada y darle otro nombre). Consulta [Qué es Erevos](#about).",
  // 4.0.0-rc.4
  "**Numbers on the home chips**: each chip above the chats (All messages, SMS, Erevos, Matrix, XMPP, Nostr) shows how many messages are not read in it, as a small number after its name; muted chats and groups are not counted. See [Getting started](#start).":
    "**Números en los chips de la pantalla de inicio**: cada chip sobre los chats (Todos, SMS, Erevos, Matrix, XMPP, Nostr) muestra cuántos mensajes sin leer hay en él, con un número pequeño tras su nombre; los chats y grupos silenciados no cuentan. Mira [Primeros pasos](#start).",
  "**Open a photo full screen in Matrix, XMPP and Nostr chats**: tap a photo shown in a Matrix, XMPP or Nostr chat to see it on the whole screen, with zoom, turning with the phone and Save, as in a chat with a contact. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Foto a pantalla completa en chats de Matrix, XMPP y Nostr**: toca una foto que se muestra en un chat de Matrix, XMPP o Nostr para verla en toda la pantalla, con zoom, giro con el teléfono y Guardar, como en el chat con un contacto. Mira [Matrix](#matrix), [XMPP](#xmpp) y [Chats con otras apps de Nostr](#nostr-chats).",
  "**Who got and who read your messages in groups**: in a group that is not public, your messages show ✓, then ✓✓ once they reached the phone of every member, and ✓✓✓ once every one read them. Hold one and choose **Who read it** to see who read it and when, whose phone it reached and when, and who has neither yet. A member whose Erevos is older says nothing. A linked computer shows the same marks. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Quién recibió y quién leyó tus mensajes en los grupos**: en un grupo que no es público, tus mensajes muestran ✓, luego ✓✓ cuando llegaron al teléfono de cada miembro, y ✓✓✓ cuando todos los leyeron. Mantén pulsado uno y elige **Quién lo leyó** para ver quién lo leyó y cuándo, a qué teléfono llegó y cuándo, y quién no ha hecho ninguna de las dos cosas. Un miembro con un Erevos anterior no dice nada. Un ordenador vinculado muestra las mismas marcas. Ver [Chatear a través de un relay](#relay) y [Chats de grupo](#groups).",
  "**Who read your messages in Matrix**: your messages in a Matrix chat show ✓ once the Matrix server took them and ✓✓✓ once every other member read them, as their Matrix apps tell their servers; **Who read it**, on a message held down, lists who read it and when, and who has not. Matrix has no mark for a message that reached a phone, so there is no ✓✓. See [Matrix](#matrix).":
    "**Quién leyó tus mensajes en Matrix**: tus mensajes en un chat de Matrix muestran ✓ cuando el servidor de Matrix los recogió y ✓✓✓ cuando todos los demás miembros los leyeron, según lo dicen sus apps de Matrix a sus servidores; **Quién lo leyó**, en un mensaje mantenido pulsado, lista quién lo leyó y cuándo, y quién no. Matrix no tiene marca para un mensaje que llegó a un teléfono, así que no hay ✓✓. Ver [Matrix](#matrix).",
  "**Quiet group messages for the marks**: the group message that says a message came or was read goes only to the senders concerned, and batched; after 300 such messages to some members only, the next goes to all, so no member falls behind in the phone's MLS keys (they accept a jump of 1000 at most). Groups let go of as their space closes send nothing more. See [Group chats](#groups).":
    "**Mensajes de grupo silenciosos para las marcas**: el mensaje de grupo que dice que un mensaje llegó o se leyó va solo a los remitentes afectados, y agrupado; tras 300 de estos mensajes a solo algunos miembros, el siguiente va a todos, para que ningún miembro se quede atrás en las claves MLS del teléfono (aceptan un salto de 1000 como máximo). Los grupos que se sueltan al cerrarse su espacio no envían nada más. Ver [Chats de grupo](#groups).",
  // 4.0.0-rc.3
  "**Bold, italic, code and hidden words**: in chats and groups, words typed between * become bold, between _ italic, between ~ struck through, between ` code, and between || hidden behind a grey bar until tapped. See [Chat through a relay](#relay).":
    "**Negrita, cursiva, código y palabras ocultas**: en chats y grupos, las palabras entre * se ponen en negrita, entre _ en cursiva, entre ~ tachadas, entre ` como código, y entre || ocultas tras una barra gris hasta que las toques. Mira [Chatear por un relay](#relay).",
  "**Hidden photo**: under + in a chat or a group, a photo that shows blurred until it is tapped. See [Chat through a relay](#relay).":
    "**Foto oculta**: bajo + en un chat o un grupo, una foto que se ve borrosa hasta que la tocas. Mira [Chatear por un relay](#relay).",
  "**Safety message**: under + in a chat, words to a contact that the relay sends by itself if you do not open Erevos for 6 hours to a week; each time you open it, they move on again. See [Chat through a relay](#relay).":
    "**Mensaje de seguridad**: bajo + en un chat, palabras para un contacto que el relay envía por sí solo si no abres Erevos durante entre 6 horas y una semana; cada vez que lo abres, se retrasan de nuevo. Mira [Chatear por un relay](#relay).",
  "**Name a member in a group with @**: type @ and pick a member; they are told of the message even if they muted the group. See [Group chats](#groups).":
    "**Nombra a un miembro en un grupo con @**: escribe @ y elige a un miembro; se entera del mensaje aunque haya silenciado el grupo. Mira [Chats de grupo](#groups).",
  "**Reply, change, react and delete in XMPP chats**: hold a message in an XMPP chat or group to answer it, change your words, delete it for everyone or react with an emoji, as Conversations, Dino, Gajim, Monal and Kaidan do; and **typing…** shows while the other person writes. See [XMPP](#xmpp).":
    "**Responder, cambiar, reaccionar y eliminar en los chats XMPP**: mantén pulsado un mensaje en un chat o grupo XMPP para responderlo, cambiar tus palabras, eliminarlo para todos o reaccionar con un emoji, como hacen Conversations, Dino, Gajim, Monal y Kaidan; y **escribiendo…** aparece mientras la otra persona escribe. Mira [XMPP](#xmpp).",
  "**See who is writing in a Matrix chat**: **typing…** shows under a Matrix chat while someone writes in it, as the Matrix server says. It shows of you too only if you turn on **Say when I am writing** on the Matrix or XMPP screen: off at first, as it goes through the server not encrypted. See [Matrix](#matrix).":
    "**Mira quién escribe en un chat de Matrix**: **escribiendo…** aparece bajo un chat de Matrix mientras alguien escribe en él, según dice el servidor de Matrix. De ti solo se ve si activas **Avisar cuando escribo** en la pantalla de Matrix o XMPP: desactivado al principio, ya que pasa por el servidor sin cifrar. Mira [Matrix](#matrix).",
  "**Block someone on XMPP**: Block, at the bottom of an XMPP chat, keeps that person's messages, calls and requests from every app of your XMPP account; Unblock lets them through again. See [XMPP](#xmpp).":
    "**Bloquea a alguien en XMPP**: Bloquear, al final de un chat XMPP, aparta los mensajes, llamadas y solicitudes de esa persona de todas las apps de tu cuenta XMPP; Desbloquear la deja pasar de nuevo. Mira [XMPP](#xmpp).",
  "**Voice messages in XMPP chats**: hold the microphone under an XMPP chat's message box to record, and let go to send; it goes encrypted as the chat is, as Conversations sends one. See [XMPP](#xmpp).":
    "**Mensajes de voz en chats XMPP**: mantén pulsado el micrófono bajo el cuadro de mensaje de un chat XMPP para grabar, y suelta para enviar; va cifrado como el chat, igual que lo envía Conversations. Mira [XMPP](#xmpp).",
  "**Matrix groups from Erevos**: New group, on the Matrix screen, makes an encrypted group with a name and the people you invite; Join a group joins one by its address; Invite, in a group, asks someone else in; typing @ in a group names a member, who is told of it. See [Matrix](#matrix).":
    "**Grupos de Matrix desde Erevos**: Grupo nuevo, en la pantalla de Matrix, crea un grupo cifrado con un nombre y las personas que invites; Unirse a un grupo entra en uno por su dirección; Invitar, en un grupo, invita a otra persona; escribir @ en un grupo nombra a un miembro, que recibe el aviso. Mira [Matrix](#matrix).",
  "**The panic button on a computer and on Sailfish OS**: Settings → Privacy and security → Panic button now wipes Erevos there too, with its automatic backups if you choose; on a computer it then starts again as new. See [Panic button](#panic).":
    "**El botón de pánico en un ordenador y en Sailfish OS**: Ajustes → Privacidad y seguridad → Botón de pánico ahora también borra Erevos allí, con sus copias automáticas si lo eliges; en un ordenador luego vuelve a abrirse como nuevo. Ver [Botón de pánico](#panic).",
  "**Every chat opens at its latest message**: chats with contacts, groups and SMS, and the Matrix, XMPP and Nostr chats, all open at the last message with the message bar under it, and have round arrows to the start, to where you left off (the first message that was new when you opened it) and to the end. See [Getting started](#start).":
    "**Cada chat se abre en su último mensaje**: los chats con contactos, los grupos y los SMS, y los chats de Matrix, XMPP y Nostr se abren todos en el último mensaje con la barra de mensajes debajo, y tienen flechas redondas al principio, a donde lo dejaste (el primer mensaje que era nuevo al abrirlo) y al final. Ver [Primeros pasos](#start).",
  "**The panic button says when it refused**: when your panic app asked to wipe Erevos while the switch was off, or signed with another key, the panic screen now says so, with the time. An app that moves to a new key the way Android allows stays trusted; otherwise you can trust it again as it is now. See [Panic button](#panic).":
    "**El botón de pánico dice cuándo se negó**: cuando tu app de pánico pidió borrar Erevos con el interruptor apagado, o firmada con otra clave, la pantalla del botón de pánico ahora lo dice, con la hora. Una app que pasa a una clave nueva de la forma que Android permite sigue siendo de confianza; si no, puedes volver a confiar en ella tal como está ahora. Ver [Botón de pánico](#panic).",
  "**The home screen's chips stay on one line**: with a Nostr, Matrix or XMPP chip as well, **Names** went to a line of its own and the chips moved. Now they stay on one line that slides to the side, and the chosen one is always in sight.":
    "**Los chips de la pantalla de inicio se quedan en una sola línea**: si había además un chip de Nostr, Matrix o XMPP, **Nombres** pasaba a una línea propia y los chips se movían. Ahora se quedan en una sola línea que se desliza hacia un lado, y el elegido siempre se ve.",
  "**Screens come down when the keyboard is gone**: back from another app that had its keyboard open, the home screen's buttons (or a chat's field) could stay up where the keyboard had been, until a keyboard opened again. Now they come down within a second.":
    "**Las pantallas bajan cuando se va el teclado**: al volver de otra app con el teclado abierto, los botones de la pantalla de inicio (o el campo de un chat) podían quedarse arriba, donde había estado el teclado, hasta que se abría otra vez un teclado. Ahora bajan en menos de un segundo.",
  // 4.0.0-rc.2
  "**See what you type in a password or a PIN**: every field for a password, a PIN or a token has an eye at its end: tap it to see what you type, and again to hide it. It is hidden again the next time. See [Password lock](#lock).":
    "**Ve lo que escribes en una contraseña o un PIN**: cada campo para una contraseña, un PIN o un token tiene un ojo al final: tócalo para ver lo que escribes, y otra vez para ocultarlo. La próxima vez vuelve a estar oculto. Consulta [Bloqueo con contraseña](#lock).",
  "**A chat read as it opens stays read**: messages read while their chat was still opening, as Erevos ended a look at the relay, showed as unread on the home screen once you went back. Now they are marked read as soon as they show.":
    "**Un chat leído mientras se abre queda leído**: los mensajes que leías mientras su chat aún se abría, porque Erevos terminaba de mirar en el relay, aparecían como no leídos en la pantalla de inicio al volver. Ahora quedan marcados como leídos en cuanto se ven.",
  "**Link for a website**: under New chat → Your contact link, a link to put on a web page, such as your contact page. It opens a page that offers Erevos to whoever has none yet, then adds you; what they send comes as a message request. See [Chat through a relay](#relay).":
    "**Enlace para una web**: en Chat nuevo → Tu enlace de contacto, un enlace para poner en una página web, como tu página de contacto. Abre una página que ofrece Erevos a quien aún no lo tiene y luego te añade; lo que envíe llega como solicitud de mensaje. Ver [Chatear a través de un relay](#relay).",
  "**An update's download that stalls is tried again**: when the connection brings nothing for a while, Erevos starts the download again by itself, three times in all, and then says so in its own words. See [Updates](#updates).":
    "**Una descarga de actualización que se atasca se vuelve a intentar**: cuando la conexión no trae nada durante un rato, Erevos vuelve a empezar la descarga solo, tres veces en total, y luego lo dice con sus propias palabras. Ver [Actualizaciones](#updates).",
  // 4.0.0-rc.1
  "**Pieces of photos through Nostr stay with their chats**: while a photo that comes through Nostr waits for the rest of its pieces, they are now kept encrypted with the space or the hidden chats they came for, no longer apart where they could be counted, so nothing outside a hidden chats' password says that a photo is on its way to them. Pieces kept before go to the first chats whose photo they are, or after four days. See [Through Nostr](#nostr).":
    "**Los trozos de fotos por Nostr se quedan con sus chats**: mientras una foto que llega por Nostr espera el resto de sus trozos, ahora se guardan cifrados con el espacio o los chats ocultos para los que llegaron, ya no aparte, donde se podían contar, así que nada fuera de la contraseña de unos chats ocultos dice que les llega una foto. Los trozos guardados antes van a los primeros chats de cuya foto son, o se van a los cuatro días. Ver [A través de Nostr](#nostr).",
  "**Encrypted SMS when nothing else works, if you choose**: on Android, when the relay, Nostr, the phones nearby and LoRa all fail, a text to an Erevos contact whose number is linked can go by SMS, end-to-end encrypted, hidden from their SMS app. Off until you turn it on, for all such contacts under Settings → Phone and SMS → SMS, or for one in a chat's Details. It costs SMS (3 for a short text, up to 10 for a longer one), and the phone company sees who wrote to whom, and when. Both phones need Erevos as the SMS app. See [SMS](#sms).":
    "**SMS cifrados cuando nada más funciona, si lo eliges**: en Android, cuando fallan el relay, Nostr, los teléfonos cercanos y LoRa, un texto a un contacto de Erevos con número vinculado puede ir por SMS, cifrado de extremo a extremo y oculto para su app de SMS. Desactivado hasta que lo actives, para todos esos contactos en Ajustes → Teléfono y SMS → SMS, o para uno en los Detalles de un chat. Cuesta SMS (3 para un texto corto, hasta 10 para uno más largo), y la compañía telefónica ve quién escribió a quién, y cuándo. Ambos teléfonos necesitan Erevos como app de SMS. Mira [SMS](#sms).",
  "**Answer a hidden call with Answer**: on the \"Incoming call\" screen with no name that a call to your hidden chats brings, **Answer** now asks for the PIN, as the small sign does, and the right PIN answers the call; before, it could not connect, and only the small sign could. See [Hidden chats](#hidden).":
    "**Responder una llamada oculta con Responder**: en la pantalla «Llamada entrante» sin nombre que trae una llamada a tus chats ocultos, **Responder** ahora pide el PIN, como el pequeño símbolo, y el PIN correcto responde la llamada; antes no podía conectar, y solo el pequeño símbolo podía. Consulta [Chats ocultos](#hidden).",
  "**Spam SMS come quietly**: on Android, an SMS that the spam filter's own words catch, a link with words that try to fool from a number that is no contact and that you never answered, still goes to Spam but no longer shows a notice or makes a sound. Spam by your own words and rules still shows one, as they stay encrypted in the space; with the Spam filter off, every SMS does. See [SMS](#sms).":
    "**Los SMS de spam llegan en silencio**: en Android, un SMS que atrapan las propias palabras del filtro de spam, un enlace con palabras que intentan engañar de un número que no es un contacto y al que nunca respondiste, sigue yendo a Spam pero ya no muestra un aviso ni suena. El spam por tus propias palabras y reglas sigue mostrando uno, ya que quedan cifradas en el espacio; con el Filtro de spam apagado, todo SMS lo muestra. Ver [SMS](#sms).",
  '**What\'s new in two parts**: each version says first what changes for you, then what changed under the hood: fixes, speed, battery and security inside. See [Updates](#updates).':
    '**Novedades en dos partes**: cada versión dice primero qué cambia para ti y luego qué cambió bajo el capó: arreglos, velocidad, batería y seguridad por dentro. Ver [Actualizaciones](#updates).',
  '**A contact\'s SMS no longer stay counted as new**: opening their chat reads all of them, the earlier ones too, not only those that show.':
    '**Los SMS de un contacto ya no siguen contando como nuevos**: al abrir su chat se leen todos, también los anteriores, no solo los que se ven.',
  '**A message no longer waits when Tor cannot reach the relay**: with Tor for messages, it goes straight at once, as the Tor settings say. See [Through Tor](#tor).':
    '**Un mensaje ya no espera cuando Tor no llega al relay**: con Tor para los mensajes, sale directo enseguida, como dicen los ajustes de Tor. Ver [Por Tor](#tor).',
  '**Background notices no longer stop after a network change**: when the connection of a wait at the relay died on the way (Wi-Fi to mobile data, the relay restarting), Erevos took the relay for one from before, which cannot wait, for the whole run: contacts\' messages then came up to ten minutes late, and hidden chats, closed spaces and hidden rings said nothing until Erevos was restarted. See [Chat through a relay](#relay).':
    '**Los avisos en segundo plano ya no se detienen tras un cambio de red**: cuando la conexión de una espera en el relay moría por el camino (de Wi-Fi a datos móviles, reinicio del relay), Erevos tomaba el relay por uno antiguo, que no sabe esperar, durante toda la ejecución: los mensajes de los contactos llegaban hasta diez minutos tarde, y los chats ocultos, los espacios cerrados y los timbres ocultos no decían nada hasta reiniciar Erevos. Ver [Chatear a través de un relay](#relay).',
  '**A call hung up at once no longer rings**: when the hang-up came in the same look as the call, the phone rang 45 seconds for a call nobody was on; the same for a group call its starter left at once. See [Chat through a relay](#relay).':
    '**Una llamada colgada al instante ya no suena**: cuando el colgado llegaba en la misma mirada que la llamada, el teléfono sonaba 45 segundos por una llamada en la que no había nadie; lo mismo para una llamada de grupo que quien la empezó dejó al instante. Ver [Chatear a través de un relay](#relay).',
  '**A hidden call rings once**: a place with Receive while closed and a ring queue rang twice for one call, and a call taken while hidden chats were open rang again as they closed. See [Hidden chats](#hidden).':
    '**Una llamada oculta suena una vez**: un lugar con Recibir estando cerrados y una cola de timbre sonaba dos veces por una llamada, y una llamada atendida con los chats ocultos abiertos volvía a sonar al cerrarse. Ver [Chats ocultos](#hidden).',
  '**A member\'s contact link no longer says New message**: the answer to an ask from a group only adds the contact, with no notice. See [Group chats](#groups).':
    '**El enlace de contacto de un miembro ya no dice Mensaje nuevo**: la respuesta a una petición desde un grupo solo añade el contacto, sin aviso. Ver [Chats de grupo](#groups).',
  '**The birthday notice and the phone\'s incoming call no longer replace each other**: they had the same notice number. See [Contacts](#contacts).':
    '**El aviso de cumpleaños y la llamada entrante del teléfono ya no se reemplazan**: tenían el mismo número de aviso. Ver [Contactos](#contacts).',
  '**A closed space tells of its contacts\' messages too**: since each contact writes to a queue of their own, a space that says a message came while another is open told only of group messages and first messages from new contacts. It now asks about its contacts\' queues too, up to 64. See [Chat through a relay](#relay).':
    '**Un espacio cerrado avisa también de los mensajes de sus contactos**: como cada contacto escribe en una cola propia, un espacio que avisa de que llegó un mensaje mientras otro está abierto solo avisaba de mensajes de grupos y de primeros mensajes de contactos nuevos. Ahora pregunta también por las colas de sus contactos, hasta 64. Ver [Chatear a través de un relay](#relay).',
  '**The user guide is in every language of the app**: it shows in the one you chose, and names the buttons as the app shows them. See [Language](#start).':
    '**La guía de uso está en todos los idiomas de la app**: se muestra en el que elegiste y nombra los botones como los muestra la app. Ver [Idioma](#start).',
  '**Location finds where you are, indoors too**: the phone looks by satellite and by its network at once, a sheet says it is looking, and when nothing is found it says why, with Try again. See [Chat through a relay](#relay).':
    '**Ubicación encuentra dónde estás, también en interiores**: el teléfono busca por satélite y por su red a la vez, una hoja dice que está buscando, y si no se encuentra nada dice por qué, con Volver a intentarlo. Ver [Chatear a través de un relay](#relay).',
  '**The web app\'s icon counts what is not read**: on an iPhone, with notifications on for the space, Erevos\'s icon on the home screen shows how many messages are not read, never a hidden chat\'s, unless turned off under Settings → Notifications → Number on the icon. See [On an iPhone](#iphone).':
    '**El icono de la app web cuenta lo no leído**: en un iPhone, con las notificaciones activadas para el espacio, el icono de Erevos en la pantalla de inicio muestra cuántos mensajes no se han leído, nunca los de un chat oculto, salvo que lo desactives en Ajustes → Notificaciones → Número en el icono. Ver [En un iPhone](#iphone).',
  "**Notifications for each chat**: on Android, mute a chat or a group for 8 hours, a week or always, and give its messages and its calls a sound of their own, or none. See [Chat through a relay](#relay).":
    "**Notificaciones para cada chat**: en Android, silencia un chat o un grupo durante 8 horas, una semana o siempre, y da a sus mensajes y llamadas un sonido propio, o ninguno. Mira [Chatear a través de un relay](#relay).",
  "**A chat locked with its own PIN stays locked**: when its contact's Erevos started a new conversation, as it does about once a month, the chat lost its PIN, and a public group joined again lost its own. See [Hidden chats](#hidden).":
    "**Un chat bloqueado con su propio PIN sigue bloqueado**: cuando el Erevos del contacto empezaba una conversación nueva, como hace más o menos una vez al mes, el chat perdía su PIN, y un grupo público al que volviste a unirte perdía el suyo. Ver [Chats ocultos](#hidden).",
  "**Erevos's icon keeps the number of messages not read, on Android**: leaving Erevos with messages not read, a notice without sound keeps how many until you read them, and the launcher shows it on the icon, as a number or a dot. Settings → Notifications → Number on the icon turns it off. See [Chat through a relay](#relay).":
    "**El icono de Erevos guarda el número de mensajes sin leer, en Android**: al salir de Erevos con mensajes sin leer, un aviso sin sonido guarda cuántos son hasta que los leas, y el launcher lo muestra en el icono, como número o punto. Ajustes → Notificaciones → Número en el icono lo desactiva. Ver [Chatear a través de un relay](#relay).",
  "**The web app's notifications, more dependable**: no New message over Erevos while it is open, and a push held back while the phone was offline no longer counts messages you already read (both with your relay updated), every notice sounds in Chrome, Firefox and Edge, they come back by themselves when the browser changes its push address, and Notifications while closed says when the browser blocks them or your relay was not told yet that they are off. See [On an iPhone](#iphone).":
    "**Las notificaciones de la app web, más fiables**: ningún Mensaje nuevo encima de Erevos mientras está abierto, y un push retenido mientras el teléfono estaba sin conexión ya no cuenta los mensajes que ya leíste (las dos cosas con tu relay actualizado), cada aviso suena en Chrome, Firefox y Edge, vuelven solas cuando el navegador cambia su dirección push, y Notificaciones con la app cerrada dice cuándo el navegador las bloquea o cuándo aún no se ha avisado a tu relay de que están desactivadas. Ver [En un iPhone](#iphone).",
  "**Calls ring in the web app, on the computer and on Sailfish OS**: a call that comes while Erevos is open now rings, where only its screen showed, and vibrates where the phone can. On an iPhone it rings once you have touched Erevos, and not on silent. See [On an iPhone](#iphone).":
    "**Las llamadas suenan en la app web, en el ordenador y en Sailfish OS**: una llamada que llega mientras Erevos está abierto ahora suena, donde solo se mostraba su pantalla, y vibra donde el teléfono puede. En un iPhone suena una vez que has tocado Erevos, y no en silencio. Ver [En un iPhone](#iphone).",
  '**Erevos on a computer keeps running with its window closed**: in the system tray (on a Mac, in the Dock) it goes on receiving, a call rings and brings the window back, and a notification says how many messages are not read, never who or what. Turn it off under Settings → Notifications → In the background. See [On a computer](#desktop).':
    '**Erevos en el ordenador sigue funcionando con su ventana cerrada**: en la bandeja del sistema (en un Mac, en el Dock) sigue recibiendo, una llamada suena y trae de vuelta la ventana, y una notificación dice cuántos mensajes no se han leído, nunca de quién ni qué. Se desactiva en Ajustes → Notificaciones → En segundo plano. Ver [En un ordenador](#desktop).',
  "**Erevos on Sailfish OS tells of messages and calls while it is closed**: while it is out of sight or closed, a small helper waits at the relay for the open space, a notification says how many messages came, never who or what, and a call rings with the phone's ringtone. See [On Sailfish OS](#sailfish).":
    "**Erevos en Sailfish OS avisa de mensajes y llamadas mientras está cerrado**: mientras no se ve o está cerrado, un pequeño ayudante espera en el relay por el espacio abierto, un aviso dice cuántos mensajes llegaron, nunca de quién ni qué, y una llamada suena con el tono del teléfono. Ver [En Sailfish OS](#sailfish).",
  "**The relay's pushes to the web app, sturdier**: a push the push service could not take just then is sent again, a call goes before the messages waiting their turn, and whoever runs the relay can allow another push service. Your relay needs an update for it.":
    "**Los push del relay a la app web, más robustos**: un push que el servicio push no pudo aceptar en ese momento se envía de nuevo, una llamada pasa por delante de los mensajes que esperan su turno, y quien gestiona el relay puede permitir otro servicio push. Tu relay necesita una actualización para ello.",
  "**Permissions checks every notice Erevos uses**: on Android, the message notice without sound or with a chat's own sound, and the reminders', turned off, now show there, with a button to each. See [Chat through a relay](#relay).":
    '**Permisos comprueba cada aviso que usa Erevos**: en Android, el aviso de mensajes sin sonido o con el sonido propio de un chat, y el de los recordatorios, si están desactivados, ahora aparecen ahí, con un botón para cada uno. Ver [Chatear a través de un relay](#relay).',
  '**Hidden chats say what their switches need**: Say when a message comes and Ring calls when closed say so when Settings → Notifications → In the background lets them do nothing. See [Hidden chats](#hidden).':
    '**Los chats ocultos dicen qué necesitan sus interruptores**: Avisar cuando llega un mensaje y Sonar las llamadas cuando están cerrados lo dicen cuando Ajustes → Notificaciones → En segundo plano no les deja hacer nada. Ver [Chats ocultos](#hidden).',
  "**Truer words about notices**: Settings and the guide give the notices' own words and say what each one needs. See [Chat through a relay](#relay).":
    '**Palabras más fieles sobre los avisos**: Ajustes y la guía dan las propias palabras de los avisos y dicen qué necesita cada uno. Ver [Chatear a través de un relay](#relay).',
  "**Calls ring as they should**: with Do Not Disturb only when their notice may break through, with a phone's clock off too once the relay is updated, and to the end on Android 7 and 8; a second call is told busy, and a ring stops only for its own call. See [Chat through a relay](#relay).":
    '**Las llamadas suenan como deben**: con «No molestar», solo cuando su aviso puede saltárselo, también con el reloj de un teléfono desajustado una vez actualizado el relay, y hasta el final en Android 7 y 8; a una segunda llamada se le dice que la línea está ocupada, y un timbre solo se detiene por su propia llamada. Ver [Chatear a través de un relay](#relay).',
  '**Hidden calls**: one turned down no longer leaves Erevos over the lock screen, one that comes while the password screen shows comes over it, and none rings twice. See [Hidden chats](#hidden).':
    '**Llamadas ocultas**: una rechazada ya no deja Erevos sobre la pantalla de bloqueo, una que llega mientras se muestra la pantalla de la contraseña aparece sobre ella, y ninguna suena dos veces. Ver [Chats ocultos](#hidden).',
  '**Notices come again at once after a change of network**, and receiving starts again as Erevos shows when Android refused it. See [Chat through a relay](#relay).':
    '**Los avisos vuelven al instante tras un cambio de red**, y la recepción se reanuda al mostrarse Erevos cuando Android la había rechazado. Ver [Chatear a través de un relay](#relay).',
  "**Hidden chats' notices tell each message once**: what came since a place last looked is told as it closes, a call that rang is not told again as a message, and a place whose queue the relay lost keeps its switch on. See [Hidden chats](#hidden).":
    '**Los avisos de los chats ocultos cuentan cada mensaje una vez**: lo que llegó desde la última vez que un lugar miró se avisa al cerrarse, una llamada que sonó no se avisa otra vez como mensaje, y un lugar cuya cola perdió el relay mantiene su interruptor activado. Ver [Chats ocultos](#hidden).',
  '**Hidden chats close while Erevos is away**, after 30 seconds, so a call to them meanwhile rings with their PIN to answer. See [Hidden chats](#hidden).':
    '**Los chats ocultos se cierran mientras Erevos no está a la vista**, tras 30 segundos, así que una llamada para ellos mientras tanto suena con su PIN para responder. Ver [Chats ocultos](#hidden).',
  '**A voice message counts once**, on its last part, also when it goes again whole.':
    '**Un mensaje de voz cuenta una vez**, en su última parte, también cuando se vuelve a enviar entero.',
  '**The number on the icon counts only what is still there**: a message deleted for everyone, or read on a linked computer, no longer counts. See [Chat through a relay](#relay).':
    '**El número en el icono solo cuenta lo que sigue ahí**: un mensaje eliminado para todos, o leído en un ordenador vinculado, ya no cuenta. Ver [Chatear a través de un relay](#relay).',
  '**Messages sent for later** tell of themselves only while their space is open, without sound if sent so.':
    '**Los mensajes enviados para más tarde** solo avisan de sí mismos mientras su espacio está abierto, sin sonido si se enviaron así.',
  '**SMS**: one to the chat on screen only sounds there, they are marked read only while their screen shows, and Android names their notices SMS. See [SMS](#sms).':
    '**SMS**: uno que llega al chat que está en pantalla solo suena ahí, se marcan como leídos solo mientras su pantalla está a la vista, y Android llama SMS a sus avisos. Ver [SMS](#sms).',
  "**Reminders**: one seen in Chat with myself goes from the notice, a hidden place's go with a new PIN, and birthdays come at 9:00. See [Getting started](#start).":
    '**Recordatorios**: uno visto en Chat conmigo se va del aviso, los de un lugar oculto se van con un PIN nuevo, y los cumpleaños llegan a las 9:00. Ver [Primeros pasos](#start).',
  '**Nostr reads as soon as Tor is ready.** See [Through Nostr](#nostr).':
    '**Nostr lee en cuanto Tor está listo.** Ver [A través de Nostr](#nostr).',
  "**Erevos's notices show its mark** in the status bar.":
    '**Los avisos de Erevos muestran su marca** en la barra de estado.',
  '**Notices are asked for with receiving off too**, when Say a message came is on.':
    '**Los avisos se piden también con la recepción desactivada**, cuando Avisar de mensajes nuevos está activado.',
  "**Photos open on the whole screen**: tap one to see it edge to edge, zoom in with two fingers or a double tap, and tap again to hide or show what is around it; big photos open as small ones do. Erevos also turns with the phone while the phone's Auto-rotate is on, and a photo shown on its own even when it is off. See [Chat through a relay](#relay).":
    '**Las fotos se abren en toda la pantalla**: toca una para verla de borde a borde, amplíala con dos dedos o con un doble toque, y vuelve a tocar para ocultar o mostrar lo que hay alrededor; las fotos grandes se abren como las pequeñas. Erevos también gira con el teléfono mientras Girar automáticamente está activado en él, y una foto vista sola incluso cuando está desactivado. Ver [Chatear a través de un relay](#relay).',
  "**Matrix accounts in Erevos**: sign a space in to Matrix and chat with people who use Element or another Matrix app, end-to-end encrypted, under Settings → Relay and networks → Matrix. These chats are not anonymous, and say so: the Matrix server sees who talks with whom. Text, photos and files. See [Matrix](#matrix).":
    "**Cuentas de Matrix en Erevos**: inicia sesión en Matrix desde un espacio y chatea con personas que usan Element u otra app de Matrix, con cifrado de extremo a extremo, en Ajustes → Relay y redes → Matrix. Estos chats no son anónimos, y lo dicen: el servidor de Matrix ve quién habla con quién. Texto, fotos y archivos. Ver [Matrix](#matrix).",
  "**Every network's chats on the home screen**: once you sign in to Matrix, its chats are in the list with the Erevos chats and the SMS, newest first, each marked Matrix, and the Matrix chip shows them alone, as SMS and Erevos do. See [Matrix](#matrix).":
    "**Los chats de todas las redes en la pantalla de inicio**: una vez que inicias sesión en Matrix, sus chats están en la lista con los chats de Erevos y los SMS, los más recientes primero, cada uno marcado Matrix, y el chip Matrix muestra solo ellos, como SMS y Erevos. Ver [Matrix](#matrix).",
  '**Test versions before a release**: Erevos reads a version such as 4.0.0-rc.1, a test version that comes before 4.0.0, when it looks for updates, tells of a new version and shows what is new. See [Updates](#updates).':
    '**Versiones de prueba antes de una versión**: Erevos lee una versión como 4.0.0-rc.1, una versión de prueba que va antes de la 4.0.0, al buscar actualizaciones, al avisar de una versión nueva y al mostrar las novedades. Ver [Actualizaciones](#updates).',
  "**Check Matrix devices by emoji**: in a chat with one person on Matrix, Check by emoji shows you both seven pictures; if they match, nobody sits in between, and Element sees the check too. Check this device with another of yours makes your own Element trust Erevos. See [Matrix](#matrix).":
    "**Comprobar dispositivos de Matrix con emojis**: en un chat con una persona en Matrix, Comprobar con emojis os muestra a los dos siete imágenes; si coinciden, nadie está en medio, y Element también ve la comprobación. Comprobar este dispositivo con otro tuyo hace que tu propio Element confíe en Erevos. Ver [Matrix](#matrix).",
  "**Automatic backups to your own server too**: on Android, each automatic backup can also go to a folder on a server you choose, such as your Nextcloud, over WebDAV. Off until you add one. The server gets random bytes under a random name and cannot open them; it still sees your account, your address and when. See [Backups](#backup).":
    "**Copias automáticas también a tu propio servidor**: en Android, cada copia automática puede ir también a una carpeta en un servidor que elijas, como tu Nextcloud, por WebDAV. Desactivado hasta que añadas uno. El servidor recibe bytes aleatorios con un nombre aleatorio y no puede abrirlos; aun así ve tu cuenta, tu dirección y cuándo. Ver [Copias de seguridad](#backup).",
  "**Matrix Security Key and key backup**: enter the Security Key Element made, under Settings → Relay and networks → Matrix, and earlier messages open, new keys are backed up, and your other devices trust Erevos. An account with none can set one up there. See [Matrix](#matrix).":
    "**Clave de seguridad y copia de claves de Matrix**: escribe la clave de seguridad que creó Element, en Ajustes → Relay y redes → Matrix, y se abren los mensajes anteriores, se guardan copias de las claves nuevas, y tus otros dispositivos confían en Erevos. Una cuenta sin ella puede crear una allí. Ver [Matrix](#matrix).",
  "**Matrix through Tor**: on Android, a space's Matrix account follows its choice under Settings → Relay and networks → Tor, so the Matrix server no longer sees where you are; the Matrix screen says when it goes through Tor. See [Matrix](#matrix).":
    "**Matrix por Tor**: en Android, la cuenta de Matrix de un espacio sigue su elección en Ajustes → Relay y redes → Tor, así que el servidor de Matrix ya no ve dónde estás; la pantalla de Matrix dice cuándo va por Tor. Ver [Matrix](#matrix).",
  "**XMPP accounts in Erevos**: sign a space in to XMPP, under Settings → Relay and networks → XMPP, and chat with people who use Conversations, Monal, Gajim, Dino or another XMPP app, encrypted with OMEMO. These chats are not anonymous, and say so: the XMPP server sees who talks with whom. Text with delivery and read marks, photos and files, in the home list under an XMPP chip of its own, and through Tor on Android as you chose. See [XMPP](#xmpp).":
    "**Cuentas de XMPP en Erevos**: inicia sesión en XMPP desde un espacio, en Ajustes → Relay y redes → XMPP, y chatea con personas que usan Conversations, Monal, Gajim, Dino u otra app de XMPP, cifrado con OMEMO. Estos chats no son anónimos, y lo dicen: el servidor de XMPP ve quién habla con quién. Texto con marcas de entrega y de lectura, fotos y archivos, en la lista de inicio bajo un chip XMPP propio, y por Tor en Android como elijas. Ver [XMPP](#xmpp).",
  "**Voice and video calls with people on XMPP**: the two tiles at the top of an XMPP chat call the person, and their calls ring on the same screen as Erevos's own, with apps that call as Conversations does. The call goes through your call relay or the XMPP server's, so they do not learn your address; the key that proves it passes through the XMPP servers, which could put themselves in between. See [XMPP](#xmpp).":
    "**Llamadas de voz y video con personas en XMPP**: los dos recuadros de arriba de un chat de XMPP llaman a la persona, y sus llamadas suenan en la misma pantalla que las de Erevos, con apps que llaman como Conversations. La llamada pasa por tu relay de llamadas o el del servidor de XMPP, así que no conoce tu dirección; la clave que la prueba pasa por los servidores de XMPP, que podrían ponerse en medio. Mira [XMPP](#xmpp).",
  "**Voice and video calls with people on Matrix**: on Android, the two tiles at the top of a Matrix chat call with Element Call, the call app of Element and Element X, which opens inside Erevos in a window of its own, and their calls ring here as Erevos's own do. Sound and picture are end-to-end encrypted and go through the media server your Matrix server names, never through Tor. See [Matrix](#matrix).":
    "**Llamadas de voz y video con gente en Matrix**: en Android, los dos recuadros de arriba de un chat de Matrix llaman con Element Call, la app de llamadas de Element y Element X, que se abre dentro de Erevos en una ventana propia, y sus llamadas suenan aquí como las de Erevos. El sonido y la imagen van cifrados de extremo a extremo y pasan por el servidor de medios que indica tu servidor de Matrix, nunca por Tor. Ver [Matrix](#matrix).",
  "**Voice and video calls with people on Matrix, in the web app and on a computer**: the two tiles at the top of a Matrix chat call with Element Call there too, as on Android, over the app; its back arrow makes it small in a corner, so you can keep using Erevos during the call. Element Call runs apart from Erevos and can read nothing of it. See [Matrix](#matrix).":
    "**Llamadas de voz y video con gente en Matrix, en la app web y en el ordenador**: los dos recuadros de arriba de un chat de Matrix llaman también allí con Element Call, como en Android, sobre la app; la flecha de atrás de su ventana la reduce a una esquina, para que puedas seguir usando Erevos durante la llamada. Element Call funciona aparte de Erevos y no puede leer nada de él. Ver [Matrix](#matrix).",
  "**Chats with people on other Nostr apps**: give a space a Nostr key of its own, under Settings → Relay and networks → Nostr chats, and chat with people who use Damus, Amethyst, Primal, 0xchat or another Nostr app, one to one or in groups, encrypted as NIP-17 asks: the relays see whom a message is for, not who wrote it. These chats are not anonymous, and say so: your key is the same to everyone you write to. Text, photos, files and reactions, in the home list under a Nostr chip of its own, and through Tor on Android as you chose. See [Chats with other Nostr apps](#nostr-chats).":
    "**Chats con personas en otras apps de Nostr**: da a un espacio una clave de Nostr propia, en Ajustes → Relay y redes → Chats de Nostr, y chatea con personas que usan Damus, Amethyst, Primal, 0xchat u otra app de Nostr, de tú a tú o en grupos, cifrado como pide NIP-17: los relays ven para quién es un mensaje, no quién lo escribió. Estos chats no son anónimos y lo dicen: tu clave es la misma para todos a quienes escribes. Texto, fotos, archivos y reacciones, en la lista de inicio bajo un botón Nostr propio, y por Tor en Android como elegiste. Ver [Chats con otras apps de Nostr](#nostr-chats).",
  "**Notices for Matrix, XMPP and Nostr messages**: a message in a chat on Matrix, XMPP or Nostr shows a notice and counts in the number on Erevos's icon, as in Erevos's own chats. On Android, Notifications at the bottom of such a chat mutes it or gives it a sound of its own, and an XMPP or Matrix call rings with its chat's ringtone. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Avisos de los mensajes de Matrix, XMPP y Nostr**: un mensaje en un chat de Matrix, XMPP o Nostr muestra un aviso y cuenta en el número del icono de Erevos, como en los chats propios de Erevos. En Android, Notificaciones, al final de un chat así, lo silencia o le da un sonido propio, y una llamada de XMPP o Matrix suena con el tono de su chat. Ver [Matrix](#matrix), [XMPP](#xmpp) y [Chats con otras apps de Nostr](#nostr-chats).",
  "**A closed space tells of Matrix messages**: on Android, Say a message came under While this space is closed, on the Matrix screen, has a closed space say \"New message\" when something comes on Matrix while another space is open, never what, from whom or in which chat. Off until you choose it. The Matrix server then tells the space's relay of each message, with no words in it: it learns the relay's address, and the relay when messages come. See [Matrix](#matrix).":
    "**Un espacio cerrado avisa de los mensajes de Matrix**: en Android, «Avisar de mensajes nuevos» en «Mientras este espacio está cerrado», en la pantalla de Matrix, hace que un espacio cerrado diga «Mensaje nuevo» cuando llega algo en Matrix mientras otro espacio está abierto, nunca qué, de quién ni en qué chat. Desactivado hasta que lo elijas. El servidor de Matrix avisa entonces al relay del espacio de cada mensaje, sin ninguna palabra suya: sabe la dirección del relay, y el relay cuándo llegan mensajes. Ver [Matrix](#matrix).",
  "**Made with others' open source**: About Erevos, and the guide, now name the open-source projects Erevos is built on, with their makers and their licences. See [What Erevos is](#about).":
    "**Hecho con el código abierto de otros**: En Acerca de Erevos y en la guía figuran ahora los proyectos de código abierto sobre los que está construido Erevos, con sus autores y sus licencias. Ver [Qué es Erevos](#about).",
  "**Groups on XMPP**: under Settings → Relay and networks → XMPP, make a private group with your contacts, encrypted with OMEMO for every member as Conversations' private groups are, or join a group by its address, and answer invitations to groups. A group that is not private, a channel, is not encrypted, and says so. Your groups follow your account's other XMPP apps, and a channel tells only of messages that name you. See [XMPP](#xmpp).":
    "**Grupos en XMPP**: en Ajustes → Relay y redes → XMPP, crea un grupo privado con tus contactos, cifrado con OMEMO para cada miembro como los grupos privados de Conversations, o entra en un grupo con su dirección, y responde a las invitaciones a grupos. Un grupo que no es privado, un canal, no está cifrado, y lo dice. Tus grupos siguen a las otras apps de XMPP de tu cuenta, y un canal avisa solo de los mensajes que te nombran. Ver [XMPP](#xmpp).",
  "**More in Matrix chats**: hold a message to react to it, reply to it, copy it and, if it is yours, edit it or delete it for everyone. Load earlier messages brings in older ones, and the microphone under the message box sends voice messages that Element plays too. Reactions are not encrypted, as Element sends them. See [Matrix](#matrix).":
    "**Más en los chats de Matrix**: mantén pulsado un mensaje para reaccionar, responderle, copiarlo y, si es tuyo, editarlo o eliminarlo para todos. «Cargar mensajes anteriores» trae los más antiguos, y el micrófono bajo el campo del mensaje envía mensajes de voz que Element también reproduce. Las reacciones no van cifradas, tal como las envía Element. Ver [Matrix](#matrix).",
  "**Video added to an XMPP call**: in a voice call with someone on XMPP, either of you can turn on video with Add video; the other is asked first and can say Not now. It works with apps that add video to a call as Conversations does. See [XMPP](#xmpp).":
    "**Video añadido a una llamada de XMPP**: en una llamada de voz con alguien en XMPP, cualquiera de los dos puede activar el video con «Añadir vídeo»; a la otra persona se le pregunta primero y puede decir «Ahora no». Funciona con apps que añaden video a una llamada como Conversations. Ver [XMPP](#xmpp).",
  "**Voice messages and replies in Nostr chats**: hold the microphone under the message box to send a voice message, which plays with Play; hold a message to reply to it, and the answer shows the message it is to, here and in other Nostr apps. See [Chats with other Nostr apps](#nostr-chats).":
    "**Mensajes de voz y respuestas en los chats de Nostr**: mantén pulsado el micrófono bajo el campo del mensaje para enviar un mensaje de voz, que se reproduce con «Reproducir»; mantén pulsado un mensaje para responderle, y la respuesta muestra el mensaje al que responde, aquí y en otras apps de Nostr. Ver [Chats con otras apps de Nostr](#nostr-chats).",
  "**OMEMO 2 in XMPP chats**: a message to someone whose app speaks OMEMO 2, as Kaidan does, now goes with OMEMO 2 to that app and with OMEMO 0.3 to their others, as before. The XMPP screen shows this device's key both ways, to compare with what each app shows. See [XMPP](#xmpp).":
    "**OMEMO 2 en los chats de XMPP**: un mensaje a alguien cuya app habla OMEMO 2, como Kaidan, ahora va con OMEMO 2 a esa app y con OMEMO 0.3 a sus otras apps, como antes. La pantalla de XMPP muestra la clave de este dispositivo de las dos maneras, para compararla con lo que muestra cada app. Ver [XMPP](#xmpp).",
  "**Hidden chats can have their own Matrix, XMPP and Nostr accounts**: under the list of a place of hidden chats, Matrix, XMPP and Nostr open an account of that place alone, apart from the space's, kept encrypted with the hidden chats' key. Its chats show among the hidden chats only. It connects while they are open, and while they are closed too if Receive while closed is on, as the hidden chats do: then a message says only \"New message\", and a call rings with no name and is answered with the PIN. See [Hidden chats](#hidden).":
    "**Los chats ocultos pueden tener sus propias cuentas de Matrix, XMPP y Nostr**: bajo la lista de un lugar de chats ocultos, Matrix, XMPP y Nostr abren una cuenta solo de ese lugar, aparte de la del espacio y guardada cifrada con la clave de los chats ocultos. Sus chats se ven solo entre los chats ocultos. Se conecta mientras están abiertos, y también mientras están cerrados si Recibir estando cerrados está activado, como los propios chats ocultos: entonces un mensaje dice solo «Mensaje nuevo», y una llamada suena sin nombre y se contesta con el PIN. Ver [Chats ocultos](#hidden).",
  "**Matrix, XMPP and Nostr in backups**: a backup now holds the Matrix, XMPP and Nostr accounts of every space and of its hidden chats. After a restore, a Nostr key comes back with its chats as they were; an XMPP account goes on as a new device of the account, with its contacts and chats; a Matrix account is let go of on this phone, and the space signs in again as a new device; its Security Key opens the messages from before. See [Backups](#backup).":
    "**Matrix, XMPP y Nostr en las copias de seguridad**: una copia ahora contiene las cuentas de Matrix, XMPP y Nostr de cada espacio y de sus chats ocultos. Tras restaurar, una clave de Nostr vuelve con sus chats como estaban; una cuenta de XMPP sigue como un dispositivo nuevo de la cuenta, con sus contactos y chats; una cuenta de Matrix se suelta en este teléfono, y el espacio inicia sesión de nuevo como un dispositivo nuevo; su clave de seguridad abre los mensajes de antes. Ver [Copias de seguridad](#backup).",
  "**Matrix voice messages show their waveform, and Nostr answers can be photos**: a voice message sent in a Matrix chat carries its waveform, which Element draws, and one that comes with a waveform shows it under Play; in a Nostr chat, a photo, file or voice message sent while a message shows over the message box answers it. See [Matrix](#matrix) and [Chats with other Nostr apps](#nostr-chats).":
    "**Los mensajes de voz de Matrix muestran su forma de onda, y las respuestas en Nostr pueden ser fotos**: un mensaje de voz enviado en un chat de Matrix lleva su forma de onda, que Element dibuja, y uno que llega con forma de onda la muestra bajo Reproducir; en un chat de Nostr, una foto, un archivo o un mensaje de voz enviado mientras un mensaje aparece sobre el campo del mensaje le responde. Ver [Matrix](#matrix) y [Chats con otras apps de Nostr](#nostr-chats).",
  "**Group calls in XMPP groups**: in a private XMPP group, start a voice or video call, answer one that rings, or join one going on, together with people who use Dino. See [XMPP](#xmpp).":
    "**Llamadas de grupo en grupos de XMPP**: en un grupo privado de XMPP, inicia una llamada de voz o de video, responde a una que suena, o únete a una en curso, junto con personas que usan Dino. Ver [XMPP](#xmpp).",
  '**A call to a slow phone rings in full**: the caller now waits up to a minute and a quarter for the other phone to say it rings, and then 45 seconds from then, so a call that reached it late no longer rings there only to stop at once; and the phone called reads a call before anything it has to send, and waits for calls again at once after its network changes. See [Chat through a relay](#relay).':
    '**Una llamada a un teléfono lento suena entera**: quien llama espera ahora hasta un minuto y cuarto a que el otro teléfono diga que suena, y luego 45 segundos desde entonces, así que una llamada que le llegó tarde ya no suena allí solo para parar enseguida; y el teléfono que recibe la llamada la lee antes de todo lo que tiene que enviar, y vuelve a esperar llamadas de inmediato cuando cambia de red. Ver [Chatear a través de un relay](#relay).',
  "**The web app and the computer reach Matrix, XMPP and Nostr servers over HTTPS**: their page policy allowed only WebSocket connections, so Matrix sign-in, XMPP server discovery and file sharing, and Nostr files and name lookups failed there. They work now. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**La app web y el ordenador llegan a servidores de Matrix, XMPP y Nostr por HTTPS**: la política de su página solo permitía conexiones WebSocket, así que allí fallaban el inicio de sesión en Matrix, el descubrimiento del servidor XMPP y el envío de archivos, y los archivos y las búsquedas de nombres de Nostr. Ahora funcionan. Ver [Matrix](#matrix), [XMPP](#xmpp) y [Chats con otras apps de Nostr](#nostr-chats).",
  // 3.4.2
  '**A message sent as a chat opens waits for it**, marked Sending…, and goes as soon as the chat is open, never saying that Erevos cannot encrypt.':
    '**Un mensaje enviado mientras se abre un chat lo espera**, marcado Enviando…, y se va en cuanto el chat está abierto, sin decir que Erevos no puede cifrar.',
  '**What you read as a chat opens stays read**: the home screen no longer counts it as new.':
    '**Lo que lees mientras se abre un chat queda leído**: la pantalla de inicio ya no lo cuenta como nuevo.',
  '**No question from Samsung about its sharing**: on a Samsung phone, Wi-Fi Aware and the Wi-Fi with phones nearby stay off until you turn them on. See [Chat with a nearby phone](#nearby).':
    '**Samsung ya no pregunta por su uso compartido**: en un teléfono Samsung, Wi-Fi Aware y la Wi-Fi con teléfonos cercanos siguen desactivados hasta que los actives. Mira [Chatear con un teléfono cercano](#nearby).',
  '**The SMS field keeps its width on a small screen**: Photo and Send beside it are round buttons, as in a chat.':
    '**El campo del SMS conserva su ancho en una pantalla pequeña**: Foto y Enviar a su lado son botones redondos, como en un chat.',
  // 3.4.1
  '**Send answers at once**: a short buzz as you press it, the field empties and the message shows, marked Sending…, so it never goes twice.':
    '**Enviar responde al instante**: una breve vibración al pulsarlo, el campo se vacía y el mensaje aparece, marcado Enviando…, así que nunca sale dos veces.',
  '**The screen no longer stays pushed up** after the keyboard closed behind a sheet, a dialog or another app.':
    '**La pantalla ya no se queda desplazada hacia arriba** después de que el teclado se cerrara tras una hoja, un diálogo u otra app.',
  '**Importing a chat with its photos no longer freezes Erevos**: the screen moves while the files come in, says what share of them is in, and **Cancel** stops it. A chat moved into hidden chats takes the chats imported into it along. See [Imported chats](#import).':
    '**Importar un chat con sus fotos ya no congela Erevos**: la pantalla responde mientras llegan los archivos, dice qué parte ha llegado y **Cancelar** lo detiene. Un chat movido a los chats ocultos se lleva los chats importados en él. Consulta [Chats importados](#import).',
  // 3.4.0
  '**Your relay proves its own key**: every connection to it starts with a check only the relay holding that key can pass, so no one in between can pass for it. Once it has, Erevos never reaches it without the check. Your relay needs an update for it.':
    '**Tu relay demuestra su propia clave**: cada conexión con él empieza con una comprobación que solo supera el relay que tiene esa clave, así que nadie en medio puede hacerse pasar por él. Una vez que la ha superado, Erevos ya nunca se conecta a él sin la comprobación. Para ello tu relay necesita una actualización.',
  '[Transparency](#transparency), a new part of the guide: what the server behind Erevos keeps and for how long, what it does not keep, and who else sees something.':
    '[Transparencia](#transparency), una parte nueva de la guía: qué guarda el servidor que hay detrás de Erevos y durante cuánto tiempo, qué no guarda y quién más ve algo.',
  "**What's new**: this list, in Settings → General, by version.": '**Novedades**: esta lista, en Ajustes → General, por versión.',
  "**Nothing shows behind a chat's PIN**: none of the messages of a chat locked with a PIN is drawn until its PIN is typed, and with glass, a wallpaper or a style's own scene, the PIN screen is a dense frost that lets nothing through.":
    "**Nada se ve detrás del PIN de un chat**: ningún mensaje de un chat bloqueado con un PIN se muestra hasta escribir su PIN, y con cristal, un fondo de pantalla o un estilo con su propia escena, la pantalla del PIN es un esmerilado denso que no deja ver nada.",
  "**A group video call from the top of the group**: a blue camera beside the green handset, as in a contact's chat.":
    "**Videollamada de grupo desde arriba del grupo**: una cámara azul junto al auricular verde, como en el chat con un contacto.",
  "**A relay queue for each contact**: each contact writes to a queue only they know, so the relay cannot tell that two contacts write to the same phone, and deleting or blocking someone deletes only theirs. Your relay needs an update for it.":
    "**Una cola del relay para cada contacto**: cada contacto escribe en una cola que solo él conoce, así el relay no puede saber que dos contactos escriben al mismo teléfono, y eliminar o bloquear a alguien borra solo la suya. Tu relay necesita una actualización para ello.",
  "**Hidden chats, more like the others**: they close after 30 seconds in the background, not at once, and never during a call or while you pick a photo or a file; while open, a message plays its sound, and link previews have a switch of their own there. See [Hidden chats](#hidden).":
    "**Los chats ocultos, más como los demás**: se cierran tras 30 segundos en segundo plano, no al instante, y nunca durante una llamada ni mientras eliges una foto o un archivo; mientras están abiertos, un mensaje suena, y las vistas previas de enlaces tienen allí su propio interruptor. Consulta [Chats ocultos](#hidden).",
  "**Hidden chats that receive while closed**: a switch at the top of each place, on for new places, has them receive as your other chats do: their contacts see at once that a message came, a notice says only \"New message\", and a call rings with no name. See [Hidden chats](#hidden).":
    "**Chats ocultos que reciben estando cerrados**: un interruptor arriba de cada lugar, activado en los lugares nuevos, hace que reciban como tus otros chats: sus contactos ven al instante que un mensaje llegó, un aviso dice solo «Mensaje nuevo», y una llamada suena sin nombre. Consulta [Chats ocultos](#hidden).",
  "**Hidden chats wait and import too**: what cannot go now waits, marked Waiting, and goes by itself through their relay; Send later works there as in your other chats; and a chat from Telegram, WhatsApp or Viber can be imported into a hidden chat, kept only there. See [Hidden chats](#hidden).":
    "**Los chats ocultos también esperan e importan**: lo que no puede enviarse ahora queda en espera, marcado «En espera», y se envía solo a través de su relay; «Enviar más tarde» funciona allí como en tus otros chats; y un chat de Telegram, WhatsApp o Viber puede importarse a un chat oculto y quedarse solo allí. Consulta [Chats ocultos](#hidden).",
  "**Hidden chats listed like your chats**: they open on a list as the home screen's, with what was said last and how many are not read, and each place has a Chat with myself of its own at its top. See [Hidden chats](#hidden).":
    "**Los chats ocultos en una lista como tus chats**: se abren en una lista como la de la pantalla de inicio, con lo último que se dijo y cuántos no se han leído, y cada posición tiene arriba su propio Chat conmigo. Consulta [Chats ocultos](#hidden).",
  "**More in hidden chats**: with Receive while closed on, what comes to them through Nostr is read while they are closed too; and there a contact can be added from a photo of their QR code, and a hidden contact given a photo. See [Hidden chats](#hidden).":
    "**Más en los chats ocultos**: con Recibir estando cerrados, lo que les llega por Nostr también se lee mientras están cerrados; y allí se puede añadir un contacto desde una foto de su código QR y dar una foto a un contacto oculto. Consulta [Chats ocultos](#hidden).",
  "**Hidden chats with no relay**: as your other chats, they can begin through Nostr only: their contact link and QR code say where they read there, and texts and reactions go there. See [Hidden chats](#hidden).":
    "**Chats ocultos sin relay**: como tus otros chats, pueden empezar solo por Nostr: su enlace de contacto y su código QR dicen dónde leen allí, y los textos y las reacciones van allí. Consulta [Chats ocultos](#hidden).",
  "**Groups in hidden chats**: under their list, New group makes a group with their contacts; it lists among their chats, goes through their relay only, and is read while they are closed if Receive while closed is on. See [Hidden chats](#hidden).":
    "**Grupos en chats ocultos**: bajo su lista, Grupo nuevo crea un grupo con sus contactos; aparece entre sus chats, va solo por su relay y se lee mientras están cerrados si Recibir estando cerrados está activado. Consulta [Chats ocultos](#hidden).",
  "**No test version line**: the home screen no longer ends saying this is a test version. The guide still says exactly what is protected, and that nothing has been audited yet. See [What is protected today](#privacy).":
    "**Sin la línea de versión de prueba**: la pantalla de inicio ya no termina diciendo que es una versión de prueba. La guía sigue diciendo exactamente qué está protegido, y que nada se ha auditado todavía. Consulta [Qué está protegido hoy](#privacy).",
  "**The contacts menu in hidden chats**: their Contacts has a menu again, with what is theirs only: a .vcf file imported into them, their contacts saved as a .vcf file, and a contact's QR code read from a photo. An Erevos ID typed there adds them to the hidden chats. See [Contacts](#contacts).":
    "**El menú de contactos en los chats ocultos**: sus Contactos vuelven a tener menú, solo con lo suyo: importar en ellos un archivo .vcf, guardar sus contactos como archivo .vcf y leer el código QR de un contacto desde una foto. Un ID de Erevos escrito allí lo añade a los chats ocultos. Consulta [Contactos](#contacts).",
  // 3.3.2
  '**The plain call button for more contacts**: the orange keypad at the top of a contact’s chat also takes the number of a contact you connected them to (**Connect to one of my contacts**), the mobile number first.':
    '**El botón de llamada normal, en más contactos**: el teclado naranja de arriba en el chat de un contacto también usa el número del contacto al que lo vinculaste (**Vincular a uno de mis contactos**), primero el móvil.',
  // 3.3.1
  '**Viber chats can be imported**: from the HTML file of the Android app Backup Text for Viber, words only.':
    '**Ya se pueden importar chats de Viber**: desde el archivo HTML de la app de Android Backup Text for Viber, solo el texto.',
  // 3.3.0
  '**Start without a relay, through Nostr**: **Start without a relay** on New chat. Texts, stickers, reactions, edits and the delivered and read marks go through Nostr over Tor. Photos, voice messages, files and calls still need a relay or a phone nearby.':
    '**Empezar sin relay, por Nostr**: **Empezar sin relay** en Chat nuevo. Los textos, stickers, reacciones, ediciones y las marcas de entregado y leído van por Nostr a través de Tor. Las fotos, los mensajes de voz, los archivos y las llamadas siguen necesitando un relay o un teléfono cerca.',
  '**The relay comes by itself**: whoever has a relay that invites sends a contact with no relay an invite once, inside the chat, and the other phone takes it by itself.':
    '**El relay llega solo**: quien tiene un relay que invita envía una vez una invitación a un contacto sin relay, dentro del chat, y el otro teléfono la acepta solo.',
  '**Told when a new version is out** (Android): once a day Erevos asks LPHL’s server, then shows a pinned Erevos row and a notice, only for a version the release computer signed. It turns off in Settings → General → Updates.':
    '**Aviso cuando sale una versión nueva** (Android): una vez al día Erevos pregunta al servidor de LPHL y luego muestra una fila de Erevos fijada y un aviso, solo para una versión firmada por el ordenador de versiones. Se desactiva en Ajustes → General → Actualizaciones.',
  '**Lock a chat with a PIN**: Details → Lock with a PIN, for chats and groups. Nothing of it shows in search, starred messages or imports. In hidden chats it asks for no PIN.':
    '**Bloquear un chat con un PIN**: Detalles → Bloquear con un PIN, para chats y grupos. Nada de él aparece en la búsqueda, los mensajes destacados ni las importaciones. En los chats ocultos no pide PIN.',
  '**A new handset** on the green tiles: Phone, and the call in a chat.': '**Un auricular nuevo** en los recuadros verdes: Teléfono, y la llamada en un chat.',
  '**A new New chat screen**: How you connect now at the top, three large cards for a phone without a relay (I have an invite, Sign in with LPHL, Start without a relay), and the technical part under For advanced users.':
    '**Una pantalla de Chat nuevo renovada**: «Cómo te conectas ahora» arriba, tres tarjetas grandes para un teléfono sin relay (Tengo una invitación, Iniciar sesión con LPHL, Empezar sin relay), y la parte técnica en «Para usuarios avanzados».',
  '**Nostr steadier through Tor**: each Nostr relay has its own way through Tor, and after a failure it tries a new exit. A clearer error on the Nostr screen.':
    '**Nostr más estable por Tor**: cada relay de Nostr tiene su propio camino por Tor, y tras un fallo prueba una salida nueva. Un error más claro en la pantalla de Nostr.',
  '**When the connection to the relay drops** while Erevos waits on it, Erevos notices and connects again, where it stayed stuck before.':
    '**Cuando se corta la conexión con el relay** mientras Erevos espera su respuesta, Erevos se da cuenta y vuelve a conectarse; antes se quedaba atascado.',
  '**Invite by SMS** (Android): on a phone contact’s card, for one person, for 2 days. The link opens a page that offers Erevos (the APK for Android, the web app for an iPhone or a computer), then opens the invite. The QR code and Share the invite stay as they were.':
    '**Invitar por SMS** (Android): en la ficha de un contacto del teléfono, para una persona, durante 2 días. El enlace abre una página que ofrece Erevos (el APK para Android, la app web para un iPhone o un ordenador) y luego abre la invitación. El código QR y «Compartir la invitación» siguen como estaban.',
  '**Fixes to the SMS invite**: a link copied as /i/#… works too, an older web app opens the invite as well, and on iOS 26 it says Share is under •••.':
    '**Arreglos en la invitación por SMS**: también funciona un enlace copiado como /i/#…, una app web más antigua también abre la invitación, y en iOS 26 indica que Compartir está dentro de •••.',
  '**A phone call button** in Erevos chats and SMS chats.': '**Un botón de llamada telefónica** en los chats de Erevos y en los de SMS.',
  // 3.2.1
  '**Edit a message** you sent, up to a day after: to contacts, groups and linked devices, with Edited beside the time.':
    '**Editar un mensaje** que enviaste, hasta un día después: a contactos, grupos y dispositivos vinculados, con «Editado» junto a la hora.',
  '**Nostr says what it did**: Sent through Nostr, and on the Nostr screen what each relay did last.':
    '**Nostr dice lo que hizo**: «Enviado por Nostr», y en la pantalla de Nostr lo último que hizo cada relay.',
  '**Coloured call buttons** at the top of a chat: video blue, voice green.': '**Botones de llamada de colores** arriba en el chat: vídeo en azul, voz en verde.',
  // 3.2.0
  'Arrows to the start and the end of a chat; earlier messages come by themselves as you scroll.':
    'Flechas para ir al principio y al final de un chat; los mensajes anteriores se cargan solos al desplazarte.',
  'Chats imported from Telegram and WhatsApp look like Erevos messages: bubbles, days, photos, voice messages, search.':
    'Los chats importados de Telegram y WhatsApp se ven como mensajes de Erevos: burbujas, días, fotos, mensajes de voz, búsqueda.',
  'Dogs instead of cats in the stickers.': 'Perros en lugar de gatos en los stickers.',
  'Screenshots: a switch in Settings → Privacy and security.': 'Capturas de pantalla: un interruptor en Ajustes → Privacidad y seguridad.',
  'Hidden chats from New chat: hold it for a second.': 'Chats ocultos desde Chat nuevo: mantenlo pulsado un segundo.',
  'Coloured tiles on the home screen: Phone green, Contacts violet, the lock orange.': 'Recuadros de colores en la pantalla de inicio: Teléfono verde, Contactos violeta, el candado naranja.',
  '**Chat with myself**, always first, and **Remind me**, the orange bell.': '**Chat conmigo**, siempre el primero, y **Recordarme**, la campana naranja.',
  '**Media, links and files** in a chat’s Details, with a calendar and Go to a day.':
    '**Multimedia, enlaces y archivos** en los Detalles de un chat, con un calendario e «Ir a un día».',
  'Import a chat from inside the chat: Details → Imported chats.': 'Importar un chat desde dentro del chat: Detalles → Chats importados.',
  'A closed space can say that a message came while another space is open.': 'Un espacio cerrado puede avisar de que llegó un mensaje mientras otro espacio está abierto.',
  'The message menu says when a message went or came through Nostr.': 'El menú del mensaje indica cuándo un mensaje se envió o llegó por Nostr.',
  '**Support Erevos**: Liberapay, PayPal, Monero, Bitcoin.': '**Apoyar Erevos**: Liberapay, PayPal, Monero, Bitcoin.',
  'Who makes Erevos and why, in About Erevos; the guide says why everywhere.': 'Quién hace Erevos y por qué, en Acerca de Erevos; la guía explica el porqué en todas partes.',
  // 3.1.2
  '**Settings in 8 groups**, with a search: General, Appearance, Notifications, Privacy and security, Relay and networks, Phone and SMS, Data and devices, For testing. The home screen’s ⋯ keeps only the places, and Settings last.':
    '**Ajustes en 8 grupos**, con búsqueda: General, Apariencia, Notificaciones, Privacidad y seguridad, Relay y redes, Teléfono y SMS, Datos y dispositivos, Para pruebas. El ⋯ de la pantalla de inicio solo conserva los lugares, y Ajustes al final.',
  // 3.1.1
  'Check for updates says what stopped an update.': '«Buscar actualizaciones» indica qué impidió una actualización.',
  'Invite someone is not made from a token for all; it asks you to sign in to the relay first.':
    '«Invitar a alguien» no se crea a partir de un token para todos; primero te pide iniciar sesión en el relay.',
  'The relay’s token for all becomes a token of the phone’s own, by itself (needs the relay updated).':
    'El token para todos del relay se convierte solo en un token propio del teléfono (requiere el relay actualizado).',
  'A relay that refuses through Tor says why.': 'Un relay que rechaza la conexión por Tor dice por qué.',
  // 3.1.0
  'Less battery in the background: the relay, Tor and the nearby radios.': 'Menos batería en segundo plano: el relay, Tor y las radios para teléfonos cercanos.',
  'Erevos no longer closes when you make a sticker from a photo.': 'Erevos ya no se cierra cuando haces un sticker a partir de una foto.',
  'Hidden chats’ notices are right.': 'Los avisos de los chats ocultos son correctos.',
  'Hidden chats by holding New chat.': 'Chats ocultos manteniendo pulsado Chat nuevo.',
  'A search for contacts on the Phone.': 'Búsqueda de contactos en el Teléfono.',
  'New chat shows first how to add a contact.': 'Chat nuevo muestra primero cómo añadir un contacto.',
  'A call shows over the screen saver, and the screen wakes.': 'Una llamada aparece por encima del salvapantallas, y la pantalla se enciende.',
  'Erevos in other apps’ Share.': 'Erevos en el menú Compartir de otras apps.',
  'A sound for every new message, also while Erevos shows.': 'Un sonido para cada mensaje nuevo, también con Erevos en pantalla.',
  'The SMS settings say right what holding does.': 'Los ajustes de SMS explican bien qué hace mantener pulsado.',
  // 3.0.0
  'Each icon opens what it names: Erevos, SMS, Phone, Contacts, the widget.': 'Cada icono abre lo que indica: Erevos, SMS, Teléfono, Contactos, el widget.',
  '**Messages through Tor by default**: Messages, Everything or Nothing.': '**Mensajes por Tor de forma predeterminada**: Mensajes, Todo o Nada.',
  '**Texts through Nostr**: three public relays, through Tor, with your own relay as backup after 5 minutes.':
    '**Textos por Nostr**: tres relays públicos, por Tor, con tu propio relay como respaldo pasados 5 minutos.',
  // 2.0.3
  'One invite for everything: the relay and the contact together.': 'Una sola invitación para todo: el relay y el contacto a la vez.',
  'Spam rules for senders and numbers abroad, with the reason.': 'Reglas de spam para remitentes y números del extranjero, con el motivo.',
  '480 stickers in 20 sets.': '480 stickers en 20 paquetes.',
  'Lighter chats on older phones; QR codes at once.': 'Chats más ligeros en teléfonos antiguos; códigos QR al instante.',
  'Copy code for one-time codes in SMS.': '«Copiar código» para los códigos de un solo uso en los SMS.',
  'Locked, Erevos keeps receiving.': 'Bloqueado, Erevos sigue recibiendo.',
  'Faster contacts; the hidden chats’ notice counts only messages.': 'Contactos más rápidos; el aviso de los chats ocultos solo cuenta mensajes.',
  'The relay tries every address: push, other relays, the LPHL sign-in.': 'El relay prueba todas las direcciones: push, otros relays, el inicio de sesión con LPHL.',
  // 2.0.2
  'Swiping on the tabs only changes the tab.': 'Deslizar sobre las pestañas solo cambia de pestaña.',
  'The icons fill the launcher’s shape.': 'Los iconos llenan la forma del lanzador.',
  // 2.0.1
  'Coloured icons (Erevos red, Phone green, SMS blue, Contacts violet) and a new SMS icon.':
    'Iconos de colores (Erevos rojo, Teléfono verde, SMS azul, Contactos violeta) y un icono de SMS nuevo.',
  'A colour for each icon, and the order of the widget’s buttons.': 'Un color para cada icono, y el orden de los botones del widget.',
  'Swipe to go back, and between tabs.': 'Deslizar para volver atrás, y entre pestañas.',
  // 2.0.0
  'An update of the WebView no longer closes Erevos.': 'Una actualización del WebView ya no cierra Erevos.',
  'Deleting or blocking a contact gives you a new queue on the relay.': 'Al eliminar o bloquear un contacto recibes una cola nueva en el relay.',
  'A new contact can take the name of a contact on the phone.': 'Un contacto nuevo puede tomar el nombre de un contacto del teléfono.',
  '**Sign in to the relay with LPHL**, and **invites to the relay**.': '**Iniciar sesión en el relay con LPHL**, e **invitaciones al relay**.',
  'Permissions in the web app, and more on Android; the web app’s notice says how many came.':
    'Permisos en la app web, y más en Android; el aviso de la app web dice cuántos mensajes llegaron.',
  'Hidden chats can ring calls while they are closed.': 'Los chats ocultos pueden sonar las llamadas mientras están cerrados.',
  'New keys every month in chats, every week in groups.': 'Claves nuevas cada mes en los chats, cada semana en los grupos.',
  'Linked devices work with the phone off.': 'Los dispositivos vinculados funcionan con el teléfono apagado.',
  'A new chat screen; QR codes from a photo; the Phone for small screens.': 'Una pantalla de chat nueva; códigos QR desde una foto; el Teléfono para pantallas pequeñas.',
  'Add as contact inside a group.': '«Añadir como contacto» dentro de un grupo.',
  'Stickers in sets, moving, and your own.': 'Stickers en paquetes, animados y propios.',
  'SMS inside the Erevos chat.': 'SMS dentro del chat de Erevos.',
  'Android updates need the release computer’s signature.': 'Las actualizaciones de Android necesitan la firma del ordenador de versiones.',
  'An F-Droid build; Serbo-Croatian; new version numbers.': 'Una versión para F-Droid; serbocroata; números de versión nuevos.',
  'Much for security: Argon2id, messages encrypted for the relay too, a token for each phone, no link starts a call.':
    'Mucho para la seguridad: Argon2id, mensajes cifrados también para el relay, un token para cada teléfono, ningún enlace inicia una llamada.',
  // 0.1.16
  'Imports from Telegram and WhatsApp bring photos, videos, voice messages and files.': 'Las importaciones de Telegram y WhatsApp traen fotos, vídeos, mensajes de voz y archivos.',
  'A phone without a relay talks through a place on a contact’s relay.': 'Un teléfono sin relay se comunica a través de un sitio en el relay de un contacto.',
  // 0.1.14
  'Back to my chats, for hidden chats.': '«Volver a mis chats», para los chats ocultos.',
  'Erevos receives and rings even after you swipe it away from the recent apps.': 'Erevos recibe y suena incluso después de quitarlo de las apps recientes.',
  // 0.1.12
  'Hidden chats can say a message came.': 'Los chats ocultos pueden avisar de que llegó un mensaje.',
  'Fixes: menus, QR codes from a photo, Bluetooth on Android 17, long lists.': 'Arreglos: menús, códigos QR desde una foto, Bluetooth en Android 17, listas largas.',
  // 0.1.11
  'The Phone without the password, if you allow it; a home screen widget; an SMS and Erevos filter.':
    'El Teléfono sin la contraseña, si lo permites; un widget para la pantalla de inicio; un filtro de SMS y Erevos.',
  // 0.1.10
  'Links wait for the password; Phone and Contacts icons; the Erevos ID on a contact.': 'Los enlaces esperan a la contraseña; iconos de Teléfono y Contactos; el ID de Erevos en un contacto.',
  // 0.1.8
  '61 new features: 5 new languages, linked devices, public groups, replies, reactions, polls, send later, Erevos as the phone and contacts app, Tor bridges, the fingerprint, Windows and more.':
    '61 funciones nuevas: 5 idiomas nuevos, dispositivos vinculados, grupos públicos, respuestas, reacciones, encuestas, enviar más tarde, Erevos como app de teléfono y contactos, puentes de Tor, la huella, Windows y más.',
  // 0.1.7 to 0.1.2
  'SMS notices in the background.': 'Avisos de SMS en segundo plano.',
  'The web app comes out with every release.': 'La app web sale con cada versión.',
  'Greek in the whole app.': 'Griego en toda la app.',
  'Web Push in the web app.': 'Web Push en la app web.',
  'The first signed Android release: encrypted chats, calls, groups, hidden chats, backups, imports, and phones nearby without the internet.':
    'La primera versión firmada para Android: chats cifrados, llamadas, grupos, chats ocultos, copias de seguridad, importaciones y teléfonos cercanos sin internet.',
  "**Two new sticker sets of 24 moods**: **Tux**, the Linux penguin as he is drawn, and **Aikido**, an aikidoka in keikogi and a wide hakama, who also bows, sits in seiza and rolls.":
    "**Dos nuevos conjuntos de stickers con 24 estados de ánimo**: **Tux**, el pingüino de Linux tal como está dibujado, y **Aikido**, un aikidoka con keikogi y un hakama amplio, que también se inclina, se sienta en seiza y rueda.",
  "**A new sticker set, Takis**: a caricature in a dark suit and a purple tie with dots, in 24 moods that move.":
    "**Un nuevo conjunto de stickers, Takis**: una caricatura con traje oscuro y corbata morada de lunares, en 24 estados de ánimo que se mueven.",
  "**Photos, files and voice messages with no relay**: when there is no relay between you and your contact and they read on Nostr, a voice message goes through Nostr like a text, a photo up to 3 MB in pieces, and a larger photo, a video or another file, up to 20 MB, to an encrypted file server (Blossom), all through Tor. See [Through Nostr](#nostr).":
    "**Fotos, archivos y mensajes de voz sin relay**: cuando no hay relay entre tú y tu contacto y este lee en Nostr, un mensaje de voz va por Nostr como un texto, una foto de hasta 3 MB en trozos, y una foto mayor, un vídeo u otro archivo, de hasta 20 MB, a un servidor de archivos cifrado (Blossom), todo por Tor. Ver [A través de Nostr](#nostr).",
  "**More battery saved in the background, if you choose**: under Settings → Notifications → In the background, Only the waste stays the default; And nearby phones also turns off the radios for phones nearby while Erevos is in the background; And sleep also lets the phone sleep, so Erevos looks at your relay about once a minute and a message or a call can be a minute or two late. Android only. See [Chat through a relay](#relay).":
    "**Más batería ahorrada en segundo plano, si lo eliges**: en Ajustes → Notificaciones → En segundo plano, Solo lo que se desperdicia sigue siendo lo habitual; Y los teléfonos cercanos apaga también las radios para teléfonos cercanos mientras Erevos está en segundo plano; Y el sueño deja dormir también al teléfono, así que Erevos mira tu relay una vez por minuto y un mensaje o una llamada puede llegar uno o dos minutos tarde. Solo en Android. Ver [Chatear a través de un relay](#relay).",
  "**A contact you delete no longer comes back from an old ask**: in a group, a member you asked for their contact link, or who asked for yours, and whom you then deleted as a contact before Erevos looked at the relay again, could be added again by that old ask. Deleting them now lets go of it at once. See [Group chats](#groups).":
    "**Un contacto que borras ya no vuelve por una petición antigua**: en un grupo, un miembro al que pediste su enlace de contacto, o que pidió el tuyo, y al que luego borraste como contacto antes de que Erevos volviera a mirar el relay, podía añadirse de nuevo por esa petición antigua. Ahora borrarlo la suelta al instante. Ver [Chats de grupo](#groups).",
  "**Every message says which way it went**: hold a message and its menu says whether it went or came through the relay, through Nostr, to a phone nearby or over LoRa. Messages from before say nothing. See [Through Nostr](#nostr).":
    "**Cada mensaje dice por dónde fue**: mantén pulsado un mensaje y su menú dice si fue o llegó por el relay, por Nostr, por un teléfono cercano o por LoRa. Los mensajes anteriores no dicen nada. Mira [A través de Nostr](#nostr).",
  "**The spam filter reads words as they look**: a scam text that swaps a letter for a look-alike of another alphabet, or hides a mark that shows nothing inside a word, no longer gets past it. See [SMS](#sms).":
    "**El filtro de spam lee las palabras como se ven**: un SMS de estafa que cambia una letra por una parecida de otro alfabeto, o esconde dentro de una palabra una marca que no se ve, ya no lo engaña. Mira [SMS](#sms).",
  "**Media, links and files in groups too**: in a group's details, a list of its photos, videos, voice messages, music, files and links, each kind apart under its months, with a calendar, as in a contact's chat. A tap opens or plays; held, each goes to its message. See [Group chats](#groups).":
    "**Multimedia, enlaces y archivos también en los grupos**: en los detalles de un grupo, una lista de sus fotos, vídeos, mensajes de voz, música, archivos y enlaces, cada tipo aparte bajo sus meses, con un calendario, como en el chat de un contacto. Un toque abre o reproduce; mantenido, cada uno va a su mensaje. Mira [Chats de grupo](#groups).",
  "**A relay restart no longer brings a false notice**: after your relay restarted, a hidden chat or a closed space said New message once more for messages it had told of already. Your relay needs an update for it. See [Hidden chats](#hidden).":
    "**Un reinicio del relay ya no trae un aviso falso**: después de que tu relay se reiniciara, un chat oculto o un espacio cerrado volvía a decir Mensaje nuevo por mensajes de los que ya había avisado. Tu relay necesita una actualización para ello. Mira [Chats ocultos](#hidden).",
  "**Backups to your server through Tor**: on Android, automatic backups sent to your own server now follow the space's choice under Settings → Relay and networks → Tor, as Matrix does, so with Tor the server no longer sees where you are. To a server too says when they go through Tor. See [Backups](#backup).":
    "**Copias a tu servidor por Tor**: en Android, las copias automáticas que van a tu propio servidor siguen ahora la elección del espacio en Ajustes → Relay y redes → Tor, como Matrix, así que con Tor el servidor ya no ve dónde estás. También a un servidor dice cuándo van por Tor. Ver [Copias de seguridad](#backup).",
  "**Restore a backup straight from your server**: Restore from a server, under Backups, lists the backups on your server, newest first, and opens the one you choose with its password, with no download by hand, on a new phone too. See [Backups](#backup).":
    "**Restaura una copia directamente desde tu servidor**: Restaurar desde un servidor, en Copias de seguridad, muestra las copias de tu servidor, las más recientes primero, y abre la que elijas con su contraseña, sin descargarla a mano, también en un teléfono nuevo. Ver [Copias de seguridad](#backup).",
  "**Backups to your server from a computer and the web app too**: in the desktop app, automatic backups go to your WebDAV server as on Android; in the web app, Send a backup now sends one there, with a server that lets the web app in. Both can restore from it. Not through Tor. See [Backups](#backup).":
    "**Copias a tu servidor también desde el ordenador y la web app**: en la app de escritorio, las copias automáticas van a tu servidor WebDAV como en Android; en la web app, Enviar una copia ahora envía una allí, con un servidor que deje entrar a la web app. Ambas pueden restaurar desde él. No por Tor. Ver [Copias de seguridad](#backup).",
  "**Check a contact in person with QR codes**: under Safety number in a chat's details, each phone shows a code; take a photo of the code on the other phone, and they of yours. When it matches, the contact is marked Checked in person. Nothing is sent. See [Chat through a relay](#relay).": "**Comprueba un contacto en persona con códigos QR**: en Número de seguridad, en los detalles de un chat, cada teléfono muestra un código; haz una foto del código del otro teléfono, y ellos del tuyo. Cuando coincide, el contacto queda marcado como Comprobado en persona. No se envía nada. Ver [Chatear a través de un relay](#relay).",
  "**Up to three home relays**: under Settings → Relay and networks → Home relay, Add another home relay gives a space up to two more, each with a queue of its own. Your contact link and your messages name them in order, and contacts try each while the ones before cannot be reached. See [Home relay](#home-relay).": "**Hasta tres relays de casa**: en Ajustes → Relay y redes → Relay de casa, Añadir otro relay de casa da a un espacio hasta dos más, cada uno con su propia cola. Tu enlace de contacto y tus mensajes los nombran en orden, y los contactos prueban cada uno mientras los anteriores no responden. Ver [Relay de casa](#home-relay).",
  "**Introduce two of your contacts**: in a contact's chat details, Introduce to a contact asks them and another contact of yours, each in your chat with them. Only if both say yes do they become contacts, and neither learns whether the other said no. See [Chat through a relay](#relay).": "**Presenta a dos de tus contactos**: en los detalles del chat de un contacto, Presentar a un contacto le pregunta a él y a otro de tus contactos, a cada uno en tu chat con él. Solo si los dos dicen que sí se hacen contactos, y ninguno sabe si el otro dijo que no. Ver [Chatear a través de un relay](#relay).",
  "**Bluetooth that cannot be followed**: the random number your phone sends out over Bluetooth for phones nearby to find it changed only when Erevos started again; it now changes every nine to twelve minutes, so someone listening cannot follow your phone from place to place by it. Older Erevos phones still find yours. See [Chat with a nearby phone](#nearby).": "**Bluetooth que no se puede seguir**: el número aleatorio que tu teléfono emite por Bluetooth para que los teléfonos cercanos lo encuentren solo cambiaba al reiniciar Erevos; ahora cambia cada nueve a doce minutos, así que nadie que escuche puede seguir tu teléfono de un sitio a otro con él. Los teléfonos con un Erevos más antiguo siguen encontrando el tuyo. Ver [Chatear con un teléfono cercano](#nearby).",
  "**Hidden chats show at once**: as the PIN opens them, their chats and contacts show at once, to read, while what they were receiving in the background ends; before, that could hold them back a long while, as it may go through Tor. See [Hidden chats](#hidden).": "**Los chats ocultos se ven al instante**: en cuanto el PIN los abre, sus chats y contactos se ven al instante, para leer, mientras termina lo que recibían en segundo plano; antes, eso podía retenerlos mucho tiempo, pues puede pasar por Tor. Ver [Chats ocultos](#hidden).",
  "**Your backup password in pieces with friends**: under Settings → Data and devices → Backup pieces, give pieces of it to 3 to 5 contacts; any 2 or 3 of them give it back, one alone shows nothing. Each goes inside the encryption of your chat with them and only their Erevos keeps it; your phone keeps none. See [Backup pieces with friends](#backup-pieces).": "**La contraseña de tus copias en piezas con amigos**: en Ajustes → Datos y dispositivos → Piezas de copias, da piezas de ella a entre 3 y 5 contactos; 2 o 3 cualesquiera la devuelven, una sola no muestra nada. Cada una va dentro del cifrado de tu chat con ellos y solo su Erevos la guarda; tu teléfono no guarda ninguna. Consulta [Piezas de copias con amigos](#backup-pieces).",
  "**Panic button**: under Settings → Privacy and security → Panic button, wipe everything Erevos keeps here with one tap, on Android and in the web app. On Android, a panic app such as Ripple can do it too, but only the one you say yes to, checked by its signature. See [Panic button](#panic).": "**Botón de pánico**: en Ajustes → Privacidad y seguridad → Botón de pánico, borra con un toque todo lo que Erevos guarda aquí, en Android y en la app web. En Android también puede hacerlo una app de pánico como Ripple, pero solo aquella a la que digas que sí, comprobada por su firma. Consulta [Botón de pánico](#panic).",
  "**Erevos to a phone nearby, with no internet**: under Settings → General → Give Erevos to a phone nearby, this phone serves its Erevos over the same Wi-Fi or its hotspot for ten minutes, with a QR code. A phone without Erevos downloads it in the browser; one with an older Erevos takes it under Updates → From a phone nearby, which installs it only when it is Erevos, signed as that one is. See [Erevos to a phone nearby](#give-app).": "**Erevos a un teléfono cercano, sin internet**: en Ajustes → General → Dar Erevos a un teléfono cercano, este teléfono sirve su Erevos por la misma Wi-Fi o su punto de acceso durante diez minutos, con un código QR. Un teléfono sin Erevos lo descarga en el navegador; uno con un Erevos más antiguo lo toma en Actualizaciones → Desde un teléfono cercano, que lo instala solo si es Erevos, firmado como ese. Consulta [Erevos a un teléfono cercano](#give-app).",
  "**Hidden chats with phones nearby**: while hidden chats are open, or receive while closed, they reach a contact's phone nearby over Bluetooth, Wi-Fi Aware, Wi-Fi Direct or the same Wi-Fi, with no internet, as your other chats do. The space never learns that a hidden contact is near, and nothing on the air tells their messages from the space's; other phones never carry them, and they never go over LoRa or by SMS. See [Hidden chats](#hidden).":
    "**Chats ocultos con teléfonos cercanos**: mientras los chats ocultos están abiertos, o reciben cerrados, llegan al teléfono de un contacto cercano por Bluetooth, Wi-Fi Aware, Wi-Fi Direct o en la misma Wi-Fi, sin internet, como tus otros chats. El espacio nunca sabe que un contacto oculto está cerca, y nada en el aire distingue sus mensajes de los del espacio; otros teléfonos nunca los llevan, y nunca van por LoRa ni por SMS. Consulta [Chats ocultos](#hidden).",
  "**The same Wi-Fi on Sailfish OS**: Erevos on Sailfish OS finds Erevos phones and computers on the same Wi-Fi or a phone's hotspot and talks with them with no internet, as on a computer. See [On Sailfish OS](#sailfish).":
    "**La misma Wi-Fi en Sailfish OS**: Erevos en Sailfish OS encuentra teléfonos y ordenadores con Erevos en la misma Wi-Fi o en el punto de acceso de un teléfono y habla con ellos sin internet, como en un ordenador. Consulta [En Sailfish OS](#sailfish).",
  "**Downloads stop at 100 MB**: a file, a backup from a server or any other download is read as it comes and stopped as soon as it passes 100 MB, or less where the network's files are smaller, such as 20 MB for Nostr files, so a file server a contact names can no longer fill the phone's memory with an answer without end. A backup on a server comes back up to 100 MB; download a larger one and open it with Restore a backup. See [Backups](#backup).":
    "**Las descargas se detienen en 100 MB**: un archivo, una copia desde un servidor o cualquier otra descarga se lee según llega y se detiene en cuanto pasa de 100 MB, o de menos donde los archivos de la red son más pequeños, como 20 MB para los archivos de Nostr, así que un servidor de archivos que nombra un contacto ya no puede llenar la memoria del teléfono con una respuesta sin fin. Una copia en un servidor vuelve hasta 100 MB; una mayor, descárgala y ábrela con Restaurar una copia de seguridad. Ver [Copias de seguridad](#backup).",
  "**Profile pictures on Matrix and XMPP**: contacts and Matrix rooms show their picture in the chat list, and you can set your own on the Matrix and XMPP screens (Choose a photo). Pictures are not encrypted on either network: the server sees them. See [Matrix](#matrix) and [XMPP](#xmpp).":
    "**Fotos de perfil en Matrix y XMPP**: los contactos y las salas de Matrix muestran su foto en la lista de chats, y puedes poner la tuya en las pantallas de Matrix y XMPP (Elegir una foto). Las fotos no están cifradas en ninguna de las dos redes: el servidor las ve. Mira [Matrix](#matrix) y [XMPP](#xmpp).",
  "**Run an XMPP group**: a group's admins can set its subject and take people out or bar them, its owner can rename it and make admins, and in a channel the admin sees who is in it and can put them out. See [XMPP](#xmpp).":
    "**Gestionar un grupo de XMPP**: los admins de un grupo ponen su asunto y expulsan o vetan a gente, el propietario le cambia el nombre y hace admins, y en un canal el admin ve quién está dentro y puede expulsarlo. Mira [XMPP](#xmpp).",
  "**Check a Matrix device by QR code**: once both sides accept a check, Erevos shows a code for Element (or another Erevos) to photograph, or photographs theirs, as Element does; comparing emoji stays one tap away. See [Matrix](#matrix).":
    "**Comprobar un dispositivo de Matrix con código QR**: cuando ambos lados aceptan una comprobación, Erevos muestra un código para que Element (u otro Erevos) lo fotografíe, o fotografía el suyo, como hace Element; comparar emoji sigue a un toque. Mira [Matrix](#matrix).",
  "**Sign in to Matrix with single sign-on** (Android): when your Matrix server signs people in on its own page, as matrix.org does, Sign in with single sign-on opens it in the browser and comes back to Erevos. See [Matrix](#matrix).":
    "**Entrar en Matrix con inicio de sesión único** (Android): cuando tu servidor Matrix inicia la sesión en su propia página, como matrix.org, «Iniciar sesión con inicio único (SSO)» la abre en el navegador y vuelve a Erevos. Ver [Matrix](#matrix).",
  "**A closed space tells of XMPP messages**: on Android, Say a message came under While this space is closed, on the XMPP screen, has a closed space say \"New message\" when something comes on XMPP while another space is open, never what, from whom or in which chat. Off until you choose it. It needs a relay updated for it and an XMPP server that sends notices to apps that are away; the XMPP server then learns the relay's name, and the relay when messages come. See [XMPP](#xmpp).":
    "**Un espacio cerrado avisa de mensajes de XMPP**: en Android, «Avisar de mensajes nuevos» en «Mientras este espacio está cerrado», en la pantalla de XMPP, hace que un espacio cerrado diga «Mensaje nuevo» cuando llega algo en XMPP mientras otro espacio está abierto, nunca qué, de quién ni en qué chat. Apagado hasta que lo elijas. Necesita un relay actualizado para ello y un servidor XMPP que envíe avisos a las apps inactivas; el servidor XMPP conoce entonces el nombre del relay, y el relay cuándo llegan mensajes. Ver [XMPP](#xmpp).",
  "**Linking a computer is clearer**: on a computer, Settings → Data and devices → Linked devices now starts with Link to my phone, with LPHL's relay filled in and Sign in with LPHL under the token, so no token has to be copied from the phone; and it says that the QR code shows once Link to my phone is tapped. See [Linked devices](#devices).":
    "**Vincular un ordenador es más claro**: en un ordenador, Ajustes → Datos y dispositivos → Dispositivos vinculados empieza ahora por «Vincular a mi teléfono», con el relay de LPHL ya rellenado e «Iniciar sesión con LPHL» bajo el token, así que no hace falta copiar ningún token desde el teléfono; y dice que el código QR aparece al tocar «Vincular a mi teléfono». Ver [Dispositivos vinculados](#devices).",
  "**Delete me from everywhere**: Settings → Privacy and security → Delete me from everywhere deletes what the servers keep for the open space (its queues on the relays with the messages in them, what a relay holds for you to send later, files waiting there, invites nobody used), asks the Nostr relays through Tor to forget the keys your chats read on, and stops the space until you tap Start again. Your phone keeps everything. You can also sign out of Matrix and XMPP and delete the Nostr account made here. See [Delete me from everywhere](#forget).": "**Borrarme de todas partes**: Ajustes → Privacidad y seguridad → Borrarme de todas partes borra lo que los servidores guardan del espacio abierto (sus colas en los relés con los mensajes dentro, lo que un relé guarda para enviarte más tarde, archivos que esperan allí, invitaciones que nadie usó), pide por Tor a los relés de Nostr que olviden las claves en las que leen tus chats, y detiene el espacio hasta que toques Iniciar de nuevo. Tu teléfono lo conserva todo. También puedes cerrar sesión en Matrix y XMPP y borrar la cuenta de Nostr creada aquí. Ver [Borrarme de todas partes](#forget).",
  "**Every relay queue on one list**: the queues a space keeps on the relays are gathered in one place, and the checks fail if a new kind of queue is made without being added there, so Delete me from everywhere cannot leave one behind.": "**Cada cola de relé en una lista**: las colas que un espacio guarda en los relés se reúnen en un solo lugar, y las comprobaciones fallan si se crea un tipo nuevo de cola sin añadirlo allí, para que Borrarme de todas partes no deje ninguna atrás.",
  "**Matrix, XMPP and Nostr on a linked computer**: linking a computer can bring this space's Matrix and XMPP accounts and the key of its Nostr chats over too, each signed in there as a new device of its own; for a computer linked already, tap Send the accounts under it on the phone. A Matrix server seldom lets the phone sign the computer in: the computer then asks for the Matrix password once, and the account's keys come from the phone, so no Security Key or check by emoji is needed. See [Linked devices](#devices).":
    "**Matrix, XMPP y Nostr en un ordenador vinculado**: al vincular un ordenador se pueden traer también las cuentas de Matrix y XMPP de este espacio y la clave de sus chats de Nostr, cada una con la sesión iniciada allí como un dispositivo nuevo propio; para un ordenador ya vinculado, toca «Enviar las cuentas» bajo él en el teléfono. Un servidor de Matrix rara vez deja que el teléfono abra sesión para el ordenador: entonces el ordenador pide la contraseña de Matrix una sola vez, y las claves de la cuenta vienen del teléfono, así que no hace falta clave de seguridad ni comprobar con emojis. Ver [Dispositivos vinculados](#devices).",
  "**Only the SMS**: with Erevos locked, the SMS icon, the widget's SMS button and the notice of a new SMS ask for the password, then open only the SMS. Anything else, and the orange padlock **Unlock everything**, asks for it again, then opens all of Erevos. See [Password lock](#lock).":
    "**Solo los SMS**: con Erevos bloqueado, el icono de SMS, el botón SMS del widget y el aviso de un SMS nuevo piden la contraseña y luego abren solo los SMS. Todo lo demás, incluido el candado naranja **Desbloquear todo**, la pide otra vez y luego abre todo Erevos. Consulta [Bloqueo con contraseña](#lock).",
  "**Nostr chats with a key brought from another app get their messages again**: Erevos reads where that app said your messages arrive, as that app does, instead of its own three relays, fetches the messages kept there and in older lists of the key, and reads a relay again when it stops sending. Before, such a key could show its chats with no past messages and get no new ones. See [Chats with other Nostr apps](#nostr-chats).":
    "**Los chats de Nostr con una clave traída de otra app vuelven a recibir sus mensajes**: Erevos lee donde esa app indicó que llegan tus mensajes, como hace esa app, en lugar de sus tres relays propios, trae los mensajes guardados allí y en listas anteriores de la clave, y vuelve a leer un relay cuando deja de enviar. Antes, una clave así podía mostrar sus chats sin mensajes anteriores y no recibir ninguno nuevo. Consulta [Chats con otras apps de Nostr](#nostr-chats).",
  "**Backups keep what closed chats need**: a backup now also holds what lets hidden chats ring a call and say a message came while they are closed, and a closed space say one came. So after a restore, on another phone too, **Ring calls when closed**, **Say when a message comes** and **Also while another space is open** go on as they were. See [Backups](#backup).":
    "**Las copias guardan lo que necesitan los chats cerrados**: una copia guarda ahora también lo que permite a los chats ocultos sonar una llamada y avisar de que llegó un mensaje mientras están cerrados, y a un espacio cerrado avisar de que llegó uno. Así, tras restaurarla, también en otro teléfono, **Sonar las llamadas cuando están cerrados**, **Avisar cuando llega un mensaje** y **También mientras otro espacio está abierto** siguen como estaban. Ver [Copias de seguridad](#backup).",
  "**Open another space from the search**: type another space's password in **Search chats** on the home screen and press Enter: the open space closes, nothing of it stays, and the other opens, as with **Lock now** and its password. It takes as long whatever is typed, and a wrong password, or the open space's own, is just a search. See [Second password](#second).":
    "**Abrir otro espacio desde la búsqueda**: escribe la contraseña de otro espacio en **Buscar chats** de la pantalla de inicio y pulsa Enter: el espacio abierto se cierra, sin que quede nada de él, y se abre el otro, como con **Bloquear ahora** y su contraseña. Tarda lo mismo escribas lo que escribas, y una contraseña equivocada, o la del espacio abierto, es solo una búsqueda. Ver [Segunda contraseña](#second).",
  "**A dot for unread messages elsewhere, if you want it**: hidden chats with **Receive while closed** can show a small dot on the magnifier of **Search chats** while they have a message unread (their switch **Dot for unread messages**), and a space set to say a message came while another is open can show one on the padlock at the top of the other spaces' chats (**Dot in the other spaces**). Never how many, nor where; off unless you turn it on. See [Hidden chats](#hidden).":
    "**Un punto para lo no leído en otra parte, si lo quieres**: los chats ocultos con **Recibir estando cerrados** pueden mostrar un pequeño punto en la lupa de **Buscar chats** mientras tengan un mensaje sin leer (su interruptor **Punto para lo no leído**), y un espacio que avisa de que llegó un mensaje mientras otro está abierto puede mostrar uno en el candado sobre los chats de los otros espacios (**Punto en los otros espacios**). Nunca cuántos, ni dónde; apagado salvo que lo actives. Ver [Chats ocultos](#hidden).",
  "**Joining takes only the invite**: on a phone with no relay yet, **New chat** shows one way in, **I have an invite**. Signing in with LPHL, **Start without a relay** and the relay's settings are under **For advanced users**, for whoever looks for them. And an invite to your relay gives the relay only a name of random letters and digits for the phone it lets in: the name you type stays on your phone, where your list of invites shows it. See [Chat through a relay](#relay).":
    "**Para entrar basta la invitación**: en un teléfono que aún no tiene relay, **Chat nuevo** muestra una forma de entrar, **Tengo una invitación**. Iniciar sesión con LPHL, **Empezar sin relay** y los ajustes del relay están en **Para usuarios avanzados**, para quien los busque. Y una invitación a tu relay da al relay solo un nombre de letras y cifras al azar para el teléfono que deja entrar: el nombre que escribes se queda en tu teléfono, donde lo muestra tu lista de invitaciones. Ver [Chatear a través de un relay](#relay).",
  "**Invited phones stay**: on a relay of this version, a phone you invited keeps its access even once yours goes, and so do the phones it invited; taking back an invite cuts off that one phone alone. See [Chat through a relay](#relay).":
    "**Los teléfonos invitados se quedan**: en un relay de esta versión, un teléfono que invitaste conserva su acceso aunque el tuyo se vaya, y lo mismo los teléfonos que este invitó; retirar una invitación corta solo ese teléfono. Ver [Chatear a través de un relay](#relay).",
  "**Backups bring the phone back as it was**: a backup now holds the photos, files and voice messages too, in files of their own beside it, each sealed and bound to its backup; and the panic password, the settings that go with you, the Phone's quick replies and the calls it turns away, the SMS for later and automatic backups with their server, but not their folder. An SMS for later whose time passed before the restore waits for you to send it or delete it. What stays with each phone, as the fingerprint, the folders and what Android allows, never comes back: after a restore, Android's permissions open for the modules that are on. See [Backups](#backup).":
    "**Las copias devuelven el teléfono tal como estaba**: una copia guarda ahora también las fotos, los archivos y los mensajes de voz, en archivos propios junto a ella, cada uno sellado y atado a su copia; y la contraseña de pánico, los ajustes que te acompañan, las respuestas rápidas del Teléfono y las llamadas que rechaza, los SMS para más tarde y las copias automáticas con su servidor, pero no su carpeta. Un SMS para más tarde cuya hora pasó antes de la restauración espera a que lo envíes o lo borres. Lo que se queda en cada teléfono, como la huella, las carpetas y lo que Android permite, nunca vuelve: tras una restauración se abren los permisos de Android para los módulos activados. Ver [Copias de seguridad](#backup).",
  "**A newer backup asks for a newer Erevos**: a backup made by a newer Erevos than yours is refused, with nothing changed, and Erevos asks you to update to the latest version first. An Erevos from before 6.0.0 does not open backups from 6.0.0 on: update it, then restore. See [Backups](#backup).":
    "**Una copia más nueva pide un Erevos más nuevo**: una copia hecha por un Erevos más nuevo que el tuyo se rechaza, sin cambiar nada, y Erevos te pide que lo actualices primero a la última versión. Un Erevos anterior a la 6.0.0 no abre copias de la 6.0.0 en adelante: actualízalo y luego restaura. Mira [Copias de seguridad](#backup).",
  "**Shared into the Collection with no plain copy**: a photo or file another app shares with Erevos is encrypted as it comes in, before **Send to** opens, so on its way into the Collection it never lies unencrypted on the phone. It can be up to 4 GB there, and a large one shows how far it is encrypted, with **Cancel**; a chat still takes 100 MB at most. See [Collection](#collection).": "**Compartir en la Colección sin copia sin cifrar**: una foto o un archivo que otra app comparte con Erevos se cifra al llegar, antes de que se abra **Enviar a**, así que en su camino a la Colección nunca queda sin cifrar en el teléfono. Allí puede ser de hasta 4 GB; un chat sigue aceptando 100 MB como máximo. Con uno grande se ve cuánto se ha cifrado, con **Cancelar**. Mira [Colección](#collection).",
  "**See a file come from the WebDAV server**: a file of the Collection that is not on this device, as after a backup restored on a new phone, shows how much of it has come from the server, and **Cancel** stops it; what came stays, and the next time only the rest comes. Music, videos, PDFs and **Open with another app** fetch it first too, instead of failing. See [Collection](#collection).": "**Mira cómo llega un archivo del servidor WebDAV**: un archivo de la Colección que no está en este dispositivo, como tras una copia restaurada en un teléfono nuevo, muestra cuánto ha llegado ya del servidor, y **Cancelar** lo detiene; lo que llegó se queda, y la próxima vez solo llega el resto. La música, los vídeos, los PDF y **Abrir con otra app** también lo traen primero, en lugar de fallar. Mira [Colección](#collection).",
  "**Backups skip what is on the WebDAV server after a restart too**: that a Collection's copies on its server are complete is kept with it, so a backup made after Erevos starts again still leaves its pieces out, as long as no file was added or deleted since. **The connection works.** now shows in the colour of success, not of a warning. See [Collection](#collection).": "**Las copias de seguridad omiten lo que está en el servidor WebDAV también tras reiniciar**: que las copias de una Colección en su servidor están completas se guarda con ella, así que una copia de seguridad hecha después de que Erevos vuelva a arrancar sigue dejando fuera sus piezas, mientras no se haya añadido ni borrado ningún archivo desde entonces. **La conexión funciona.** se muestra ahora en el color del éxito, no de un aviso. Mira [Colección](#collection).",
  "**Notes from another app**: an app on the phone, as Fasouli for a payment that is coming, can ask to keep a note with its reminder in Chat with myself. Erevos asks you first, in the space you open. See [Getting started](#start).":
    "**Notas desde otra app**: una app del teléfono, como Fasouli para un pago que se acerca, puede pedir guardar una nota con su recordatorio en el Chat conmigo. Erevos te pregunta primero, en el espacio que abres. Ver [Primeros pasos](#start).",
  "**Payment requests**: another app, as Fasouli, can ask Erevos to send one to a contact: an amount and what it is for, as a card. They tap **Paid** once they paid, and **Mark in Fasouli** then marks it collected there. Erevos moves no money. See [Chat through a relay](#relay).":
    "**Solicitudes de pago**: otra app, como Fasouli, puede pedir a Erevos que envíe una a un contacto: un importe y para qué, como tarjeta. El contacto toca **Pagado** cuando paga, y **Marcar en Fasouli** la marca cobrada allí. Erevos no mueve dinero. Ver [Chatear a través de un relay](#relay).",
  "**Panic tells Fasouli too**: on Android, under Settings → Privacy and security → Panic button → **Tell other apps**, choose the apps Erevos tells as it wipes, as a panic app does: Fasouli then locks itself. Each asks you first. See [Panic button](#panic).":
    "**El pánico avisa también a Fasouli**: en Android, en Ajustes → Privacidad y seguridad → Botón de pánico → **Avisar a otras apps**, eliges las apps que Erevos avisa al borrar, como una app de pánico: Fasouli entonces se bloquea. Cada una te pregunta primero. Ver [Botón de pánico](#panic).",
  "**The Collection in the browser and on Sailfish OS**: the web app, on an iPhone's home screen too, and Erevos on Sailfish OS have the Collection now. A file is encrypted a piece at a time as it is read, and if the browser runs out of room nothing of it is kept. Photos, text, music and videos up to 256 MB open in memory only; a PDF is saved to be read elsewhere. See [Collection](#collection).":
    "**La Colección en el navegador y en Sailfish OS**: la app web, también en la pantalla de inicio de un iPhone, y Erevos en Sailfish OS tienen ahora la Colección. Un archivo se cifra trozo a trozo mientras se lee, y si el navegador se queda sin espacio no se guarda nada de él. Fotos, textos, música y vídeos de hasta 256 MB se abren solo en memoria; un PDF se guarda para leerlo en otro sitio. Consulta [Colección](#collection).",
  "**Large files saved from the Collection on Sailfish OS**: **Save to phone** writes a file of any size to Downloads a piece at a time, as the desktop app now does too, and when the disk has no room left Erevos says so and leaves nothing half-written. See [Collection](#collection).":
    "**Archivos grandes guardados desde la Colección en Sailfish OS**: **Guardar en el teléfono** escribe en Descargas un archivo de cualquier tamaño trozo a trozo, como ahora también la app de escritorio, y cuando el disco ya no tiene espacio, Erevos lo dice y no deja nada escrito a medias. Mira [Colección](#collection).",
  "**Sign in with Nextcloud**: a Collection's server and the backups' server can now be your Nextcloud, as LPHL's, the one Fasouli syncs with, without typing a password: tap **Sign in with Nextcloud**, sign in in the browser and grant access. Erevos gets an app password of its own and its own folder there, Erevos/Collection or Erevos/Backups. See [Collection](#collection).":
    "**Iniciar sesión con Nextcloud**: el servidor de una Colección y el de las copias de seguridad ya pueden ser tu Nextcloud, como el de LPHL, el que sincroniza Fasouli, sin escribir una contraseña: toca **Iniciar sesión con Nextcloud**, inicia sesión en el navegador y concede acceso. Erevos obtiene una contraseña de aplicación propia y su propia carpeta allí, Erevos/Collection o Erevos/Backups. Consulta [Colección](#collection).",
  "**Web app and Sailfish OS fixes from the review**: in the web app, each space that turns notifications on gets a push address of its own, from a service worker of its own, so a relay is never given another space's address and it never ties two spaces together; the browser's settings then list one service worker for each such space. A check for a new release that was slow to answer no longer brings back the release just replaced. On Sailfish OS, another app on the phone can no longer make Erevos hold on to memory, nor give orders to the helper that waits at the relay while Erevos is out of sight. See [On an iPhone](#iphone).":
    "**Arreglos de la revisión en la app web y en Sailfish OS**: en la app web, cada espacio que activa las notificaciones recibe su propia dirección push, de su propio service worker, así que un relay nunca recibe la dirección de otro espacio y esta nunca une dos espacios; los ajustes del navegador muestran entonces un service worker por cada uno de esos espacios. Una búsqueda de versión nueva que tardó en responder ya no trae de vuelta la versión recién reemplazada. En Sailfish OS, otra app del teléfono ya no puede hacer que Erevos retenga memoria, ni dar órdenes al ayudante que espera en el relay mientras Erevos no está a la vista. Ver [En un iPhone](#iphone).",
  "**Photos of the Collection one after the other**: in a photo, the arrows (on a phone too, while the bars show) or a swipe go to the next or the one before, and **Slideshow** shows them by themselves, one every 4 seconds, till a tap. On a computer, in a browser and on Sailfish OS a photo opens again instead of staying at **Opening the photo…**. See [Collection](#collection).": "**Las fotos de la Colección una tras otra**: en una foto, las flechas (también en el teléfono, mientras se ven las barras) o deslizar llevan a la siguiente o a la anterior, y **Presentación** las muestra solas, una cada 4 segundos, hasta un toque. En el ordenador, en un navegador y en Sailfish OS una foto vuelve a abrirse en lugar de quedarse en **Abriendo la foto…**. Mira [Colección](#collection).",
  "**Reminders that come again**: a note Fasouli keeps for a scheduled payment now reminds you each time it is due, every month or as the payment repeats, and shows how often. Once you see it, it moves to its next time. See [Getting started](#start).":
    "**Recordatorios que vuelven**: una nota que Fasouli guarda para un pago programado ahora te avisa cada vez que vence, cada mes o según se repita el pago, y muestra cada cuánto. En cuanto la ves, pasa a su próxima vez. Consulta [Getting started](#start).",
  "**Who is online on Matrix and XMPP**: under a contact's name it says, as their server does, **Online**, **Away** or **Do not disturb**, with the words they set, or when they were last online, and their picture in the chat list has a green dot. On Matrix, Erevos no longer says you are online unless you turn on **Say when I am online** on the Matrix screen. See [Matrix](#matrix).":
    "**Quién está en línea en Matrix y XMPP**: bajo el nombre de un contacto dice, como lo dice su servidor, **En línea**, **Ausente** o **No molestar**, con las palabras que puso, o cuándo estuvo en línea por última vez, y su foto en la lista de chats tiene un punto verde. En Matrix, Erevos ya no dice que estás en línea salvo que actives **Avisar cuando estoy en línea** en la pantalla de Matrix. Ver [Matrix](#matrix).",
  "**Link a computer with one tap**: on the computer, **Linked devices** now shows a small code at once. Scan it with the phone and tap **Link**: the phone gives the computer what it needs through Nostr, end-to-end encrypted, and nothing has to be typed or compared. If Nostr cannot be reached, **Link another way** keeps the old way. See [Linked devices](#devices).":
    "**Vincular un ordenador con un toque**: en el ordenador, **Dispositivos vinculados** muestra ahora al instante un código pequeño. Escanéalo con el teléfono y toca **Vincular**: el teléfono da al ordenador lo que necesita a través de Nostr, cifrado de extremo a extremo, y no hay que escribir ni comparar nada. Si no se llega a Nostr, **Vincular de otra forma** mantiene el modo de antes. Ver [Dispositivos vinculados](#devices).",
  '**Choose the name others see**: under Settings → Privacy and security → **My name**, give this space a name that your contacts and your private groups see instead of a code, always encrypted. Hidden chats have a name of their own, in their settings, empty at first. See [Chat through a relay](#relay).':
    '**Elige el nombre que ven los demás**: en Ajustes → Privacidad y seguridad → **Mi nombre**, da a este espacio un nombre que tus contactos y tus grupos privados ven en lugar de un código, siempre cifrado. Los chats ocultos tienen un nombre propio, en sus ajustes, vacío al principio. Ver [Chatear a través de un relay](#relay).',
  "**Folders in Chat with myself**: notes, photos, files and voice messages can now go in folders. The folder button at the top makes one; its tab above the notes then shows only what is in it, and what you write while it is chosen goes into it. Holding a note offers **Move to a folder**; holding a folder's tab renames or deletes it, its notes staying. The folders go to your linked devices with the notes. See [Getting started](#start).":
    "**Carpetas en Chat conmigo**: las notas, fotos, archivos y mensajes de voz ahora pueden ir en carpetas. El botón de carpeta de arriba crea una; su pestaña sobre las notas muestra entonces solo lo que hay en ella, y lo que escribes mientras está elegida entra en ella. Mantener pulsada una nota ofrece **Mover a una carpeta**; mantener pulsada la pestaña de una carpeta la renombra o la borra, y sus notas se quedan. Las carpetas van a tus dispositivos vinculados con las notas. Mira [Primeros pasos](#start).",
  "**The battery mode And sleep spares more**: each time it wakes the phone to look, about once a minute, the phone now sleeps again within a second or two when nothing came, not after 25 seconds.":
    "**El modo de batería «Y el sueño» ahorra más**: cada vez que despierta al teléfono para mirar, más o menos una vez por minuto, el teléfono ahora vuelve a dormir en uno o dos segundos si no ha llegado nada, no después de 25 segundos.",
  "**Messages come at once while Erevos shows**: Erevos now waits at your relay with the connection open also while it is on the screen, so a message or a call comes the moment it is sent, not at the next look every 3 seconds, and the phone's radio rests in between.":
    "**Los mensajes llegan al instante mientras Erevos se ve**: Erevos ahora espera en tu relay con la conexión abierta también mientras está en pantalla, así que un mensaje o una llamada llega en el momento en que se envía, no en la siguiente mirada cada 3 segundos, y la radio del teléfono descansa entretanto.",
  "**A new battery mode, And light sleep**: under Settings → Notifications → In the background. The phone may sleep, and what comes to your relay wakes it, so messages and calls still come at once where the network and Android allow it. It is new: if messages come late with it, choose another.":
    "**Un nuevo modo de batería, «Y el sueño ligero»**: en Ajustes → Notificaciones → En segundo plano. El teléfono puede dormir, y lo que llega a tu relay lo despierta, así que los mensajes y las llamadas siguen llegando al instante donde la red y Android lo permiten. Es nuevo: si con él los mensajes llegan tarde, elige otro.",
  "**Chats are saved faster**: a message that comes, is read or is deleted is saved by looking only at its own chat, which shows most with many chats or after a large import. The chat screen is no longer drawn again every 5 seconds.":
    "**Los chats se guardan más rápido**: un mensaje que llega, se lee o se borra se guarda mirando solo su propio chat, lo que más se nota con muchos chats o tras una importación grande. La pantalla del chat ya no se vuelve a dibujar cada 5 segundos.",
  "**Large imports write less**: the note of the files an import is still writing is kept in small parts, not written whole for every file.":
    "**Las importaciones grandes escriben menos**: la nota de los archivos que una importación aún está escribiendo se guarda en partes pequeñas, no se escribe entera por cada archivo.",
  "**A text no longer waits for slow Nostr relays**: with Nostr on, a text waited for a Nostr relay to say it took it, up to 20 seconds when none answered, before it went through the relay. Now, when none says so within 4 seconds, it goes through the relay as well at once.":
    "**Un mensaje ya no espera a los relays de Nostr lentos**: con Nostr activado, un mensaje esperaba a que un relay de Nostr dijera que lo había tomado, hasta 20 segundos cuando ninguno respondía, antes de ir por el relay. Ahora, si ninguno lo dice en 4 segundos, va también por el relay al momento.",
  "**Voice messages in Opus**: on Android 10 and later, in the web app and on a computer, voice messages are recorded as Ogg/Opus, as Telegram and Element send them: as clear as before at half the size, about 240 KB a minute. Every Erevos plays them, Safari on an older iPhone too. See [Chat through a relay](#relay).":
    "**Mensajes de voz en Opus**: en Android 10 y posteriores, en la app web y en un ordenador, los mensajes de voz se graban como Ogg/Opus, como los envían Telegram y Element: igual de claros que antes con la mitad de tamaño, unos 240 KB por minuto. Todos los Erevos los reproducen, también Safari en un iPhone antiguo. Mira [Chatear a través de un relay](#relay).",
  "**Mark all as read**: the ⋮ menu of the chats has it for the part of the list you are on, all messages, SMS, Erevos, Matrix, XMPP or Nostr, and the Matrix, XMPP and Nostr screens have it for their chats. It asks first, then reads each chat as opening it would: those who wrote are told as then. See [Getting started](#start).":
    "**Marcar todo como leído**: el menú ⋮ de los chats lo tiene para la parte de la lista en la que estás, todos los mensajes, SMS, Erevos, Matrix, XMPP o Nostr, y las pantallas de Matrix, XMPP y Nostr lo tienen para sus chats. Pregunta primero, y luego lee cada chat como lo haría abrirlo: quienes escribieron lo saben como entonces. Mira [Primeros pasos](#start).",
  "**Answer with video, or voice only**: an incoming call, Erevos, group, XMPP or Matrix, now offers both. You can add video to an Erevos voice call while it goes on, and Flip on a computer moves to your next camera. See [Chat through a relay](#relay).":
    "**Responder con vídeo o solo con voz**: una llamada entrante, de Erevos, de grupo, de XMPP o de Matrix, ofrece ahora las dos cosas. Puedes añadir vídeo a una llamada de voz de Erevos mientras dura, y Girar en un ordenador pasa a tu siguiente cámara. Mira [Chatear a través de un relay](#relay).",
  "**Voice messages, places, contact cards and pins in SMS**: in an SMS conversation, hold the microphone to send a voice message by MMS. **+** also sends where you are, as an SMS with a map link any phone opens, and a contact from your phone as a contact card. Voice messages, contact cards and map links you receive show as such, to play, save or open. Hold a message down to **Pin for me**, kept only on this phone, or **Select** several to copy, forward or delete them together. See [SMS](#sms).":
    "**Mensajes de voz, lugares, tarjetas de contacto y fijados en SMS**: en una conversación de SMS, mantén pulsado el micrófono para enviar un mensaje de voz por MMS. **+** también envía dónde estás, como un SMS con un enlace de mapa que abre cualquier teléfono, y un contacto de tu teléfono como tarjeta de contacto. Los mensajes de voz, tarjetas de contacto y enlaces de mapa que recibes se ven como tales, para reproducir, guardar o abrir. Mantén pulsado un mensaje para **Fijar solo para mí**, guardado solo en este teléfono, o **Seleccionar** varios para copiarlos, reenviarlos o eliminarlos juntos. Mira [SMS](#sms).",
  "**More in XMPP chats**: voice messages from other XMPP apps now play in the chat and show how long they are; **Sticker** sends your own photo stickers as photos, encrypted as the chat is; groups show who is **owner** or **admin**, and the owner can set the group's **Description**; **Forward** sends one or several messages to another XMPP chat; tapping a quoted reply goes to the message; **Pin for me** keeps a message at the top on this phone only; and **Select** chooses several messages to copy, forward or delete. See [XMPP](#xmpp).":
    "**Más en los chats XMPP**: los mensajes de voz de otras apps XMPP ahora se reproducen en el chat y muestran su duración; **Sticker** envía tus propios stickers hechos con fotos como fotos, cifradas como el chat; los grupos muestran quién es **propietario** o **admin**, y el propietario puede poner la **Descripción** del grupo; **Reenviar** envía uno o varios mensajes a otro chat XMPP; tocar una respuesta citada va al mensaje; **Fijar solo para mí** mantiene un mensaje arriba solo en este teléfono; y **Seleccionar** elige varios mensajes para copiar, reenviar o eliminar. Mira [XMPP](#xmpp).",
  "**More in Nostr chats**: tap a reaction to add it or take yours back, pin messages for yourself, select several to copy, forward or delete, send your own photo stickers, and see, vote on and make polls in the Public feed. See [Chats with other Nostr apps](#nostr-chats).":
    "**Más en los chats de Nostr**: toca una reacción para añadirla o retirar la tuya, fija mensajes para ti, elige varios para copiar, reenviar o eliminar, envía tus propios stickers hechos con fotos, y mira, vota y crea encuestas en el feed público. Mira [Chats con otras apps de Nostr](#nostr-chats).",
  "**Matrix groups and stickers**: in a Matrix group, **Members** shows who is in it and who is an admin or moderator, and lets admins rename it, set its subject, make admins, and take people out or bar them. Stickers sent from Element and other Matrix apps now show, and your own stickers made from photos can be sent. **New chat** can find people by name, and **Select** in a message's menu chooses several messages to copy, forward or delete. See [Matrix](#matrix).":
    "**Grupos y stickers en Matrix**: en un grupo de Matrix, **Miembros** muestra quién está y quién es admin o moderador, y deja que los admins lo renombren, pongan su asunto, hagan admins, y expulsen o veten a personas. Los stickers enviados desde Element y otras apps de Matrix ahora se ven, y se pueden enviar tus propios stickers hechos con fotos. **Chat nuevo** puede encontrar personas por nombre, y **Seleccionar** en el menú de un mensaje elige varios mensajes para copiar, reenviar o eliminar. Mira [Matrix](#matrix).",
  "**More in your chats and groups**: choose several messages to copy, forward or delete at once; end your polls; reply in threads in groups; give a group a description; and send a contact from your phone as a card. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Más en tus chats y grupos**: elige varios mensajes para copiarlos, reenviarlos o eliminarlos a la vez; termina tus encuestas; responde en hilos en los grupos; da una descripción a un grupo; y envía un contacto de tu teléfono como tarjeta. Mira [Chatear a través de un relay](#relay) y [Chats de grupo](#groups).",
  "**Ticks**: a text the other phone had, and read, before it showed as sent here (through a slow Nostr relay) now shows as read, not with one tick. Ticks from a contact on another relay no longer stop, and a text that reaches a phone while Erevos is in the background there gets its second tick at that phone's next check.":
    "**Ticks**: un texto que el otro teléfono ya tenía y había leído antes de que aquí se viera como enviado (por un relay de Nostr lento) ahora se ve como leído, no con un solo tick. Los ticks de un contacto en otro relay ya no se detienen, y un texto que llega a un teléfono mientras Erevos está allí en segundo plano recibe su segundo tick en la siguiente comprobación de ese teléfono.",
  "**Stickers on other networks**: a built-in sticker sent on Matrix, XMPP, Nostr or by MMS arrives as its picture, made on your device, its words in your language. See [Chat through a relay](#relay).":
    "**Stickers en otras redes**: un sticker de los que trae Erevos enviado por Matrix, XMPP, Nostr o por MMS llega como su imagen, hecha en tu dispositivo, con sus palabras en tu idioma. Consulta [Chatear a través de un relay](#relay).",
  "**One button for all your services**: under the search on the home screen, one button says which service shows, with the messages not read and any service not connected now. Tap it for a window with every service as a card, each with its own number and a dot for its connection; **Add** turns more on, and holding a card moves it or hides it. With no search, the chats with messages not read come first, under **Unread**, then the rest under **Recent**. See [Getting started](#start).":
    "**Un botón para todos tus servicios**: bajo la búsqueda de la pantalla de inicio, un botón dice qué servicio se ve, con los mensajes sin leer y cualquier servicio que ahora no esté conectado. Tócalo para una ventana con cada servicio como tarjeta, cada una con su número y un punto para su conexión; **Añadir** activa más, y mantener pulsada una tarjeta la mueve o la oculta. Sin búsqueda, primero van los chats con mensajes sin leer, en **No leídos**, y luego los demás en **Recientes**. Mira [Primeros pasos](#start).",
  "**Share an imported chat with the other person**: a Telegram, WhatsApp or Viber chat that goes on with an Erevos contact can now go to them too, from the chat's **Details** or **Settings** → **Data and devices** → **Imported chats**: every message, photo, video, voice message and file, end-to-end encrypted, to them alone, whatever its size. Their Erevos keeps the messages at once and shows them ahead of the new messages, the sides swapped; the files follow in rounds through your relay while both phones run Erevos, each up to 4 GB, as large as an import now keeps. See [Imported chats](#import).":
    "**Comparte un chat importado con la otra persona**: un chat de Telegram, WhatsApp o Viber que continúa con un contacto de Erevos ahora puede ir también a él, desde los **Detalles** del chat o desde **Ajustes** → **Datos y dispositivos** → **Chats importados**: cada mensaje, foto, vídeo, mensaje de voz y archivo, cifrado de extremo a extremo, solo para él, sea cual sea su tamaño. Su Erevos guarda los mensajes enseguida y los muestra antes de los mensajes nuevos, con los lados cambiados; los archivos siguen por rondas a través de tu relay mientras Erevos esté en marcha en los dos teléfonos, cada uno de hasta 4 GB, tan grande como ahora guarda una importación. Ver [Chats importados](#import).",
  "**Tor for your XMPP account, and per chat**: on Android, the XMPP screen, and the one before signing in, chooses **Off** (the default), **As the space** or **Always through Tor** for the account: its connection, the look for its server and its files, never straight when it must not. **Through Tor** under any XMPP chat or group, off by default, sends the whole account only through Tor while on, as one connection carries all its chats. Calls do not go through Tor. Before you send while the account does not go through Tor, before a call and before a file from another server, Erevos says once that your internet address can be seen, and how not to. See [XMPP](#xmpp).":
    "**Tor para tu cuenta de XMPP, y por chat**: en Android, la pantalla de XMPP, y la de antes de iniciar sesión, elige para la cuenta **Desactivado** (por defecto), **Como el espacio** o **Siempre por Tor**: su conexión, la búsqueda de su servidor y sus archivos, nunca directo cuando no debe. **Por Tor** bajo cualquier chat o grupo de XMPP, desactivado por defecto, manda toda la cuenta solo por Tor mientras está activado, ya que una conexión lleva todos sus chats. Las llamadas no van por Tor. Antes de que envíes mientras la cuenta no va por Tor, antes de una llamada y antes de un archivo de otro servidor, Erevos dice una vez que tu dirección de internet puede verse, y cómo evitarlo. Mira [XMPP](#xmpp).",
  "**Tor for Messenger and Signal, and per chat**: in Erevos+, the Messenger and Signal screens, and the ones before signing in, choose **Off** (the default), **As the space** or **Always through Tor** for the account. With it, everything of the account goes through Tor, its pictures and files too, and Messenger's sign-in page and Signal's registering, captcha and linking as well: never straight when it must not. **Through Tor** under any of their chats, off by default, sends the whole account only through Tor while on, as each has one connection. Calls do not go through Tor.":
    "**Tor para Messenger y Signal, y por chat**: en Erevos+, las pantallas de Messenger y Signal, también antes de iniciar sesión, eligen para la cuenta **Desactivado** (por defecto), **Como el espacio** o **Siempre por Tor**. Con ello, todo lo de la cuenta va por Tor, también sus fotos y archivos, y además la página de inicio de sesión de Messenger y el registro, el captcha y la vinculación de Signal: nunca directo cuando no debe. **Por Tor** en cualquiera de sus chats, desactivado por defecto, envía toda la cuenta solo por Tor mientras esté activado, ya que cada una tiene una conexión. Las llamadas no van por Tor.",
  "**Telegram: Tor as every account, and per chat**: on Android, **Tor for this Telegram account**, in Telegram's settings and before signing in, has **Off** (the default), **As the space** and **Always through Tor**, as every account of another network. With Always, or while the space sends Everything through Tor, Telegram is reached only through Tor, signing in too, and never straight, not even when Tor cannot connect. **Through Tor** in a Telegram chat's info sends that chat only through Tor, and with it the whole account, which has one connection. Calls do not go through Tor. See [Telegram (ErevosGram)](#telegram).":
    "**Telegram: Tor como en toda cuenta, y por chat**: en Android, **Tor para esta cuenta de Telegram**, en los ajustes de Telegram y antes de iniciar sesión, tiene **Desactivado** (lo de partida), **Como el espacio** y **Siempre por Tor**, como toda cuenta de otra red. Con Siempre, o mientras el espacio envía Todo por Tor, Telegram se alcanza solo por Tor, también al iniciar sesión, y nunca directo, ni siquiera cuando Tor no puede conectar. **Por Tor** en la información de un chat de Telegram lleva ese chat solo por Tor, y con él toda la cuenta, que tiene una sola conexión. Las llamadas no van por Tor. Consulta [Telegram (ErevosGram)](#telegram).",
  "**Nostr: Tor as every account, and per chat**: on Android, the **Nostr chats** screen, before a key is made or brought too, has **Off** (the default, also for keys from before), **As the space** and **Always through Tor** for the account: its relays, look-ups and file servers, never straight when it must not (Always, or the space's Everything). **Through Tor** at the foot of a Nostr chat, off by default, sends that chat alone only through Tor, on circuits of its own, whatever the account says; what comes to you follows the account. See [Chats with other Nostr apps](#nostr-chats).":
    "**Nostr: Tor como en cada cuenta, y por chat**: en Android, la pantalla **Chats de Nostr**, también antes de hacer o traer una clave, tiene **Desactivado** (lo predeterminado, también para las claves de antes), **Como el espacio** y **Siempre por Tor** para la cuenta: sus relays, búsquedas y servidores de archivos, nunca directo cuando no debe (Siempre, o el Todo del espacio). **Por Tor** al pie de un chat de Nostr, desactivado por defecto, envía solo ese chat únicamente por Tor, en circuitos propios, diga lo que diga la cuenta; lo que te llega sigue a la cuenta. Mira [Chats con otras apps de Nostr](#nostr-chats).",
  "**Telegram warns before your internet address can be seen**: once in each Telegram chat, before the first message, file, sticker, voice message, poll or forward while the account does not go through Tor, with **Through Tor** for that chat to fix it, **Guide** or **Go on**; before every Telegram call, made or answered, as calls never go through Tor; and before joining a group or channel by its link. See [Who sees your internet address](#ip).":
    "**Telegram avisa antes de que se pueda ver tu dirección de internet**: una vez en cada chat de Telegram, antes del primer mensaje, archivo, sticker, mensaje de voz, encuesta o reenvío mientras la cuenta no va por Tor, con **Por Tor** para ese chat como arreglo, **Guía** o **Seguir**; antes de cada llamada de Telegram, hecha o respondida, ya que las llamadas nunca van por Tor; y antes de unirte a un grupo o canal por su enlace. Consulta [Quién ve tu dirección de internet](#ip).",
  "**Erevos or Erevos+, and betas, in Updates**: on Android, **Updates** now chooses the next update: **Erevos** or **Erevos+**, moving from one to the other with everything kept, and **Beta versions**, to join the betas, which come out first for trying, or leave them. See [Erevos or Erevos+, and betas](#updates).": "**Erevos o Erevos+, y betas, en Actualizaciones**: en Android, **Actualizaciones** elige ahora la próxima actualización: **Erevos** o **Erevos+**, pasando de uno a otro sin perder nada, y **Versiones beta**, para unirte a las betas, que salen antes para probar, o salir de ellas. Consulta [Erevos o Erevos+, y betas](#updates).",
  "**Matrix, XMPP and Nostr chats are in Erevos+**: Erevos now has its own chats, the Phone, SMS and the Collection, and Erevos+ has Matrix, XMPP and the chats with other Nostr apps besides. An account you had on them stays on the phone, encrypted, and Erevos says so once; choose **Erevos+** in **Updates** to have it again. Erevos's own messages still go through Nostr relays when no relay of yours takes them. See [Erevos or Erevos+, and betas](#updates).": "**Los chats de Matrix, XMPP y Nostr están en Erevos+**: Erevos tiene ahora sus propios chats, el Teléfono, los SMS y la Colección, y Erevos+ tiene además Matrix, XMPP y los chats con otras apps de Nostr. Una cuenta que tenías en ellos se queda en el teléfono, cifrada, y Erevos lo dice una vez; elige **Erevos+** en **Actualizaciones** para tenerla de nuevo. Los mensajes propios de Erevos siguen pasando por relays de Nostr cuando ninguno de tus relays los acepta. Ver [Erevos o Erevos+, y betas](#updates).",
  "**Radio and TV through Tor**: the Collection's settings on Android have **Play through Tor**, off unless you turn it on. On, stations and channels play only through Tor, so they do not see your IP address; TV may stall for a moment. Off, Erevos says before the first one plays that its server sees your IP address, with a button that turns it on. Before, they always played straight. See [Collection](#collection).": "**Radio y TV por Tor**: los ajustes de la Colección en Android tienen **Reproducir por Tor**, desactivado salvo que lo actives. Activado, las emisoras y los canales se reproducen solo por Tor, así que no ven tu dirección IP; la TV puede atascarse un momento. Desactivado, Erevos dice antes de que suene el primero que su servidor ve tu dirección IP, con un botón que lo activa. Antes se reproducían siempre directo. Mira [Colección](#collection).",
  "**A chat no longer freezes before a message sent for later shows**: a message your contact sends with **Send later** can come before its time, and shows only then. Until then its chat was marked read again and again without end, so it could stop answering: **⋮** opened nothing and **Back** did not leave it until Erevos was closed. Now such a message is read once it shows. See [Chat through a relay](#relay).": "**Un chat ya no se congela antes de que aparezca un mensaje enviado para más tarde**: un mensaje que tu contacto envía con **Enviar más tarde** puede llegar antes de su hora, y solo aparece entonces. Hasta entonces su chat se marcaba como leído una y otra vez sin fin, así que podía dejar de responder: **⋮** no abría nada y **Atrás** no salía de él hasta cerrar Erevos. Ahora un mensaje así se lee en cuanto aparece. Ver [Chatear a través de un relay](#relay).",
  "**Choose the part Erevos opens on**: under **All services**, hold any card, **All messages** too, and choose **Opens first**. Erevos's icon in the launcher, and Erevos started with nothing else to open, then open on it; with none chosen, or the chosen one hidden, on **All messages**. Before, the icon always opened the Erevos chats. The widget's buttons still open their own. See [Getting started](#start).": "**Elige dónde se abre Erevos**: en **Todos los servicios**, mantén pulsada cualquier tarjeta, también **Todos**, y elige **Abre primero**. El icono de Erevos en el launcher, y Erevos al iniciarse sin nada más que abrir, se abren entonces ahí; sin ninguna elegida, o con la elegida oculta, en **Todos**. Antes, el icono abría siempre los chats de Erevos. Los botones del widget siguen abriendo los suyos. Ver [Primeros pasos](#start).",
  "**Asked before strangers reach this phone**: an Erevos invite that comes by SMS is answered by itself only from a number in your contacts or one you have written to; from any other, Erevos asks first, as the sender of an SMS can be made up. A contact's invite to a place on their relay now says first that their relay sees your IP address, and is taken only if you go on. See [Who sees your internet address](#ip).": "**Se pregunta antes de que extraños lleguen a este teléfono**: una invitación de Erevos que llega por SMS se responde por sí sola solo desde un número de tus contactos o uno al que has escrito; desde cualquier otro, Erevos pregunta primero, porque el remitente de un SMS puede ser inventado. La invitación de un contacto a un lugar en su relay ahora dice primero que su relay ve tu dirección IP, y se acepta solo si sigues adelante. Ver [Quién ve tu dirección de internet](#ip).",
  "**Notices in your language**: Android's own notices and screens, new versions, reminders, birthdays, calls, SMS codes and the contact picker, now speak German, Spanish, French, Italian, Portuguese and Serbo-Croatian too, not only Greek and English. Older Greek subtitles, not saved as UTF-8, now show as Greek on the computer. See [Collection](#collection).": "**Avisos en tu idioma**: los avisos y pantallas propios de Android, las versiones nuevas, los recordatorios, los cumpleaños, las llamadas, los códigos de SMS y el selector de contactos ahora hablan también alemán, español, francés, italiano, portugués y serbocroata, no solo griego e inglés. Los subtítulos griegos antiguos, no guardados en UTF-8, ahora se ven como griego en el ordenador. Ver [Colección](#collection).",
  "**Video calls on the computer, and the calculator after a wipe**: a video call started or answered on the computer now opens its camera. With the calculator in place of Erevos's icon, once Erevos is wiped by the panic password or **Clear storage**, the calculator opens Erevos as new and gives Erevos's icon back, where before no code opened it any more. See [Appearance](#appearance).": "**Videollamadas en el ordenador, y la calculadora tras un borrado**: una videollamada iniciada o respondida en el ordenador ahora abre su cámara. Con la calculadora en lugar del icono de Erevos, una vez borrado Erevos con la contraseña de pánico o con **Borrar almacenamiento**, la calculadora abre Erevos como nuevo y devuelve el icono de Erevos, donde antes ningún código lo abría ya. Ver [Apariencia](#appearance).",
  "**Last seen starts off**: in a new space, **Last seen** is now off until you turn it on, so no contact sees when you last had Erevos open, and you see no one's either. A space you already have keeps it as it was. See [Chat through a relay](#relay).": "**Última vez empieza desactivada**: en un espacio nuevo, **Última vez** ahora está desactivada hasta que la actives, así que ningún contacto ve cuándo tuviste Erevos abierto por última vez, y tú tampoco ves la de nadie. Un espacio que ya tienes la conserva como estaba. Ver [Chatear a través de un relay](#relay).",
  "**A chat with a big file no longer closes Erevos**: on Android, opening a chat that held a large file, or one shared in many pieces, could close Erevos at once. Now it opens. See [Chat through a relay](#relay).": "**Un chat con un archivo grande ya no cierra Erevos**: en Android, abrir un chat con un archivo grande, o uno compartido en muchas partes, podía cerrar Erevos al instante. Ahora se abre. Mira [Chatear a través de un relay](#relay).",
  "**A hidden service stays quiet**: a service you hide in the **Services** window, Messenger, Matrix, SMS or any other, no longer sends notifications or counts on Erevos's icon, as a muted chat. It stays connected and tells again once you show it. Telegram, whose folders can stand on home of their own, keeps telling. See [Getting started](#start).": "**Un servicio oculto se queda en silencio**: un servicio que ocultas en la ventana **Servicios**, Messenger, Matrix, SMS u otro, ya no envía notificaciones ni cuenta en el número del icono de Erevos, como un chat silenciado. Sigue conectado y vuelve a avisar en cuanto lo muestras. Telegram, cuyas carpetas pueden estar en el inicio como servicios propios, sigue avisando. Mira [Getting started](#start).",
  "**Screenshots in hidden chats too, if you want**: hidden chats now follow **Screenshots** in **Privacy and security**: on, as it starts, they stay out of screenshots and the recent apps; turned off, screenshots work in them as in the other chats. Before, hidden chats always kept them out. See [Hidden chats](#hidden).": "**Capturas también en los chats ocultos, si quieres**: los chats ocultos siguen ahora **Capturas de pantalla** en **Privacidad y seguridad**: activado, como empieza, quedan fuera de las capturas y de las apps recientes; desactivado, las capturas funcionan en ellos como en los demás chats. Antes, los chats ocultos siempre las bloqueaban. Mira [Chats ocultos](#hidden).",
  "**Messenger signs in on facebook.com, and opens Facebook**: in Erevos+, Messenger now signs in on Facebook's own page. **Open Facebook** on the Messenger screen shows Facebook itself with the same sign-in: its Messenger links come back to Erevos's chats, and other links open in your browser without Facebook's tracking marks and never through Tor, so the site sees your internet address. An account signed in on messenger.com before signs out and in again once to open Facebook.":
    "**Messenger inicia sesión en facebook.com y abre Facebook**: en Erevos+, Messenger ahora inicia sesión en la propia página de Facebook. **Abrir Facebook** en la pantalla de Messenger muestra Facebook mismo con la misma sesión: sus enlaces de Messenger vuelven a los chats de Erevos, y los demás enlaces se abren en tu navegador sin las marcas de rastreo de Facebook y nunca a través de Tor, así que el sitio ve tu dirección de internet. Una cuenta que inició sesión antes en messenger.com cierra sesión y vuelve a iniciarla una vez para abrir Facebook.",
  "**Messenger, Signal and Session chats send more, and stay read**: in Erevos+, **+** in their chats sends a photo from your photos or the camera, a file or a sticker, and the microphone records a voice message. Your own messages show their words, where before some came empty; tapping a person with no Messenger chat yet opens a new one; and chats you mark read no longer come back unread.":
    "**Los chats de Messenger, Signal y Session envían más y siguen leídos**: en Erevos+, **+** en sus chats envía una foto de tus fotos o de la cámara, un archivo o un sticker, y el micrófono graba un mensaje de voz. Tus propios mensajes muestran sus palabras, donde antes algunos llegaban vacíos; tocar a una persona sin chat de Messenger abre uno nuevo; y los chats que marcas como leídos ya no vuelven a quedar sin leer.",
  "**Every copy carries its licences**: the Android app, the computer and Sailfish apps and the web app now carry the file NOTICES.txt, with Erevos's licence, AUTHORS.md and every package Erevos is built from, each with its licence text. See [Licence](#licence).": "**Cada copia lleva sus licencias**: la app de Android, las apps de ordenador y Sailfish y la app web llevan ahora el archivo NOTICES.txt, con la licencia de Erevos, AUTHORS.md y cada paquete con el que está hecho Erevos, cada uno con el texto de su licencia. Ver [Licencia](#licence).",
  "**A ready list of radio stations**: **Add a station** in the Collection's Radio now adds a country's most listened stations from Radio Browser at once, up to 100, with **Add the stations of this country**; the country is the phone's, and **Change** picks another. See [Collection](#collection).": "**Una lista ya hecha de emisoras**: **Añadir una emisora** en la Radio de la Colección añade ahora de una vez las emisoras más escuchadas de un país desde Radio Browser, hasta 100, con **Añadir las emisoras de este país**; el país es el del teléfono, y **Cambiar** elige otro. Mira [Colección](#collection).",
  "**A new look to start with**: Erevos, newly installed, starts in Glass (Panes), Modernist, System, My color in sky blue, the phone's letters and square messages. A look you chose before stays as it was. See [Appearance](#appearance).": "**Un aspecto nuevo para empezar**: Erevos recién instalado empieza con Glass (Paneles), Modernist, Sistema, Mi color en azul cielo, la letra del teléfono y mensajes cuadrados. Un aspecto elegido antes se queda como estaba. Mira [Aspecto](#appearance).",
  "**Modules names only what Erevos has**: under **Settings** → **General**, **Modules** no longer lists Nostr, Matrix and XMPP, which are in Erevos+.": "**Módulos nombra solo lo que tiene Erevos**: en **Ajustes** → **General**, **Módulos** ya no nombra Nostr, Matrix y XMPP, que están en Erevos+.",
  "**The guide tells only of what Erevos has**: in Erevos, the user guide no longer speaks of Matrix, XMPP and the chats with other Nostr apps, which are in Erevos+. See [Erevos or Erevos+, and betas](#updates).": "**La guía cuenta solo lo que tiene Erevos**: en Erevos, la guía ya no habla de Matrix, XMPP ni de los chats con otras apps de Nostr, que están en Erevos+. Mira [Erevos o Erevos+, y betas](#updates).",
  "**Meeting someone in one tap**: **New chat** now starts with two big buttons, **Scan their QR code** and **Show your QR code**; one of you scanning the other is enough, and the rest is under them. See [Chat through a relay](#relay).": "**Conocer a alguien con un toque**: **Chat nuevo** empieza ahora con dos botones grandes, **Escanear su código QR** y **Mostrar tu código QR**; basta con que uno de los dos escanee al otro, y lo demás está debajo. Consulta [Chatear a través de un relay](#relay).",
  "**The panic button, found at once**: it is first, in red, in the **⋯** menu of the home screen, and holding down the lock at the top of the home screen opens it. See [Panic button](#panic).": "**El botón de pánico, al instante**: está el primero, en rojo, en el menú **⋯** de la pantalla de inicio, y mantener pulsado el candado arriba en la pantalla de inicio lo abre. Consulta [Botón de pánico](#panic).",
  "**New chat looks the same every time**: the two big buttons are always at the top; **How you connect now** shows only while something is missing, and says it in plain words; **Your contact link** and **Invite someone** are rows, with no second QR code button. See [Chat through a relay](#relay).": "**El chat nuevo se ve igual siempre**: los dos botones grandes están siempre arriba; **Cómo te conectas ahora** solo aparece mientras falta algo, y lo dice con palabras sencillas; **Tu enlace de contacto** e **Invitar a alguien** son filas, sin un segundo botón de código QR. Consulta [Chatear a través de un relay](#relay).",
  "**One scan is all**: where your relay lets your phone invite, **Show your QR code** shows an invite for one person, so a phone new to Erevos joins your relay by itself as it scans it, typing nothing, and you are contacts at once; for someone else, tap **New QR code**. And with a relay, its queue is made by itself: **Create my relay queue** is there only to try again, should that fail. See [Chat through a relay](#relay).": "**Un solo escaneo basta**: donde tu relay deja que tu teléfono invite, **Mostrar tu código QR** muestra una invitación para una persona, así que un teléfono nuevo en Erevos se une solo a tu relay al escanearla, sin escribir nada, y sois contactos al instante; para otra persona, toca **Nuevo código QR**. Y con un relay, su cola se crea sola: **Crear mi cola en el relay** queda solo para volver a intentarlo, si eso falla. Consulta [Chatear a través de un relay](#relay).",
  "**Video calls take about half the data**: a video call over the internet goes through the call relay, so that neither side sees the other's address; its picture is now held to 1 Mbps, which on a phone looks much the same. A call on the same network is not held back.": "**Las videollamadas gastan casi la mitad de datos**: una videollamada por internet pasa por el relay de llamadas, para que ninguna parte vea la dirección de la otra; su imagen ahora se limita a 1 Mbps, que en un teléfono se ve casi igual. Una llamada en la misma red no se limita.",
  "**A stranger's message shows only its words**: a message request, from someone who has only your contact link, shows only what it says until you accept it. Its photos and files wait, not taken, and its links show no preview. See [Chat through a relay](#relay).": "**El mensaje de un desconocido muestra solo sus palabras**: una solicitud de mensaje, de alguien que solo tiene tu enlace de contacto, muestra solo lo que dice hasta que la aceptes. Sus fotos y archivos esperan sin descargarse, y sus enlaces no muestran vista previa. Mira [Chatear a través de un relay](#relay).",
  "**Photos sent as files say nothing of where they were taken**: a photo sent with **File** (JPEG, PNG, GIF or WebP) goes without where and when it was taken and the phone, as a photo does; a GIF sent as a photo keeps moving, now without its hidden notes.": "**Las fotos enviadas como archivos no dicen dónde se hicieron**: una foto enviada con **Archivo** (JPEG, PNG, GIF o WebP) va sin dónde y cuándo se hizo ni el teléfono, como una foto; un GIF enviado como foto sigue moviéndose, ahora sin sus notas ocultas.",
  "**A word of care over a stranger's first messages**: if a message request asks for a code, a PIN, a password or money, promises easy money, or its name looks like one of your contacts', **Be careful** says so above it. Erevos looks for this on your phone only, and blocks nothing. See [Chat through a relay](#relay).": "**Un aviso sobre los primeros mensajes de un desconocido**: si una solicitud de mensaje pide un código, un PIN, una contraseña o dinero, promete dinero fácil, o su nombre se parece al de uno de tus contactos, **Ten cuidado** lo dice encima. Erevos lo busca solo en tu teléfono, y no bloquea nada. Mira [Chatear a través de un relay](#relay).",
  "**Tor finds its own way through**: under **Bridges**, **Automatic** tries Tor straight, then the obfs4 bridges, then Snowflake, then your own, until one connects, and remembers for 30 days the one that worked on Wi-Fi and on mobile data. **My network is watched** makes it never try straight, and **Check my connection** says whether Tor connects, and how, never your address. See [Through Tor](#tor).": "**Tor encuentra su camino solo**: en **Puentes**, **Automático** prueba Tor directo, luego los puentes obfs4, luego Snowflake, luego los tuyos, hasta que uno conecta, y recuerda durante 30 días el que funcionó en Wi-Fi y en datos móviles. **Mi red está vigilada** hace que nunca pruebe directo, y **Comprobar mi conexión** dice si Tor se conecta, y cómo, nunca tu dirección. Mira [A través de Tor](#tor).",
  "**The bar at the top stays**: on the home screen, the bar with Erevos and its buttons no longer scrolls away with the list, and in SMS chats, as in those of the other networks, the name of the chat, its calls and who is online stay at the top while the messages scroll, as in Erevos's own chats.": "**La barra de arriba se queda**: en la pantalla de inicio, la barra con Erevos y sus botones ya no se va con la lista al desplazarla, y en los chats de SMS, como en los de las otras redes, el nombre del chat, sus llamadas y quién está en línea se quedan arriba mientras los mensajes se desplazan, como en los chats propios de Erevos.",
  "**A simpler field in Matrix and XMPP chats**: under it there is only **+**, for photos, files and the rest, and the microphone; the chat's settings are under **⋯** at the top.": "**Un campo más sencillo en los chats de Matrix y XMPP**: debajo solo hay **+**, para fotos, archivos y lo demás, y el micrófono; los ajustes del chat están arriba, en **⋯**.",
  "**Adding a contact with 8 digits**: **Pair with a code** on **New chat** lets one phone show a code of 8 digits and the other type it, said aloud or read off the screen, and you are each other's contacts, with no QR code or link to pass. The code never leaves the phones, and whoever guesses gets 3 tries. See [Chat through a relay](#relay).": "**Añadir un contacto con 8 dígitos**: **Emparejar con un código** en **Chat nuevo** deja que un teléfono muestre un código de 8 dígitos y el otro lo escriba, dicho en voz alta o leído de la pantalla, y sois contactos el uno del otro, sin código QR ni enlace que pasar. El código nunca sale de los teléfonos, y quien adivina tiene 3 intentos. Mira [Chatear a través de un relay](#relay).",
  "**A voice not your own**: in a contact's chat details, **Change my voice** sends your voice messages in that chat **Deeper** or **Higher**, as long as you spoke. The change is made on your phone before the message goes, so your own voice never leaves it. On Android 10 and later, and in browsers that make Opus themselves. See [Chat through a relay](#relay).": "**Una voz que no es la tuya**: en los detalles del chat con un contacto, **Cambiar mi voz** envía tus mensajes de voz en ese chat **Más grave** o **Más aguda**, igual de largos. El cambio se hace en tu teléfono antes de que salga el mensaje, así que tu propia voz nunca sale de él. En Android 10 y posteriores, y en navegadores que hacen Opus ellos mismos. Mira [Chatear a través de un relay](#relay).",
  "**A word of care under a short password**: setting the password of a space or the PIN of hidden chats, Erevos now says when it is short: someone who breaks into the phone's own security could guess it on computers of their own. A phrase of 4 or 5 words is far safer. It still takes a short one. See [Password lock](#lock).": "**Un aviso bajo una contraseña corta**: al poner la contraseña de un espacio o el PIN de los chats ocultos, Erevos ahora avisa cuando es corta: quien rompa la seguridad del propio teléfono podría adivinarla en ordenadores propios. Una frase de 4 o 5 palabras es mucho más segura. Aun así acepta una corta. Mira [Bloqueo con contraseña](#lock).",
  "**Groups that end**: a public group can now be a burner group, for one event. Under **It ends**, choose after a day, 3 days or 7 days, and when its time is up every member's Erevos deletes it, with its messages, photos and files, and its link stops working. See [public groups](#public-groups).": "**Grupos que terminan**: un grupo público ahora puede ser de un solo uso, para una ocasión. En **Termina**, elige tras un día, 3 días o 7 días, y cuando se acaba su tiempo el Erevos de cada miembro lo borra, con sus mensajes, fotos y archivos, y su enlace deja de funcionar. Mira [Grupos públicos](#public-groups).",
  "**A photo to see once**: under **+** in a chat or a group, **Photo to see once** sends a photo that never shows in the chat, and **Camera, to see once** one you take then. They see it once, on its own, kept out of screenshots where the phone allows, and as it closes it is deleted from their phone. It cannot be forwarded or saved. See [Chat through a relay](#relay).": "**Una foto de una sola vista**: bajo **+** en un chat o un grupo, **Foto de una sola vista** envía una foto que nunca se ve en el chat, y **Cámara, de una sola vista** una que tomas en ese momento. La ven una vez, sola, sin capturas de pantalla donde el teléfono lo permite, y al cerrarla se borra de su teléfono. No se puede reenviar ni guardar. Mira [Chatear a través de un relay](#relay).",
  "**Threads in a contact's chat too**: hold a message and choose **Reply in thread**, as in a group. The thread shows alone and what you send there answers it; **n answers in the thread** under a message opens it. See [Chat through a relay](#relay).": "**Hilos también en el chat con un contacto**: mantén pulsado un mensaje y elige **Responder en el hilo**, como en un grupo. El hilo se ve solo y lo que envías allí le responde; **n respuestas en el hilo** bajo un mensaje lo abre. Mira [Chatear a través de un relay](#relay).",
  "**A voice message in words**: hold a voice message and choose **In words**, and your phone writes out what was said, in about a hundred languages, Greek among them. The first time it downloads a speech model of 268 MB, once you say so; then everything is done on your phone, and neither the sound nor its words leave it. On Android. See [Chat through a relay](#relay).": "**Un mensaje de voz en palabras**: mantén pulsado un mensaje de voz y elige **En palabras**, y tu teléfono escribe lo que se dijo, en unos cien idiomas, el griego entre ellos. La primera vez descarga un modelo de voz de 268 MB, cuando tú lo digas; después todo se hace en tu teléfono, y ni el sonido ni sus palabras salen de él. En Android. Mira [Chatear a través de un relay](#relay).",
  "**Translate a message**: hold a message and choose **Translate**, and your phone translates it into your language, between Greek, English, German, Spanish, French and Italian. The first time for a language it downloads its translation models, of 60 to 95 MB each, once you say so; then everything is done on your phone, and neither the message nor its translation leave it. On Android. See [Chat through a relay](#relay).": "**Traducir un mensaje**: mantén pulsado un mensaje y elige **Traducir**, y tu teléfono lo traduce a tu idioma, entre griego, inglés, alemán, español, francés e italiano. La primera vez para un idioma descarga sus modelos de traducción, de 60 a 95 MB cada uno, cuando tú lo digas; después todo se hace en tu teléfono, y ni el mensaje ni su traducción salen de él. En Android. Mira [Chatear a través de un relay](#relay).",
  "**Phones nearby carry for each other from the start**: **Carry messages for others**, under **Nearby, with no internet** on **New chat**, is now on until you turn it off, so a message that cannot reach its relay finds more phones to take it there. What this phone carries is sealed: it cannot read it, nor tell who it is from or for. See [Chat with a nearby phone](#nearby).": "**Los teléfonos cercanos se llevan mensajes entre sí desde el principio**: **Llevar mensajes de otros**, bajo **Cerca, sin internet** en **Chat nuevo**, ahora está activado hasta que lo desactives, así un mensaje que no llega a su relay encuentra más teléfonos que lo lleven. Lo que lleva este teléfono va cifrado: no puede leerlo ni saber de quién es ni para quién. Mira [Chatear con un teléfono cercano](#nearby).",
  "**Last seen is when they closed Erevos**: with **Say when I open and close Erevos** on, closing Erevos, or its hidden chats, now tells those you told while it was open when it closed, so their **last seen** is that time, not when they last heard from you. And you show online only while the chats they talk to you in are open: not while your hidden chats are open instead. See [Chat through a relay](#relay).": "**La última vez es cuando cerraron Erevos**: con **Avisar cuando abro y cierro Erevos** activado, al cerrar Erevos, o sus chats ocultos, a quienes se avisó mientras estaba abierto ahora se les dice cuándo se cerró, así que su **Última vez** es esa hora, no la última vez que supieron de ti. Y solo apareces en línea mientras están abiertos los chats donde te hablan: no mientras están abiertos tus chats ocultos en su lugar. Mira [Chatear a través de un relay](#relay).",
  "**Sign in at another relay**: under **Sign in with LPHL** on New chat, **Sign in at another relay…** takes another relay's address, and the card signs in there with the accounts that relay takes; one that takes none says so, and its operator can give you an invite. See [Chat through a relay](#relay).": "**Iniciar sesión en otro relay**: debajo de **Iniciar sesión con LPHL** en Nuevo chat, **Iniciar sesión en otro relay…** toma la dirección de otro relay, y la tarjeta inicia sesión allí con las cuentas que acepta ese relay; uno que no acepta ninguna lo dice, y quien lo gestiona puede darte una invitación. Ver [Chatear a través de un relay](#relay).",
  "**Post-quantum, all the way**: between two phones on this Erevos, every message of a chat is now also locked with a fresh ML-KEM key, a new one every few dozen messages, not only at the start. So someone who records your messages today and has a quantum computer one day still cannot read them. By itself, with nothing to turn on; not in groups.": "**Poscuántico de principio a fin**: entre dos teléfonos con este Erevos, cada mensaje de un chat se cifra ahora también con una clave ML-KEM nueva, que cambia cada pocas decenas de mensajes, no solo al principio. Así, quien grabe hoy tus mensajes y algún día tenga un ordenador cuántico seguirá sin poder leerlos. Solo, sin nada que activar; no en los grupos.",
  "**The Collection asks for your password**: where the space has a password, the Collection asks for it each time it opens, and again after Erevos was away more than 30 seconds; a fingerprint or face works too. See [Collection](#collection).": "**La Colección pide tu contraseña**: donde el espacio tiene contraseña, la Colección la pide cada vez que se abre, y otra vez cuando Erevos estuvo fuera más de 30 segundos; también sirve la huella o la cara. Ver [Collection](#collection).",
  "**Messenger in its case**: in Erevos+, Messenger can now be used in its case instead of by Erevos: Meta's own Messenger page, as on a computer, closed in by Erevos with the same sign-in. Only Meta's sites load in it, links out open in your browser without Facebook's tracking marks, nothing of the sign-in stays in it once closed, and calls work in it. Choose it on the Messenger screen under **How Messenger is used here**; its chats are then not in Erevos's lists and Erevos does not notify of them. Through Tor, if Messenger goes through Tor, and then without calls.":
    "**Messenger en su funda**: en Erevos+, Messenger ahora puede usarse en su funda en lugar de por Erevos: la propia página de Messenger de Meta, como en un ordenador, encerrada por Erevos con el mismo inicio de sesión. Solo cargan los sitios de Meta, los enlaces hacia fuera se abren en tu navegador sin las marcas de rastreo de Facebook, nada del inicio de sesión queda en ella al cerrarla, y las llamadas funcionan en ella. Elígelo en la pantalla de Messenger en **Cómo se usa Messenger aquí**; sus chats entonces no están en las listas de Erevos y Erevos no avisa de ellos. A través de Tor, si Messenger va por Tor, y entonces sin llamadas.",
  "**Messenger chats you read stay read**: a Messenger chat you marked read right after Erevos+ started, while Messenger was still connecting, no longer comes back as unread; a chat whose last message is yours, sent from Messenger's own app or the web, is read; and encrypted chats you read in Messenger's app or on the web are read here too.":
    "**Los chats de Messenger que leíste siguen leídos**: un chat de Messenger que marcaste como leído justo al iniciar Erevos+, mientras Messenger aún se conectaba, ya no vuelve como no leído; un chat cuyo último mensaje es tuyo, enviado desde la app de Messenger o la web, está leído; y los chats cifrados que leíste en la app de Messenger o en la web también están leídos aquí.",
  "**Messenger in its case fits the phone, and Facebook's feed is a tap away**: in Erevos+, Messenger in its case is now laid out at the phone's width, so it reads without zooming in, and shows under Erevos's own bar, in its colours, with **←** back to Erevos and **Facebook** to see Facebook's feed in the same page. Facebook also has a card of its own in the **Services** window, beside Messenger. See [Messenger](#messenger).":
    "**Messenger en su funda cabe en el teléfono, y el feed de Facebook está a un toque**: en Erevos+, Messenger en su funda se ajusta ahora al ancho del teléfono, así que se lee sin ampliar, y se muestra bajo la propia barra de Erevos, con sus colores, con **←** para volver a Erevos y **Facebook** para ver el feed de Facebook en la misma página. Facebook también tiene su propia tarjeta en la ventana **Servicios**, junto a Messenger. Mira [Messenger](#messenger).",
  "**Messenger in its case asks for the PIN once**: in Erevos+, what Meta's page keeps now stays in the case between openings, apart from every other page, so Meta knows your phone again and no longer asks for the PIN of your encrypted chats each time you open it. It goes when you sign out of Messenger, or when another account opens the case. See [Messenger](#messenger).":
    "**Messenger en su funda pide el PIN una sola vez**: en Erevos+, lo que guarda la página de Meta ahora se queda en la funda entre una apertura y otra, aparte de cualquier otra página, así que Meta reconoce tu teléfono y ya no pide el PIN de tus chats cifrados cada vez que la abres. Se borra cuando cierras la sesión de Messenger o cuando otra cuenta abre la funda. Consulta [Messenger](#messenger).",
  "**Messenger in its case wears your whole look**: in Erevos+, Meta's own Messenger page in its case now takes your look: its colours, dark or light as Erevos is, the shape of your bubbles (round, square or a line), your text size, your style's letters, and what lies behind your screens (a wallpaper, Neon's grid, Paper's lines and the others), and it changes with your look even while it is open. A photo of your own stays in Erevos: there the page shows a soft gradient instead. Where Meta changes its page, parts of it may keep Meta's look. See [Messenger](#messenger).":
    "**Messenger en su funda lleva todo tu aspecto**: en Erevos+, la propia página de Messenger de Meta en su funda toma ahora tu aspecto: sus colores, oscura o clara como Erevos, la forma de tus burbujas (redondas, cuadradas o una línea), tu tamaño de texto, las letras de tu estilo y lo que hay detrás de tus pantallas (un fondo, la cuadrícula de Neon, las líneas de Paper y los demás), y cambia con tu aspecto incluso mientras está abierta. Una foto tuya se queda en Erevos: ahí la página muestra en su lugar un degradado suave. Donde Meta cambie su página, algunas partes pueden conservar el aspecto de Meta. Consulta [Messenger](#messenger).",
  "**Messenger in its case tells you of new messages**: in Erevos+, when you use Messenger in its case, Erevos now tells you of its new messages as it does of other chats, even if you never opened the case. A chat with messages not read shows on home until it is read, and tapping it opens it in the case; while the case is open, Erevos tells of nothing, as the page shows it. See [Messenger](#messenger).":
    "**Messenger en su funda te avisa de los mensajes nuevos**: en Erevos+, cuando usas Messenger en su funda, Erevos ahora te avisa de sus mensajes nuevos como de los demás chats, aunque nunca hayas abierto la funda. Un chat con mensajes sin leer aparece en el inicio hasta que se lee, y al tocarlo se abre en la funda; mientras la funda está abierta, Erevos no avisa, porque la página ya lo muestra. Consulta [Messenger](#messenger).",
};
